-- ============================================================
--  RxScreen — ฐานกฎ (rule base) export จาก Firestore → SQL seed
--  ใช้ import เข้าฐาน rxscreen สำหรับระบบ on-prem (ไม่ต้องเริ่มจากศูนย์)
--  แต่ละแถว: doc_id + icode(ถ้ามี) + data(JSON เก็บทุก field ครบ)
--  แอปอ่าน JSON แล้ว map เป็น interface เดิม (DrugMaster/LabRule/...) เหมือนตอนใช้ Firestore
--  charset utf8mb4 (มีภาษาไทย/สัญลักษณ์ ⁺ ≥ ฯลฯ)
-- ============================================================
SET NAMES utf8mb4;
CREATE DATABASE IF NOT EXISTS rxscreen CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE rxscreen;

-- ===== DRUG_MASTER (534) =====
DROP TABLE IF EXISTS rxrule_drug_master;
CREATE TABLE rxrule_drug_master (
  doc_id VARCHAR(80) PRIMARY KEY,
  icode VARCHAR(40),
  data JSON,
  KEY idx_icode (icode)
);

-- ===== LAB_RULES (224) =====
DROP TABLE IF EXISTS rxrule_lab_rules;
CREATE TABLE rxrule_lab_rules (
  doc_id VARCHAR(80) PRIMARY KEY,
  icode VARCHAR(40),
  data JSON,
  KEY idx_icode (icode)
);

