INSERT INTO rxrule_had_rules (doc_id, icode, data) VALUES ('adenosine', NULL, '{"drug_name":"Adenosine 3 mg/mL","dilution":"ไม่ต้องเจือจาง · Flush NSS 20 mL ทันทีหลังฉีด","antidote":"ไม่มี specific antidote · อาการหายเองเนื่องจาก half-life < 10 วินาที","max_dose":"0.3 mg/kg/dose (เด็ก) / 12 mg/dose (ผู้ใหญ่)","updatedAt":"2026-06-01T15:54:37.479Z","drug_key":"adenosine","route_note":"IV push เท่านั้น · Double syringe technique · ฉีดข้อพับแขนขวา ยกแขน · ห้ามแช่เย็น (ตกตะกอน)","full_note":"Half-life < 10 วินาที อาการหายเองได้ · ห้ามใน 2nd/3rd AV block / Asthma / COPD · Theophylline/Caffeine ลดฤทธิ์ · Dipyridamole เพิ่มฤทธิ์ (ลดขนาด 75%) · เตรียม crash cart + defibrillator ก่อนให้ทุกครั้ง · สีเปลี่ยน/ตะกอน = ทิ้ง","max_conc":"ไม่เจือจาง (3 mg/mL)","max_rate":"IV push < 2 วินาที (ห้ามช้า)"}');
INSERT INTO rxrule_had_rules (doc_id, icode, data) VALUES ('adrenaline', NULL, '{"max_rate":"IV infusion max 10 mcg/min (ผู้ใหญ่)","max_conc":"IV push: 1:10,000 (100 mcg/mL) · Infusion: 4 mcg/mL (peripheral)","full_note":"LASA สูงมาก: 1:1,000 vs 1:10,000 ต่างกัน 10 เท่า · Extravasation → necrosis ฉีด Phentolamine 5-10 mg รอบๆ ทันที · ตรวจ IV site ทุก 1 ชม. · สีเปลี่ยน/ตะกอน = ทิ้ง · คงตัว 24 ชม. ป้องกันแสง · Non-selective BB + Adrenaline = HTN วิกฤต","route_note":"IM ที่ต้นขาด้านนอก (Anaphylaxis) · IV infusion ผ่าน large vein + infusion pump · ห้าม IV push 1:1,000 โดยตรง (fatal) · ห้ามผสม NaHCO3 / Aminophylline","updatedAt":"2026-06-01T15:54:37.479Z","drug_key":"adrenaline","max_dose":"Cardiac arrest: 1 mg/dose · Anaphylaxis IM: 0.5 mg · Infusion: 10 mcg/min","antidote":"Extravasation: Phentolamine 5-10 mg ใน NSS 10 mL infiltrate รอบๆ ทันที ภายใน 12 ชม.","drug_name":"Adrenaline (Epinephrine) 1 mg/mL","dilution":"IV push ต้องเจือจาง 1:10,000 (ยา 1 mL + NSS 9 mL) · Infusion: D5W หรือ NSS"}');
INSERT INTO rxrule_had_rules (doc_id, icode, data) VALUES ('amiodarone', NULL, '{"max_rate":"Rapid phase: 150 mg over 10 นาที · Slow: 33 mL/hr · Maintenance: 17 mL/hr","max_conc":"2 mg/mL (peripheral) · >2 mg/mL = central line เท่านั้น","full_note":"แก้ K⁺ + Mg²⁺ ก่อนให้เสมอ (TdP risk) · QTc > 500 ms = ระวังสูง · Half-life 40-55 วัน DDI ยังมีหลายสัปดาห์หลังหยุดยา · Monitor TSH + LFT ทุก 3-6 เดือน (ระยะยาว) · Digoxin: ลด dose 50% · Warfarin: ลด 30-50% · Simvastatin: ห้ามร่วม (rhabdo)","route_note":"ห้ามผสม: NSS, Heparin, Aminophylline, Cefazolin, Furosemide, Digoxin, NaHCO3, MgSO4, Augmentin, Imipenem, Ertapenem","updatedAt":"2026-06-01T15:54:37.479Z","drug_key":"amiodarone","max_dose":"VF/VT: 300 mg IV push · Infusion: 2.1 g/day","antidote":"ไม่มี specific antidote · TdP → MgSO4 IV · หยุดยา + Vasopressor ถ้าจำเป็น","dilution":"D5W เท่านั้น — ห้าม NSS (ตกตะกอน) · Glass หรือ Polyolefin container · ห้าม PVC > 2 ชม.","drug_name":"Amiodarone 150 mg/3 mL"}');
INSERT INTO rxrule_had_rules (doc_id, icode, data) VALUES ('atropine', NULL, '{"updatedAt":"2026-06-01T15:54:37.479Z","drug_key":"atropine","max_rate":"IV push เร็ว 1-3 วินาที (ห้ามช้า → paradoxical bradycardia)","max_conc":"ไม่เจือจาง","full_note":"Organophosphate: ให้ถึง atropinization (ปากแห้ง ตาพร่า ปัสสาวะลำบาก ≠ toxicity) · ระวัง urinary retention (สูงอายุ/BPH) · Monitor I/O ทุก 2-4 ชม.","route_note":"IV push เร็ว ห้ามช้า · ห้ามใน Tachycardia / Narrow angle glaucoma · Min dose เด็ก 0.1 mg (น้อยกว่านี้ = paradoxical bradycardia)","drug_name":"Atropine Sulfate 0.6 mg/mL","dilution":"ไม่ต้องเจือจาง · ET route: เจือจาง NSS ให้ได้ 1-5 mL","max_dose":"Bradycardia: 2 mg (ผู้ใหญ่) · Organophosphate: 50 mg/day (ไม่จำกัดถ้ายังมี secretion)","antidote":"Atropine toxicity: Physostigmine 1-2 mg IV slowly (ผู้ใหญ่) / 0.02 mg/kg (เด็ก) — เฉพาะ severe life-threatening symptoms"}');
INSERT INTO rxrule_had_rules (doc_id, icode, data) VALUES ('calcium_gluconate', NULL, '{"antidote":"Hypercalcemia: NSS 200-300 mL/hr + Furosemide 40-80 mg IV · Calcitonin/Bisphosphonate ถ้ารุนแรง","max_dose":"Hypercalcemic tetany ผู้ใหญ่: 3 g/dose · เด็ก: 100-200 mg/kg/dose","dilution":"IV push ไม่ต้องเจือจาง · Infusion: เจือจางใน D5W หรือ NSS","drug_name":"10% Calcium Gluconate 1 g/10 mL","route_note":"ห้ามฉีด IM/SC เด็ดขาด (tissue necrosis รุนแรง) · ห้ามผสม Phosphate / Bicarbonate / Sulfate · ห้าม Ceftriaxone + Ca IV ในทารกแรกเกิด (FDA Black Box — fatal)","full_note":"Ca > 10.5 mg/dL = ห้ามให้ · สงสัย Digoxin toxicity = ห้ามให้ · Ca × P product > 55 = ระวัง calcification · ตรวจ IV site ทุก 1 ชม. (extravasation → necrosis) · ห้ามแช่เย็น (ตกตะกอน) · Ca gluconate ≠ Ca chloride (ต่างกัน 3 เท่า)","max_rate":"IV push: ≤ 200 mg/min (ผู้ใหญ่) · เด็ก ≤ 100 mg/min · Infusion: ≤ 240 mg/kg/hr","max_conc":"50 mg/mL","drug_key":"calcium_gluconate","updatedAt":"2026-06-01T15:54:37.479Z"}');
INSERT INTO rxrule_had_rules (doc_id, icode, data) VALUES ('diazepam', NULL, '{"drug_name":"Diazepam 10 mg/2 mL","dilution":"ห้าม IV infusion (ตกตะกอน) · IV push เท่านั้น · ห้ามผสมกับยาอื่น","antidote":"Flumazenil 0.2 mg IV q1 นาที จนตอบสนอง / max 1 mg · ระวัง re-sedation และ seizure threshold ลดลงในผู้ป่วย seizure","max_dose":"Status epilepticus ผู้ใหญ่: 30 mg/episode · เด็ก > 5y: 10 mg/episode · เด็ก < 5y: 5 mg/episode","updatedAt":"2026-06-01T15:54:37.479Z","drug_key":"diazepam","full_note":"Flumazenil (antidote) half-life สั้นกว่า Diazepam → re-sedation เกิดได้ หลัง antidote ต้อง Monitor ต่อ · Opioids + Diazepam = respiratory arrest (FDA Black Box) · เตรียม Flumazenil + BVM + O2 ก่อนให้ทุกครั้ง","route_note":"IV push เท่านั้น — ห้าม IV infusion · ห้ามใน < 30 วัน (Benzyl alcohol) · อัตรา IV push ผู้ใหญ่ ≤ 5 mg/min","max_rate":"IV push ผู้ใหญ่: ≤ 5 mg/min · เด็ก: ≤ 1-2 mg/min","max_conc":"ไม่เจือจาง (IV push) — ห้ามเจือจาง (ตกตะกอน)"}');
INSERT INTO rxrule_had_rules (doc_id, icode, data) VALUES ('digoxin', NULL, '{"updatedAt":"2026-06-01T15:54:37.479Z","drug_key":"digoxin","route_note":"ตรวจ K⁺ ก่อน — K < 3.5 = ห้ามให้ · วัด HR ก่อน — HR < 60 = ปรึกษาแพทย์ · ห้ามให้ IM · ห้ามใน VF / Digoxin toxicity","full_note":"Therapeutic level: 0.5-2 ng/mL · HF target: 0.5-0.9 ng/mL · Toxic: > 2 ng/mL · เจาะ trough 6-8 ชม. หลัง dose · xanthopsia (เห็นสีเหลือง-เขียว) = early toxicity · Amiodarone: ลด Digoxin 50% · Clarithromycin: ลดขนาด + monitor level","max_conc":"ไม่เจือจาง หรือ เจือจาง 1:4 (push) / 1:250 (infusion)","max_rate":"IV slowly push ≥ 5-10 นาที · Infusion: 15-30 นาที","dilution":"NSS / D5W / SWFI / Ringer lactate · ห้าม IV push เร็ว","drug_name":"Digoxin 0.5 mg/2 mL Injection","antidote":"Digoxin Immune Fab (Digibind): dose (vials) = (Level ng/mL × BW kg) / 100 · Indication: K⁺ > 5 + toxicity / VF·VT / bradycardia refractory / ingestion > 10 mg","max_dose":"Loading ผู้ใหญ่: 0.5-1 mg · Maintenance: 0.1-0.4 mg/day · เด็ก: ดูตามอายุ"}');
INSERT INTO rxrule_had_rules (doc_id, icode, data) VALUES ('dobutamine', NULL, '{"max_rate":"เริ่ม 0.5-1 mcg/kg/min → ปรับตาม response","max_conc":"5 mg/mL","full_note":"AF + RVR: ให้ Digoxin ก่อน แล้วค่อยให้ Dobutamine · ตรวจ IV site ทุก 1 ชม. (extravasation → necrosis) · K⁺ ควรอยู่ 3.5-5.5 mEq/L ตลอดการให้ · MAOIs / Linezolid = CONTRAINDICATED · Ergotamine = CONTRAINDICATED","route_note":"Infusion pump เท่านั้น · Large vein · ห้ามหยุดทันที (Taper ช้าๆ) · แก้ Hypovolemia ก่อนเสมอ · สีชมพู = oxidation ปกติ (ยังใช้ได้)","updatedAt":"2026-06-01T15:54:37.479Z","drug_key":"dobutamine","max_dose":"40 mcg/kg/min","antidote":"ไม่มี specific antidote · ลด rate / หยุดยา + ดูแลตามอาการ · Tachyarrhythmia: พิจารณา Cardioselective β-blocker","dilution":"D5W / D5S/2 / D5S / NSS / LRS · 2:1 = ยา 16 mL + NSS 84 mL · 4:1 = ยา 32 mL + NSS 68 mL · ห้ามผสม NaHCO3","drug_name":"Dobutamine HCl 250 mg/20 mL"}');
INSERT INTO rxrule_had_rules (doc_id, icode, data) VALUES ('dopamine', NULL, '{"drug_name":"Dopamine 250 mg/10 mL","dilution":"NSS / D5W / LRS · 1:1 = 1 mg/mL (250 mg ใน 250 mL) · 2:1 = 2 mg/mL · ห้ามผสม NaHCO3 / Ampicillin / Aminophylline / Penicillin G","antidote":"Extravasation: Phentolamine 5-10 mg ใน NSS 10 mL infiltrate รอบๆ ทันที","max_dose":"50 mcg/kg/min","updatedAt":"2026-06-01T15:54:37.479Z","drug_key":"dopamine","route_note":"Infusion pump เท่านั้น · Central vein preferred · ห้ามหยุดทันที (Taper) · สีเหลืองเข้ม/น้ำตาล = ทิ้ง · ห้ามใช้ยาที่เปลี่ยนสี","full_note":"Low 1-3 mcg/kg/min = renal · Medium 3-10 = cardiac · High > 10 = vasopressor · Phenytoin IV + Dopamine IV = cardiac arrest (ห้ามให้ร่วม) · Extravasation → necrosis: Phentolamine · MAOIs: ลด dose เหลือ 10% · ตรวจ IV site ทุก 1 ชม.","max_conc":"Central line 4:1 = ยา 16 mL + NSS 84 mL","max_rate":"Initial: 2-10 mcg/kg/min · ปรับทีละ 1-4 mcg/kg/min q10-30 นาที"}');
INSERT INTO rxrule_had_rules (doc_id, icode, data) VALUES ('enoxaparin', NULL, '{"updatedAt":"2026-06-01T15:54:37.479Z","drug_key":"enoxaparin","route_note":"Platelet < 100,000 = หยุดยา (HIT) · CrCl < 30 = ปรับขนาด · Spinal/Epidural: รอ ≥ 12 ชม. ก่อนทำ neuraxial procedure","full_note":"HIT type II: Plt ลด > 50% วันที่ 4-14 = หยุดทันที switch to Argatroban · Anti-Xa target: 0.5-1 IU/mL (q12h) / 1-2 IU/mL (q24h) · CrCl < 15 = หลีกเลี่ยง · ตรวจ CBC หลัง 7 วัน · K⁺ monitor (hyperkalemia จาก aldosterone suppression)","max_conc":"SC เท่านั้น (ยกเว้น STEMI)","max_rate":"SC injection — ไม่มี IV rate (ยกเว้น STEMI protocol)","dilution":"ห้ามฉีด IV · SC ท้องส่วนล่าง ห่างสะดือ > 5 cm · ห้ามไล่ฟองอากาศออกก่อนฉีด (สูญเสียยา) · ห้ามนวดบริเวณฉีด","drug_name":"Enoxaparin 6,000 IU/0.6 mL","antidote":"Protamine sulfate 1 mg ต่อ 1 mg enoxaparin · Neutralize ~60% anti-Xa · ถ้าผ่านไปแล้ว > 8 ชม. อาจไม่จำเป็น","max_dose":"Treatment: 1.5 mg/kg q24h · Prophylaxis: 40 mg q24h"}');
INSERT INTO rxrule_had_rules (doc_id, icode, data) VALUES ('kcl', NULL, '{"route_note":"ห้าม IV push / IV bolus เด็ดขาด (cardiac arrest) · ห้ามเติมในขวดที่กำลัง infuse · Infusion pump เท่านั้น · K⁺ > 5 = ห้ามให้","full_note":"ISMP Top Alert — Never give undiluted IV · Mg < 1.5 mg/dL = แก้ก่อน (refractory hypokalemia) · Urine output < 30 mL/hr = HOLD · ตรวจ K⁺ ทุก 2-4 ชม. · EKG monitor ถ้า > 10 mEq/hr · K⁺ > 5 + EKG changes = emergency (Ca gluconate + RI/D50 + NaHCO3)","max_rate":"≤ 10 mEq/hr (peripheral) · ≤ 40 mEq/hr (central + EKG monitor)","max_conc":"≤ 100 mEq/L (peripheral) · 200-400 mEq/L (central)","drug_key":"kcl","updatedAt":"2026-06-01T15:54:37.479Z","antidote":"Hyperkalemia: (1) Ca gluconate 1-2 g IV slow (cardiac protection) · (2) RI 10U + D50% 50 mL · (3) NaHCO3 50 mEq · (4) Furosemide · (5) Kayexalate · (6) Dialysis","max_dose":"200 mEq/24 hr (ผู้ใหญ่) · เด็ก: 3-4 mEq/kg/day","dilution":"ต้องเจือจาง D5W / NSS ก่อนเสมอ · พลิกขวดหลายครั้งให้ผสมเข้ากันดี (KCl หนักกว่า)","drug_name":"KCl 20 mEq/10 mL Injection"}');
INSERT INTO rxrule_had_rules (doc_id, icode, data) VALUES ('magnesium_sulfate', NULL, '{"dilution":"NSS / D5W · ห้ามแช่เย็น + แช่แข็ง (ตกตะกอน) · ห้ามผสม: Dobutamine, Amiodarone, Pantoprazole, Fat emulsion, Clindamycin, Amphotericin B","drug_name":"MgSO4 10% (1 g/10 mL) และ 50% (1 g/2 mL)","antidote":"10% Calcium gluconate 1-2 g IV slow push (5-10 mEq) ทันทีที่มีอาการ respiratory depression หรือ loss DTR","max_dose":"Eclampsia: 30-40 g/day · เด็ก: 200 mg/kg/day · Single dose: 4-8 g","updatedAt":"2026-06-01T15:54:37.479Z","drug_key":"magnesium_sulfate","route_note":"เตรียม 10% Ca gluconate ไว้ข้างเตียงทุกครั้ง · กฎ 3 ข้อก่อน dose ถัดไป: DTR present? + RR ≥ 12? + UO ≥ 0.5 mL/kg/hr? · ถ้า \'ไม่\' = HOLD","full_note":"Toxicity: > 7 mg/dL = loss DTR → > 10 = respiratory depression → > 15 = cardiac arrest · CrCl < 25 = CONTRAINDICATED · Neuromuscular blockers (vecuronium): ลด NMB dose 30-50% · ห้ามแช่เย็น","max_conc":"IV: ต้องเจือจางให้ < 10% ก่อนเสมอ · IM ผู้ใหญ่: ≤ 50% · เด็ก: ≤ 20%","max_rate":"IV push ≤ 150 mg/min · IV infusion: 1-4 g/hr · ยกเว้น Eclampsia ที่มีชัก"}');
INSERT INTO rxrule_had_rules (doc_id, icode, data) VALUES ('naloxone', NULL, '{"route_note":"ตัวยาเองเป็น antidote opioid · เป้าหมาย RR > 12 — ไม่ต้องให้ตื่นสนิท (acute withdrawal) · Monitor ≥ 2-4 ชม. (re-narcotization) · ไม่มีผลต่อ BZD / Barbiturate","full_note":"Half-life 30-90 นาที < กว่า opioids ส่วนใหญ่ → Re-narcotization หลัง antidote ต้อง Monitor ต่อ · Opioid-dependent: ให้ช้าๆ ขนาดน้อย (prevent acute withdrawal) · Buprenorphine: ต้องการ naloxone dose สูงมาก (high receptor affinity)","max_rate":"IV push > 30 วินาที","max_conc":"Infusion: 4 mcg/mL (0.4 mg ใน 100 mL NSS/D5W)","drug_key":"naloxone","updatedAt":"2026-06-01T15:54:37.479Z","antidote":"ตัวยาเองเป็น antidote สำหรับ opioid toxicity","max_dose":"ผู้ใหญ่: 2 mg/dose · เด็ก: 0.1 mg/dose · Infusion: 0.4-0.8 mg/hr","drug_name":"Naloxone 400 mcg/mL","dilution":"ไม่เจือจาง (IV push opioid overdose) · Infusion: NSS หรือ D5W"}');
INSERT INTO rxrule_had_rules (doc_id, icode, data) VALUES ('nicardipine', NULL, '{"updatedAt":"2026-06-01T15:54:37.479Z","drug_key":"nicardipine","full_note":"ลด BP ช้าๆ ใน stroke: ลด MAP ≤ 25% ใน 1 ชม. แรกเท่านั้น · MgSO4 + Nicardipine = additive hypotension มาก (eclampsia patients) · Cyclosporine + Nicardipine: ↑ cyclosporine level 2-3 เท่า (monitor level)","route_note":"Infusion pump เสมอ · เปลี่ยน peripheral IV site ทุก 12 ชม. · เปลี่ยน central line site ทุก 24 ชม. · หยุดถ้า BP < 90/60 หรือ HR > 120","max_rate":"เริ่ม 5 mg/hr → เพิ่ม 2.5 mg/hr ทุก 15 นาที · เมื่อได้ผล: ลดเหลือ 3 mg/hr","max_conc":"0.2 mg/mL (1:5 = ยา 2 amp + 80 mL) · 0.1 mg/mL (1:10 = ยา 1 amp + 90 mL)","dilution":"D5W / NSS / D5S / D5S/2 · ห้ามผสม NaHCO3 / LRS / Furosemide / Heparin / Ampicillin / Diazepam","drug_name":"Nicardipine HCl 10 mg/10 mL","antidote":"ไม่มี specific antidote · Hypotension: หยุดยา + NSS IV bolus + Trendelenburg · Calcium gluconate IV อาจช่วยได้บ้าง","max_dose":"Hypertensive crisis: 15 mg/hr · Stable angina: 4 mg/hr"}');
INSERT INTO rxrule_had_rules (doc_id, icode, data) VALUES ('nitroglycerin', NULL, '{"updatedAt":"2026-06-01T15:54:37.479Z","drug_key":"nitroglycerin","max_rate":"เริ่ม 5-10 mcg/min ปรับทีละ 5-10 mcg/min q3-5 นาที","max_conc":"ขึ้นกับ dilution · ระวัง tolerance","full_note":"ถามประวัติ PDE5 inhibitors ก่อนให้ทุกครั้ง · Methemoglobinemia (ใช้นาน/dose สูง) → Methylene blue 1-2 mg/kg IV · ห้ามหยุดทันทีใน angina (rebound) · ปวดหัว = ADR ปกติ มักดีขึ้นใน 2 สัปดาห์","route_note":"ห้ามใช้ร่วม Sildenafil/Tadalafil/Vardenafil เด็ดขาด (fatal hypotension) · Tolerance เกิดใน 24-48 ชม. → ต้อง nitrate-free period 10-12 ชม./วัน · SBP < 90 = ห้ามให้","drug_name":"Nitroglycerin (NTG) 50 mg/10 mL","dilution":"D5W หรือ NSS · Glass / Polyolefin container เท่านั้น — ห้าม PVC (ยาดูดซึม 40-80%) · ห่อด้วย aluminum foil ป้องกันแสง","max_dose":"Titrate ตาม hemodynamics · ทั่วไป 5-200 mcg/min","antidote":"Methemoglobinemia: Methylene blue 1-2 mg/kg IV slow 5 นาที · Hypotension: หยุดยา + NSS IV bolus + Trendelenburg"}');
INSERT INTO rxrule_had_rules (doc_id, icode, data) VALUES ('norepinephrine', NULL, '{"route_note":"Central line preferred · Peripheral ≤ 12 ชม. เท่านั้น · Infusion pump เท่านั้น · ห้ามหยุดทันที (Taper) · ห้ามผสม NaHCO3 / Barbiturates","full_note":"แก้ Hypovolemia ก่อนเสมอ · Extravasation → rapid necrosis: Phentolamine ทันที · ตรวจ peripheral perfusion + IV site บ่อยๆ · TCAs: เพิ่มปฏิกิริยา 2-10 เท่า (ระวัง) · MAOIs / Linezolid = CONTRAINDICATED · Ergotamine = CONTRAINDICATED","max_conc":"Peripheral: 16 mcg/mL · Central: ≤ 64 mcg/mL","max_rate":"Titrate ตาม MAP target","updatedAt":"2026-06-01T15:54:37.479Z","drug_key":"norepinephrine","antidote":"Extravasation: Phentolamine 5-10 mg ใน NSS 10 mL infiltrate รอบๆ ทันที ภายใน 12 ชม.","max_dose":"ผู้ใหญ่: เริ่ม 8-12 mcg/min · Maintenance: 2-4 mcg/min · เด็ก max: 2 mcg/kg/min","drug_name":"Norepinephrine 4 mg/4 mL","dilution":"D5W เท่านั้น — ห้าม NSS เดี่ยว (oxidation → inactivation) · 4:250 = ยา 8 mL + D5W 482 mL · 4:100 = ยา 4 mL + D5W 96 mL"}');
INSERT INTO rxrule_had_rules (doc_id, icode, data) VALUES ('oxytocin', NULL, '{"dilution":"D5W / D5S/2 / NSS / LRS · 10 units ใน 1,000 mL","drug_name":"Oxytocin 10 IU/mL","antidote":"Water intoxication: หยุดยา + จำกัดน้ำ + Furosemide 20-40 mg IV + ตรวจ Na⁺ + Diazepam ถ้าชัก","max_dose":"Labor induction: 6 milliunits/min · หลังคลอด: 40 milliunits/min","drug_key":"oxytocin","updatedAt":"2026-06-01T15:54:37.479Z","route_note":"Infusion pump เสมอ · ห้ามให้ร่วม Prostaglandins (รอ ≥ 6-8 ชม.) · Monitor I/O ทุก 1 ชม. (water intoxication) · Contraction > 5 ครั้ง/10 นาที = หยุดยาทันที","full_note":"Water intoxication: Na < 130 = หยุดยา + Furosemide · จำกัดน้ำ ≤ 3 L/24 ชม. · Monitor FHR continuous · ตรวจ Na⁺ ถ้า I/O positive มาก · Pregnancy Cat C (ใช้ใน obstetric context)","max_rate":"Labor: เริ่ม 0.5-1 milliunit/min เพิ่มทีละ 1-2 q30-60 นาที · หลังคลอด: 20-40 milliunits/min","max_conc":"10 units/L (10 milliunits/mL)"}');
INSERT INTO rxrule_had_rules (doc_id, icode, data) VALUES ('phenytoin', NULL, '{"drug_name":"Phenytoin 250 mg/5 mL Injection","dilution":"NSS เท่านั้น — ห้ามผสม Dextrose (ตกตะกอนทันที) · คงตัวหลังเจือจาง 4 ชม. เท่านั้น · ห้ามผสมกับยาอื่น","antidote":"ไม่มี specific antidote · Hypotension → ลด rate · Bradycardia → Atropine · Purple Glove Syndrome → หยุด + ปรึกษาศัลยกรรม","max_dose":"Loading: 15-20 mg/kg (max 1,500 mg) · Maintenance: 5-6 mg/kg/day","drug_key":"phenytoin","updatedAt":"2026-06-01T15:54:37.479Z","route_note":"Flush NSS 30 mL ก่อน/หลังให้ยาทุกครั้ง · ห้ามให้สายเดียวกับยาอื่น · ตรวจ IV site ทุก 1 ชม. (Purple Glove Syndrome)","full_note":"Albumin < 3 g/dL = ต้องใช้ Free phenytoin / Winter-Tozer correction · Therapeutic: 10-20 mcg/mL · Toxic: > 20 · Meropenem/Carbapenems ลด Phenytoin level · Valproate: ตรวจ free level · Fluconazole: ↑ level 50-75%","max_rate":"≤ 50 mg/min (ผู้ใหญ่) · ≤ 20 mg/min (สูงอายุ/โรคหัวใจ) · ≤ 3 mg/kg/min (เด็ก)","max_conc":"10 mg/mL ใน NSS"}');
INSERT INTO rxrule_had_rules (doc_id, icode, data) VALUES ('sodium_bicarbonate', NULL, '{"route_note":"ห้ามผสมสายเดียวกับ: Ca gluconate / Dopamine / Adrenaline / NE / Amiodarone / Dobutamine / Phenytoin / Nicardipine · Flush NSS ก่อน/หลัง · ห้ามใน Respiratory acidosis","full_note":"pH > 7.45 = ห้ามให้ (alkalosis แล้ว) · ใน CPR ไม่ใช้ routine (AHA 2020) — ใช้เฉพาะ severe acidosis pH < 7.1 / hyperkalemia / TCA toxicity · Overcorrection → alkalosis → hypokalemia + tetany · Na⁺ > 145 = ระวัง","max_conc":"7.5% NaHCO3 = 0.893 mEq/mL · เจือจาง 1:1 ก่อนให้ทารก","max_rate":"ช้า 30-60 นาที (ยกเว้น cardiac arrest) · ทารก: ห้าม IV push เร็ว (IVH risk)","updatedAt":"2026-06-01T15:54:37.479Z","drug_key":"sodium_bicarbonate","antidote":"Alkalosis overcorrection: หยุดยา + Ammonium chloride (ปรึกษาแพทย์)","max_dose":"Metabolic acidosis: 1-2 mEq/kg/dose · Cardiac arrest: 1 mEq/kg","dilution":"D5W / NSS · เจือจาง 1:1 ในทารก (ลด osmolality) · ห้ามผสมกับยาเกือบทุกชนิด","drug_name":"Sodium Bicarbonate 7.5% (3.75 g/50 mL)"}');
INSERT INTO rxrule_had_rules (doc_id, icode, data) VALUES ('streptokinase', NULL, '{"max_conc":"ละลายด้วย NSS 5-10 mL + เจือจางใน NSS/D5W 100 mL","max_rate":"STEMI: infuse over ≥ 60 นาที · ห้ามให้เร็ว","route_note":"ห้ามใช้ถ้าเคยได้ SK < 1 ปี (antibody → anaphylaxis + ลด efficacy) · BP > 200/100 = CONTRAINDICATED · เตรียม Adrenaline ไว้ข้างเตียงตลอดเวลา","full_note":"Monitor TT ที่ 4 ชม. (target 2-5× baseline) · CBC + PT + aPTT + Fibrinogen ที่ baseline + 4 ชม. · เลือดออก = หยุดยา + FFP/Cryoprecipitate + Tranexamic acid · เก็บในตู้เย็น 2-8°C ก่อนใช้","updatedAt":"2026-06-01T15:54:37.479Z","drug_key":"streptokinase","max_dose":"STEMI: 1,500,000 IU over 60 นาที · DVT loading: 250,000 IU/30 นาที","antidote":"Bleeding: หยุดยา + กด + FFP 15-30 mL/kg + Cryoprecipitate (แก้ fibrinogen) + Tranexamic acid (Antifibrinolytic)","dilution":"ฉีดสารละลายช้าๆ ด้านในผนังขวด · เอียงกลิ้งช้าๆ — ห้ามเขย่า (เกิดฟอง → inactivation) · ห้ามผสมยาอื่นทุกชนิด","drug_name":"Streptokinase 1,500,000 IU/vial"}');
INSERT INTO rxrule_had_rules (doc_id, icode, data) VALUES ('terbutaline', NULL, '{"route_note":"ห้ามใช้ > 48-72 ชม. (FDA Warning: maternal cardiac events) · HR > 120 = หยุดยาทันที · Monitor K⁺ + DTX + FHR ตลอด · ห้ามใน Non-selective β-blocker (CONTRAINDICATED)","full_note":"β2 → K⁺ ลด (intracellular shift) → ตรวจ K⁺ ทุก 2-4 ชม. · DTX > 200 = ระวังใน GDM · Pulmonary edema ใน preterm labor (เจ็บแน่นหน้าอก + หายใจลำบาก = หยุดทันที) · Corticosteroid + Terbutaline = additive hypokalemia","max_rate":"IV infusion เริ่ม 2.5-10 mcg/min เพิ่มทุก 10-20 นาที","max_conc":"ขึ้นกับปริมาณ","drug_key":"terbutaline","updatedAt":"2026-06-01T15:54:37.479Z","antidote":"ไม่มี specific antidote · Cardioselective β-blocker ถ้า severe tachycardia · หยุดยา + Oxygen + ดูแลตามอาการ","max_dose":"IV infusion: max 80 mcg/min · SC: 0.25 mg/dose × 3 ใน 3 ชม.","drug_name":"Terbutaline Sulfate 0.5 mg/mL","dilution":"D5W / 0.45% NSS / NSS · SC: ไม่เจือจาง"}');
INSERT INTO rxrule_had_rules (doc_id, icode, data) VALUES ('warfarin', NULL, '{"route_note":"LASA: 3 mg (สีฟ้า) ≠ 5 mg (สีชมพู) — ตรวจสีก่อนทุกครั้ง · INR > 4.5 = HOLD + Vit K · INR < 1.5 = Subtherapeutic + แจ้งแพทย์ · Pregnancy Cat X — ห้ามใช้","full_note":"DDI มากที่สุดในบรรดายาทั้งหมด · ออกฤทธิ์ช้า 3-5 วัน (bridging ด้วย LMWH) · Rifampicin: ↓ INR มาก · Fluconazole/Amiodarone: ↑ INR มาก · Vit K ในอาหารกินสม่ำเสมอ (ไม่ต้องงด) · CYP2C9/VKORC1 genotype ช่วยเลือก dose","max_rate":"Oral — ไม่มี IV rate","max_conc":"Oral tablet","drug_key":"warfarin","updatedAt":"2026-06-01T15:54:37.479Z","antidote":"Vit K1 oral 1-10 mg · Vit K1 IV slow 5-10 mg · FFP 15-30 mL/kg (bleeding) · 4-Factor PCC (major bleeding) · rFVIIa (intracranial hemorrhage)","max_dose":"ปรับขนาดตาม INR target · ทั่วไป 2-10 mg/day","drug_name":"Warfarin 3 mg (ฟ้า) / 5 mg (ชมพู)","dilution":"Oral เท่านั้น"}');
INSERT INTO rxrule_disease_rules (doc_id, icode, data) VALUES ('AF', NULL, '{"screening_notes":"INR<2.0=เสี่ยงลิ่มเลือด ต้องปรับขนาด Warfarin | INR2-3=เป้าหมาย | INR>3=เสี่ยงเลือดออก ลด Warfarin | HR>100=Rate control ไม่เพียงพอ | HR<55=Bradycardia จาก BB/Digoxin","updatedAt":"2026-05-30T15:18:10.876Z","display_name":"ภาวะหัวใจเต้นผิดจังหวะ (AF)","required_labs":"INR,HR","disease_key":"AF","disease":"AF"}');
INSERT INTO rxrule_disease_rules (doc_id, icode, data) VALUES ('ALLOPURINOL_NEW', NULL, '{"note":"ผู้ป่วยใหม่/รับยา <2 เดือน: ตรวจ HLA-B*58:01 ก่อน — ไม่พบผล → consult แพทย์","display_name":"ผู้ป่วยใหม่ + Allopurinol","updatedAt":"2026-05-30T18:03:49.431Z","disease_key":"ALLOPURINOL_NEW","drug_icode":"allopurinol","severity":"caution","disease":"NEW_PATIENT"}');
INSERT INTO rxrule_disease_rules (doc_id, icode, data) VALUES ('Anemia', NULL, '{"screening_notes":"BW ลดลง=ติดตามอาการ | CBC ก่อนและระหว่างรักษา | FF treatment:3-6mg/kg/day แบ่ง 1-3ครั้ง | อาการดีขึ้นใน 1-2 เดือน | Hb target>11 g/dL","display_name":"โลหิตจาง (Anemia)","updatedAt":"2026-05-30T15:18:10.876Z","disease_key":"Anemia","disease":"Anemia","optional_labs":"BW"}');
INSERT INTO rxrule_disease_rules (doc_id, icode, data) VALUES ('Asthma_COPD', NULL, '{"disease_key":"Asthma_COPD","disease":"Asthma_COPD","required_labs":"HR","updatedAt":"2026-05-30T15:18:10.876Z","display_name":"โรคหอบหืด/ปอดอุดกั้น (Asthma/COPD)","screening_notes":"HR>110 + wheezing รุนแรง=ต้องรับไว้รักษา | Salbutamol nebulizer ทุก 20 นาที×3 ครั้ง | SpO2<92%=ต้องให้ O2 | ระวัง Beta-blocker ในหอบหืด"}');
INSERT INTO rxrule_disease_rules (doc_id, icode, data) VALUES ('CKD', NULL, '{"disease_key":"CKD","disease":"CKD","optional_labs":"BUN","screening_notes":"eGFR>60=ปกติ | eGFR30-60=ระวัง ลดขนาด Metformin | eGFR15-30=ห้ามใช้ Metformin ระวัง NSAID | eGFR<15=ไตวาย ต้องปรึกษาอายุรกรรม | SCr>1.5=ปรับขนาด Aminoglycoside ทุกตัว | BUN>30=uremia ระวัง","required_labs":"SCr,eGFR","display_name":"ไตเสื่อมเรื้อรัง (CKD)","updatedAt":"2026-05-30T15:18:10.876Z"}');
INSERT INTO rxrule_disease_rules (doc_id, icode, data) VALUES ('CKD_GLIBENCLAMIDE', NULL, '{"note":"eGFR<60: ห้ามใช้ (เปลี่ยนเป็น Glipizide)","drug_class":"Sulfonylurea","display_name":"CKD + Glibenclamide","updatedAt":"2026-05-30T18:03:49.431Z","disease_key":"CKD_GLIBENCLAMIDE","severity":"contraindicated","disease":"CKD"}');
INSERT INTO rxrule_disease_rules (doc_id, icode, data) VALUES ('CKD_LITHIUM', NULL, '{"disease_key":"CKD_LITHIUM","disease":"CKD","drug_icode":"lithium","severity":"avoid","display_name":"CKD + Lithium","updatedAt":"2026-05-30T18:03:49.431Z","note":"CrCl<30: ไม่แนะนำ"}');
INSERT INTO rxrule_disease_rules (doc_id, icode, data) VALUES ('CKD_METFORMIN', NULL, '{"disease":"CKD","severity":"contraindicated","disease_key":"CKD_METFORMIN","updatedAt":"2026-05-30T18:03:49.431Z","display_name":"CKD + Metformin","note":"eGFR<30: ห้ามใช้ · eGFR 30-45: max 1000 mg/day","drug_class":"Metformin"}');
INSERT INTO rxrule_disease_rules (doc_id, icode, data) VALUES ('CKD_NSAID', NULL, '{"display_name":"CKD + NSAIDs","updatedAt":"2026-05-30T18:03:49.431Z","note":"eGFR<30: หลีกเลี่ยง NSAIDs","drug_class":"NSAID","disease":"CKD","severity":"avoid","disease_key":"CKD_NSAID"}');
INSERT INTO rxrule_disease_rules (doc_id, icode, data) VALUES ('CKD_SGLT2', NULL, '{"display_name":"CKD + SGLT2 (Empagliflozin)","updatedAt":"2026-05-30T18:03:49.431Z","note":"eGFR<30: ห้ามใช้ · HF: eGFR<20 ห้ามใช้","drug_class":"SGLT2","disease_key":"CKD_SGLT2","disease":"CKD","severity":"contraindicated"}');
INSERT INTO rxrule_disease_rules (doc_id, icode, data) VALUES ('DM', NULL, '{"screening_notes":"FBS<70=น้ำตาลต่ำ ต้องรักษาทันที | FBS70-130=เป้าหมาย | FBS130-180=ปรับยาเพิ่ม | FBS>180=ควบคุมไม่ได้ | HbA1c<7%=ดี | HbA1c≥8%=ควบคุมไม่ดี | BW เพิ่ม>5%=ระวังน้ำหนักเกิน","display_name":"เบาหวาน (DM)","updatedAt":"2026-05-30T15:18:10.876Z","required_labs":"FBS","disease":"DM","optional_labs":"HbA1c,BW","disease_key":"DM"}');
INSERT INTO rxrule_disease_rules (doc_id, icode, data) VALUES ('ELDERLY_LABZD', NULL, '{"note":"หลีกเลี่ยง chlordiazepoxide / diazepam / dipotassium chlorazepate","drug_class":"Long-acting BZD","updatedAt":"2026-05-30T18:03:49.431Z","display_name":"อายุ ≥65 + Long-acting BZD","disease_key":"ELDERLY_LABZD","severity":"avoid","disease":"ELDERLY"}');
INSERT INTO rxrule_disease_rules (doc_id, icode, data) VALUES ('Epilepsy', NULL, '{"disease_key":"Epilepsy","disease":"Epilepsy","optional_labs":"drug_level","screening_notes":"Phenytoin level<10=sub-therapeutic ชักได้ | Phenytoin level>20=toxic เดินเซ ตาพร่า | Phenobarbital<15=sub-therapeutic | Phenobarbital>40=toxic ซึม | ระวัง DDI phenytoin สูงมาก","display_name":"โรคลมชัก (Epilepsy)","updatedAt":"2026-05-30T15:18:10.876Z"}');
INSERT INTO rxrule_disease_rules (doc_id, icode, data) VALUES ('Gout', NULL, '{"disease_key":"Gout","disease":"Gout","optional_labs":"SCr,eGFR","screening_notes":"eGFR<30=ลดขนาด Allopurinol ลงครึ่งหนึ่ง | eGFR<10=หลีกเลี่ยง Allopurinol | SCr สูง=ระวัง NSAIDs ทำให้ไตแย่ลง | ระหว่างกำเริบเฉียบพลัน ห้ามหยุดยาลดกรดยูริกที่กินอยู่","display_name":"โรคเกาต์ (Gout)","updatedAt":"2026-05-30T15:18:10.876Z"}');
INSERT INTO rxrule_disease_rules (doc_id, icode, data) VALUES ('HF', NULL, '{"required_labs":"HR,K+","display_name":"หัวใจล้มเหลว (HF)","updatedAt":"2026-05-30T15:18:10.876Z","screening_notes":"HR<55=bradycardia จาก Beta-blocker ระวัง | K+<3.5=hypokalemia เพิ่มพิษ Digoxin | BW เพิ่ม>2กก.ใน2วัน=fluid overload ปรับ Furosemide | SCr สูงขึ้น=ระวังยาขับน้ำมากเกิน","disease_key":"HF","optional_labs":"SCr,BW","disease":"HF"}');
INSERT INTO rxrule_disease_rules (doc_id, icode, data) VALUES ('HF_PIOGLITAZONE', NULL, '{"note":"ผู้ป่วย HF NYHA 3-4 ห้ามใช้ Pioglitazone","drug_class":"Thiazolidinedione","display_name":"HF NYHA III-IV + Pioglitazone","updatedAt":"2026-05-30T18:03:49.431Z","disease_key":"HF_PIOGLITAZONE","severity":"contraindicated","disease":"HF"}');
INSERT INTO rxrule_disease_rules (doc_id, icode, data) VALUES ('HIV_ARV', NULL, '{"disease_key":"HIV_ARV","disease":"HIV_ARV","optional_labs":"LFT,SCr","screening_notes":"LFT>5x normal=พิจารณาหยุด ARV | SCr>1.5=ระวัง Tenofovir nephrotoxicity ปรึกษาแพทย์ | ติดตาม CD4 และ Viral load ตามนัด | ห้ามหยุดยาเองเด็ดขาด","display_name":"ผู้ติดเชื้อ HIV รับ ARV","updatedAt":"2026-05-30T15:18:10.876Z"}');
INSERT INTO rxrule_disease_rules (doc_id, icode, data) VALUES ('HIV_ARV_Monitoring', NULL, '{"disease_key":"HIV_ARV_Monitoring","optional_labs":"LFT,SCr,WBC","disease":"HIV_ARV_Monitoring","screening_notes":"LFT>5xNormal=พิจารณาหยุด ARV | SCr>1.5=ระวัง TDF nephrotoxicity | WBC<3000 หรือ Neutrophil<1500=ระวัง AZT myelosuppression | ห้ามหยุดยา ARV เองเด็ดขาด | ติดตาม CD4 และ Viral load","display_name":"การติดตาม HIV/ARV","updatedAt":"2026-05-30T15:18:10.876Z"}');
INSERT INTO rxrule_disease_rules (doc_id, icode, data) VALUES ('HT', NULL, '{"disease":"HT","optional_labs":"K+,SCr","disease_key":"HT","screening_notes":"K+<3.5=hypokalemia จาก thiazide/loop diuretic เสี่ยงหัวใจผิดจังหวะ | K+>5.5=hyperkalemia จาก ACEI/ARB+K-sparing ระวัง | SCr สูงขึ้น>30%หลังเริ่ม ACEI/ARB=ปรึกษาแพทย์","display_name":"ความดันโลหิตสูง (HT)","updatedAt":"2026-05-30T15:18:10.876Z"}');
INSERT INTO rxrule_disease_rules (doc_id, icode, data) VALUES ('HTN_Pregnancy', NULL, '{"disease":"HTN_Pregnancy","optional_labs":"SCr,K+","disease_key":"HTN_Pregnancy","updatedAt":"2026-05-30T15:18:10.876Z","display_name":"ความดันในตั้งครรภ์","screening_notes":"ใช้ Methyldopa หรือ Nifedipine เป็น first-line | ห้าม ACEI/ARB ทุกชนิดในตั้งครรภ์ไตรมาส 2-3 | ห้าม Warfarin ไตรมาส 1 และ 3 | Aspirin ขนาดต่ำ 75-150mg อาจป้องกัน preeclampsia"}');
INSERT INTO rxrule_disease_rules (doc_id, icode, data) VALUES ('Hyperthyroid', NULL, '{"screening_notes":"HR>100=tachycardia ระวัง thyroid storm | HR<50=bradycardia จาก beta-blocker มากเกิน | อายุ>65=เริ่ม Methimazole/PTU ขนาดต่ำ | ตรวจ TFT ทุก 4-6 สัปดาห์จนคงที่","required_labs":"HR","display_name":"ภาวะไทรอยด์เป็นพิษ (Hyperthyroid)","updatedAt":"2026-05-30T15:18:10.876Z","disease_key":"Hyperthyroid","disease":"Hyperthyroid","optional_labs":"อายุ"}');
INSERT INTO rxrule_disease_rules (doc_id, icode, data) VALUES ('Hypothyroid', NULL, '{"disease":"Hypothyroid","optional_labs":"อายุ","disease_key":"Hypothyroid","updatedAt":"2026-05-30T15:18:10.876Z","display_name":"ภาวะขาดไทรอยด์ (Hypothyroid)","screening_notes":"ผู้สูงอายุ>60ปี หรือมีโรคหัวใจ: เริ่ม Levothyroxine 25-50mcg ค่อยๆปรับขึ้น | อายุ<60ปี ไม่มีโรคหัวใจ: เริ่ม 50mcg ปรับทุก 6 สัปดาห์ | ติดตาม TSH ทุก 6 สัปดาห์จนคงที่"}');
INSERT INTO rxrule_disease_rules (doc_id, icode, data) VALUES ('Infection_Sepsis', NULL, '{"screening_notes":"WBC>12000 หรือ <4000=suspect infection | Fever+WBC สูง=เริ่ม empirical ATB ภายใน 1 ชม. | SCr สูงขึ้น=septic AKI ระวัง nephrotoxic drugs | ปรับขนาด aminoglycoside ตาม CrCl","display_name":"ภาวะติดเชื้อ/Sepsis","updatedAt":"2026-05-30T15:18:10.876Z","disease":"Infection_Sepsis","optional_labs":"WBC,SCr","disease_key":"Infection_Sepsis"}');
INSERT INTO rxrule_disease_rules (doc_id, icode, data) VALUES ('PREG_ERGOT', NULL, '{"disease_key":"PREG_ERGOT","severity":"contraindicated","disease":"PREGNANCY","note":"ห้ามใช้ Ergotamine/Methylergonovine ในระหว่างตั้งครรภ์","drug_class":"Ergot","display_name":"ตั้งครรภ์ + Ergot","updatedAt":"2026-05-30T18:03:49.431Z"}');
INSERT INTO rxrule_disease_rules (doc_id, icode, data) VALUES ('PREG_LITHIUM', NULL, '{"disease":"PREGNANCY","drug_icode":"lithium","severity":"contraindicated","disease_key":"PREG_LITHIUM","display_name":"ตั้งครรภ์ไตรมาสแรก + Lithium","updatedAt":"2026-05-30T18:03:49.431Z","note":"ห้ามใช้ในไตรมาสแรก"}');
INSERT INTO rxrule_disease_rules (doc_id, icode, data) VALUES ('PREG_STATIN', NULL, '{"display_name":"ตั้งครรภ์ + Statin","updatedAt":"2026-05-30T18:03:49.431Z","drug_class":"Statin","note":"ห้ามใช้ในหญิงตั้งครรภ์","disease":"PREGNANCY","severity":"contraindicated","disease_key":"PREG_STATIN"}');
INSERT INTO rxrule_disease_rules (doc_id, icode, data) VALUES ('PREG_WARFARIN', NULL, '{"note":"ห้ามใช้ (teratogenic) — เปลี่ยนเป็น LMWH","display_name":"ตั้งครรภ์ + Warfarin","updatedAt":"2026-05-30T18:03:49.431Z","severity":"contraindicated","drug_icode":"warfarin","disease":"PREGNANCY","disease_key":"PREG_WARFARIN"}');
INSERT INTO rxrule_disease_rules (doc_id, icode, data) VALUES ('Pain_Management', NULL, '{"required_labs":"BW","display_name":"การจัดการความปวด","updatedAt":"2026-05-30T15:18:10.876Z","screening_notes":"BW เด็ก=คำนวณ Paracetamol 10-15mg/kg q4-6h | NSAID ระวังในไตเสื่อมและผู้สูงอายุ | Opioid+Benzodiazepine=เสี่ยง respiratory depression | ปวดรุนแรง+ไตเสื่อม=ปรึกษาขนาด Tramadol","disease_key":"Pain_Management","disease":"Pain_Management","optional_labs":"SCr"}');
INSERT INTO rxrule_disease_rules (doc_id, icode, data) VALUES ('Renal_Impairment', NULL, '{"disease":"Renal_Impairment","optional_labs":"BUN,K+","disease_key":"Renal_Impairment","required_labs":"SCr,eGFR","display_name":"ไตเสื่อม/ไตวาย (CKD/AKI)","updatedAt":"2026-05-30T15:18:10.876Z","screening_notes":"eGFR>60=ปกติ | eGFR45-60=ระวัง Metformin ลดขนาด | eGFR30-45=Metformin Max 500 BID | eGFR15-30=ห้าม Metformin NSAID | eGFR<15=ไตวาย referral | K+>6=hyperkalemia ด่วน hold K-sparing | SCr เพิ่ม>30%หลัง ACEI=ปรึกษา"}');
INSERT INTO rxrule_disease_rules (doc_id, icode, data) VALUES ('TB', NULL, '{"disease":"TB","optional_labs":"LFT","disease_key":"TB","display_name":"วัณโรค (TB)","updatedAt":"2026-05-30T15:18:10.876Z","screening_notes":"LFT>3x normal ไม่มีอาการ=หยุดยาชั่วคราว | LFT>3x normal มีอาการ=หยุดยาทันที | LFT ปกติ=ติดตามต่อทุก 2 สัปดาห์ | ระวัง Rifampicin ลดฤทธิ์ยาอื่นๆมาก"}');
INSERT INTO rxrule_disease_rules (doc_id, icode, data) VALUES ('TB_Treatment', NULL, '{"display_name":"การรักษาวัณโรค (TB)","updatedAt":"2026-05-30T15:18:10.876Z","screening_notes":"LFT>3xNormal ไม่มีอาการ=หยุดยาชั่วคราว | LFT>3xNormal มีอาการ=หยุดทันที | Ethambutol CrCl<30=เปลี่ยนเป็น 3ครั้ง/สัปดาห์ | Pyrazinamide CrCl<30=เปลี่ยนเป็น 3ครั้ง/สัปดาห์ | Rifampicin ลดฤทธิ์ยาหลายชนิด","disease":"TB_Treatment","optional_labs":"LFT,SCr","disease_key":"TB_Treatment"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000010', '1000010', '{"storage":"≤ 25°C · ป้องกันแสง · ห้ามแช่แข็ง","special_pop":"• ผู้ป่วย DM: ตรวจ DTX หลังให้ยา (Hyperglycemia)\\n• ผู้ป่วยโรคหัวใจ: ระวัง tachycardia รุนแรง","full_counseling":"• ยา EpiPen/Adrenaline ฉีดเข้ากล้ามเนื้อต้นขาด้านนอก ทะลุกางเกงได้เลย\\n• หลังฉีดให้นอนราบ ยกขาสูง ไปโรงพยาบาลทันทีแม้อาการดีขึ้นแล้ว\\n• อาจรู้สึกใจสั่น มือสั่น เป็นผลปกติ\\n• เก็บยาที่อุณหภูมิห้อง ห้ามแช่เย็น","drug_name":"ADRENALINE (HAD)","icode":"1000010","counseling_th":"• ยา EpiPen/Adrenaline ฉีดเข้ากล้ามเนื้อต้นขาด้านนอก ทะลุกางเกงได้เลย\\n• หลังฉีดให้นอนราบ ยกขาสูง ไปโรงพยาบาลทันทีแม้อาการดีขึ้นแล้ว\\n• อาจรู้สึกใจสั่น มือสั่น เป็นผลปกติ\\n• เก็บยาที่อุณหภูมิห้อง ห้ามแช่เย็น","when_to_er":"• หายใจลำบาก · ความดันยังต่ำ · มีผื่นลามเพิ่มขึ้น\\n• ผิวหนังบริเวณฉีด IV ซีดขาว เย็น (extravasation)","short_label":"ฉีดต้นขาด้านนอก · ไปโรงพยาบาลทันทีแม้อาการดีขึ้น","updatedAt":"2026-06-01T15:54:37.249Z"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000016', '1000016', '{"icode":"1000016","counseling_th":"• ยาป้องกันเก๊าท์ ไม่ใช่ยารักษาเก๊าท์เฉียบพลัน\\n• ดื่มน้ำมากๆ ≥ 2 ลิตร/วัน (ป้องกัน kidney stones)\\n• กินพร้อมหรือหลังอาหาร (ลดระคายเคืองกระเพาะ)\\n• ห้ามเริ่มยาระหว่างที่ข้ออักเสบกำเริบ\\n• ตรวจ HLA-B*5801 ก่อนเริ่มในผู้ป่วยไทย (SJS risk)","when_to_er":"• ผื่นแดงลามทั่วตัว ตุ่มพอง (SJS/TEN — อันตรายมาก หยุดยาทันที)\\n• ไข้ร่วมกับผื่น\\n• ตัวเหลือง ตาเหลือง (hepatotoxicity)","short_label":"ห้ามเริ่มระหว่าง gout กำเริบ · แจ้งทันทีถ้ามีผื่น","full_counseling":"• ยาป้องกันเก๊าท์ ไม่ใช่ยารักษาเก๊าท์เฉียบพลัน\\n• ดื่มน้ำมากๆ ≥ 2 ลิตร/วัน (ป้องกัน kidney stones)\\n• กินพร้อมหรือหลังอาหาร (ลดระคายเคืองกระเพาะ)\\n• ห้ามเริ่มยาระหว่างที่ข้ออักเสบกำเริบ\\n• ตรวจ HLA-B*5801 ก่อนเริ่มในผู้ป่วยไทย (SJS risk)","special_pop":"• Azathioprine/6-MP: ลด dose 75% (allopurinol ↑ level มาก)\\n• Pregnancy Cat C","drug_name":"alloPURINOL*","storage":"≤ 25°C · ป้องกันความชื้น","updatedAt":"2026-06-01T15:54:37.249Z","food_interaction":"• ลดอาหารที่มี purine สูง: เครื่องในสัตว์ น้ำซุปเข้มข้น\\n• ลดแอลกอฮอล์ (เพิ่ม uric acid)\\n• แยกยาจาก antacid / iron ≥ 2 ชม."}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000016_16', '1000016', '{"icode":"1000016","when_to_er":"• ผื่นแดงลามทั่วตัว ตุ่มพอง (SJS/TEN ฉุกเฉิน)\\n• ตัวเหลือง ตาเหลือง ปวดท้องมาก\\n• ไข้สูงร่วมกับผื่น","counseling_th":"• กินพร้อมหรือหลังอาหาร\\n• ดื่มน้ำมาก 2-3 ลิตร/วัน\\n• ห้ามหยุดยาระหว่างเกิดเกาต์เฉียบพลัน","special_pop":"• ไตเสื่อม eGFR<30: ต้องลดขนาดยาลงครึ่งหนึ่ง\\n• HLA-B*5801 เสี่ยง SJS สูงในคนเอเชีย","full_counseling":"• กินพร้อมหรือหลังอาหาร\\n• ดื่มน้ำมาก 2-3 ลิตร/วัน\\n• ห้ามหยุดยาระหว่างเกิดเกาต์เฉียบพลัน","drug_name":"Allopurinol","side_effect":"• ผื่นแพ้ผิวหนัง (ต้องแจ้งแพทย์ทันที)\\n• คลื่นไส้ ปวดท้อง\\n• ตับอักเสบ","food_interaction":"• แอลกอฮอล์เพิ่มกรดยูริก\\n• หลีกเลี่ยงอาหารที่มีพิวรีนสูง (เครื่องในสัตว์ อาหารทะเล)","warning":"• ผื่นแดงลามทั่วตัว ตุ่มพอง (SJS/TEN ฉุกเฉิน)\\n• ตัวเหลือง ตาเหลือง ปวดท้องมาก\\n• ไข้สูงร่วมกับผื่น","updatedAt":"2026-05-30T15:18:09.169Z"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000023_27', '1000023', '{"food_interaction":"• แอลกอฮอล์เพิ่มฤทธิ์กดระบบประสาท\\n• หลีกเลี่ยงยากดประสาทอื่น","updatedAt":"2026-05-30T15:18:09.169Z","warning":"• หัวใจเต้นผิดจังหวะรุนแรง\\n• ชักหรือหมดสติ (กินเกินขนาด)\\n• ซึมมาก ไม่ตอบสนอง\\n• ความดันต่ำมาก หมดสติ","side_effect":"• ง่วงนอนมาก (พบบ่อย)\\n• ปากแห้ง ตาพร่า ท้องผูก ปัสสาวะลำบาก\\n• ความดันต่ำเมื่อลุกยืน เวียนหัว\\n• น้ำหนักขึ้น","drug_name":"Amitriptyline","special_pop":"• ผู้สูงอายุ: เสี่ยงหกล้ม สับสน ปัสสาวะลำบาก\\n• โรคหัวใจ: ระวัง QT prolongation","full_counseling":"• กินก่อนนอนเพื่อลดฤทธิ์ง่วง\\n• ระวังการขับขี่และใช้เครื่องจักร\\n• ลุกนั่งช้าๆ ป้องกันความดันต่ำ\\n• ห้ามหยุดยาเองทันที ต้องค่อยๆลด","when_to_er":"• หัวใจเต้นผิดจังหวะรุนแรง\\n• ชักหรือหมดสติ (กินเกินขนาด)\\n• ซึมมาก ไม่ตอบสนอง\\n• ความดันต่ำมาก หมดสติ","counseling_th":"• กินก่อนนอนเพื่อลดฤทธิ์ง่วง\\n• ระวังการขับขี่และใช้เครื่องจักร\\n• ลุกนั่งช้าๆ ป้องกันความดันต่ำ\\n• ห้ามหยุดยาเองทันที ต้องค่อยๆลด","icode":"1000023"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000041', '1000041', '{"special_pop":"• ผู้สูงอายุ / BPH: ระวัง urinary retention มาก\\n• ห้ามใน Narrow angle glaucoma","full_counseling":"• หลังฉีดยาอาจปากแห้ง ตาพร่า ปัสสาวะลำบาก ชั่วคราว — เป็นผลปกติของยา\\n• ถ้าปัสสาวะไม่ออกนานกว่า 4-6 ชม. แจ้งพยาบาลทันที\\n• หลีกเลี่ยงการขับรถหรือใช้เครื่องจักร (ตาพร่า)","drug_name":"ATROpine (HAD)","storage":"≤ 25°C · ป้องกันแสง","counseling_th":"• หลังฉีดยาอาจปากแห้ง ตาพร่า ปัสสาวะลำบาก ชั่วคราว — เป็นผลปกติของยา\\n• ถ้าปัสสาวะไม่ออกนานกว่า 4-6 ชม. แจ้งพยาบาลทันที\\n• หลีกเลี่ยงการขับรถหรือใช้เครื่องจักร (ตาพร่า)","short_label":"อาจปากแห้ง ตาพร่า ปัสสาวะลำบาก — ปกติ","when_to_er":"• ปัสสาวะไม่ออกนาน > 6 ชม. · ปวดท้องน้อยมาก\\n• สับสน เพ้อ (atropine toxicity ในสูงอายุ)\\n• ชีพจร > 140 ครั้ง/นาที","icode":"1000041","updatedAt":"2026-06-01T15:54:37.249Z"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000058', '1000058', '{"food_interaction":"• ยาแคลเซียมเม็ดรับประทาน: แยก ≥ 2 ชม. จาก quinolone / thyroid / iron","updatedAt":"2026-06-01T15:54:37.249Z","when_to_er":"• ใจสั่น หัวใจเต้นผิดจังหวะ\\n• กล้ามเนื้ออ่อนแรงมาก\\n• ปัสสาวะน้อยผิดปกติ (hypercalcemia)","short_label":"แจ้งพยาบาลถ้าบริเวณ IV ปวด บวม หรือซีด","counseling_th":"• ยาฉีดเข้าเส้นเลือดเท่านั้น ห้ามฉีดเข้ากล้ามเนื้อ\\n• ถ้าบริเวณที่ให้ยาปวด บวม แดง หรือผิวหนังซีด แจ้งพยาบาลทันที\\n• Calcium gluconate และ Calcium chloride ต่างกัน — อย่าสับสน","icode":"1000058","drug_name":"calCIUM glucoNATE (HAD)","special_pop":"• ผู้ป่วยที่ใช้ Digoxin: ห้ามให้ Ca IV ถ้าสงสัย digoxin toxicity\\n• ทารกแรกเกิด: ห้ามผสม Ceftriaxone + Ca IV (fatal)","full_counseling":"• ยาฉีดเข้าเส้นเลือดเท่านั้น ห้ามฉีดเข้ากล้ามเนื้อ\\n• ถ้าบริเวณที่ให้ยาปวด บวม แดง หรือผิวหนังซีด แจ้งพยาบาลทันที\\n• Calcium gluconate และ Calcium chloride ต่างกัน — อย่าสับสน","storage":"อุณหภูมิห้อง · ห้ามแช่เย็น (ตกตะกอน)"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000065', '1000065', '{"updatedAt":"2026-06-01T15:54:37.249Z","food_interaction":"• ห้ามร่วม Antacid/Kaolin — แยก ≥ 2-4 ชม.","storage":"≤ 25°C · ป้องกันแสง","drug_name":"chloroQUINE (150 mg base)","special_pop":"• Pregnancy Cat C — ใช้ได้ใน malaria (benefit > risk)\\n• G6PD deficiency: ระวัง","full_counseling":"• กินพร้อมอาหาร (ลด GI ADR)\\n• ตรวจ G6PD ก่อนเริ่มยา\\n• กินครบ course ตามแพทย์สั่ง แม้อาการดีขึ้น\\n• ตรวจตา ถ้าใช้ระยะยาว > 5 ปี","short_label":"ตรวจ G6PD ก่อน · กินพร้อมอาหาร","when_to_er":"• ตาพร่า มองเห็นผิดปกติ (retinopathy — ระยะยาว)\\n• ใจสั่น หัวใจเต้นผิดจังหวะ (QTc prolongation)\\n• มองเห็นแสงหรือสี halo รอบแสง","counseling_th":"• กินพร้อมอาหาร (ลด GI ADR)\\n• ตรวจ G6PD ก่อนเริ่มยา\\n• กินครบ course ตามแพทย์สั่ง แม้อาการดีขึ้น\\n• ตรวจตา ถ้าใช้ระยะยาว > 5 ปี","icode":"1000065"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000086', '1000086', '{"icode":"1000086","counseling_th":"• กินพร้อมหรือหลังอาหาร\\n• ห้ามกินเกินขนาดที่กำหนดเด็ดขาด (toxic dose ใกล้ therapeutic dose)\\n• ถ้าท้องเสียมาก = early toxicity — หยุดยาทันที\\n• ห้ามใช้ร่วม Clarithromycin/Erythromycin โดยไม่ปรึกษาแพทย์","when_to_er":"• ท้องเสียรุนแรงไม่หยุด · คลื่นไส้อาเจียนมาก (early toxicity)\\n• กล้ามเนื้ออ่อนแรงมาก (myopathy)\\n• ไข้ + ปัสสาวะน้อย (multiorgan failure — severe toxicity)","short_label":"ห้ามกินเกินขนาด · ท้องเสียมาก = หยุดยา","storage":"≤ 25°C · ป้องกันแสง","special_pop":"• โรคไต CrCl < 30: ลดขนาดมาก\\n• โรคตับ: ลดขนาด\\n• Pregnancy Cat C","full_counseling":"• กินพร้อมหรือหลังอาหาร\\n• ห้ามกินเกินขนาดที่กำหนดเด็ดขาด (toxic dose ใกล้ therapeutic dose)\\n• ถ้าท้องเสียมาก = early toxicity — หยุดยาทันที\\n• ห้ามใช้ร่วม Clarithromycin/Erythromycin โดยไม่ปรึกษาแพทย์","drug_name":"colCHICINE(*ชา)","food_interaction":"• น้ำเกรปฟรุต: ↑ colchicine level — หลีกเลี่ยง","updatedAt":"2026-06-01T15:54:37.249Z"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000086_35', '1000086', '{"food_interaction":"• น้ำส้มโอเพิ่มระดับยา\\n • หลีกเลี่ยงแอลกอฮอล์","warning":"• ท้องเสียรุนแรงไม่หยุด\\n • กล้ามเนื้ออ่อนแรงมาก\\n • อาการผิดปกติทางเลือด","updatedAt":"2026-05-30T15:18:09.169Z","side_effect":"• ท้องเสีย คลื่นไส้ ปวดท้อง (พบบ่อย)\\n • กล้ามเนื้ออ่อนแรง\\n • เม็ดเลือดขาวต่ำ (ถ้าใช้นาน)","drug_name":"Colchicine","full_counseling":"• กินพร้อมหรือหลังอาหาร\\n • ห้ามใช้เกินขนาดที่กำหนด\\n • หยุดยาถ้ามีท้องเสียรุนแรง","special_pop":"• ไตเสื่อมและตับเสื่อม: ลดขนาด\\n • ระวัง DDI กับ Clarithromycin, Statin","when_to_er":"• ท้องเสียรุนแรงไม่หยุด\\n • กล้ามเนื้ออ่อนแรงมาก\\n • อาการผิดปกติทางเลือด","counseling_th":"• กินพร้อมหรือหลังอาหาร\\n • ห้ามใช้เกินขนาดที่กำหนด\\n • หยุดยาถ้ามีท้องเสียรุนแรง","icode":"1000086"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000089', '1000089', '{"when_to_er":"• DTX > 300 mg/dL ในผู้ป่วย DM\\n• ไข้สูง มีการติดเชื้อ (immunosuppression)","short_label":"Monitor DTX · ห้ามหยุดทันที (ถ้าใช้นาน)","counseling_th":"• ยาให้ทาง IV/IM ลดการอักเสบ\\n• น้ำตาลในเลือดอาจสูงขึ้น — ตรวจ DTX\\n• ห้ามหยุดยาทันทีถ้าใช้มานาน\\n• ห้ามฉีดวัคซีนมีชีวิตขณะใช้ยา","icode":"1000089","storage":"≤ 30°C · ป้องกันแสง","drug_name":"dexaMETHASONE","full_counseling":"• ยาให้ทาง IV/IM ลดการอักเสบ\\n• น้ำตาลในเลือดอาจสูงขึ้น — ตรวจ DTX\\n• ห้ามหยุดยาทันทีถ้าใช้มานาน\\n• ห้ามฉีดวัคซีนมีชีวิตขณะใช้ยา","special_pop":"• Pregnancy Cat C\\n• DM: monitor DTX ถี่ขึ้น","updatedAt":"2026-06-01T15:54:37.249Z"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000113_2', '1000113', '{"special_pop":"• ผู้สูงอายุและผู้ป่วยไตเสื่อม: ยาสะสมได้ง่าย ต้องลดขนาด\\n• เด็กเล็ก: คำนวณขนาดตามน้ำหนัก","full_counseling":"• นับชีพจรก่อนกินยา ถ้าน้อยกว่า 60 ครั้ง/นาที ให้หยุดยาและปรึกษาแพทย์\\n• กินยาเวลาเดิมทุกวัน ไม่ขาดยา\\n• ห้ามหยุดยาเองโดยไม่ปรึกษาแพทย์","drug_name":"Digoxin","icode":"1000113","counseling_th":"• นับชีพจรก่อนกินยา ถ้าน้อยกว่า 60 ครั้ง/นาที ให้หยุดยาและปรึกษาแพทย์\\n• กินยาเวลาเดิมทุกวัน ไม่ขาดยา\\n• ห้ามหยุดยาเองโดยไม่ปรึกษาแพทย์","when_to_er":"• ชีพจรน้อยกว่า 50 ครั้ง/นาที หรือมากกว่า 120 ครั้ง/นาที\\n• คลื่นไส้อาเจียนรุนแรง\\n• มองเห็นผิดปกติ หรือตาพร่ามัว\\n• หัวใจเต้นผิดจังหวะ ใจสั่นมาก","food_interaction":"• หลีกเลี่ยง St. John Wort\\n• แอลกอฮอล์ลดระดับยาในเลือด","updatedAt":"2026-05-30T15:18:09.169Z","warning":"• ชีพจรน้อยกว่า 50 ครั้ง/นาที หรือมากกว่า 120 ครั้ง/นาที\\n• คลื่นไส้อาเจียนรุนแรง\\n• มองเห็นผิดปกติ หรือตาพร่ามัว\\n• หัวใจเต้นผิดจังหวะ ใจสั่นมาก","side_effect":"• คลื่นไส้ อาเจียน เบื่ออาหาร\\n• มองเห็นภาพสีเหลืองหรือสีเขียว\\n• ใจสั่น หัวใจเต้นผิดจังหวะ\\n• ปวดหัว อ่อนเพลีย"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000114', '1000114', '{"storage":"≤ 25°C · ป้องกันแสง","drug_name":"[ ยาฉีด ] diGOXIN (HAD)","full_counseling":"• วัดชีพจรก่อนให้ยาทุกครั้ง ถ้า < 60 ครั้ง/นาที = หยุดยา + แจ้งพยาบาล\\n• ตรวจเลือด K⁺ ก่อนให้ทุกครั้ง ถ้า < 3.5 = ห้ามให้\\n• ให้ IV ช้าๆ ≥ 5-10 นาที ห้ามฉีดเร็ว","special_pop":"• โรคไต: ลดขนาดยา + monitor digoxin level บ่อยขึ้น\\n• ผู้สูงอายุ: เพิ่มความเสี่ยง toxicity (ลด dose)\\n• Pregnancy Cat C","when_to_er":"• ชีพจรน้อยกว่า 50 ครั้ง/นาที\\n• มองเห็นแสงสีเหลือง-เขียว หรือเห็นวงรอบแสง\\n• คลื่นไส้อาเจียนรุนแรง · สับสน\\n• หัวใจเต้นผิดจังหวะ","short_label":"นับชีพจรก่อนให้ · K < 3.5 = HOLD","counseling_th":"• วัดชีพจรก่อนให้ยาทุกครั้ง ถ้า < 60 ครั้ง/นาที = หยุดยา + แจ้งพยาบาล\\n• ตรวจเลือด K⁺ ก่อนให้ทุกครั้ง ถ้า < 3.5 = ห้ามให้\\n• ให้ IV ช้าๆ ≥ 5-10 นาที ห้ามฉีดเร็ว","icode":"1000114","updatedAt":"2026-06-01T15:54:37.249Z"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000118', '1000118', '{"special_pop":"• Pregnancy Cat C\\n• ผู้ป่วย hypovolemia: แก้ไขก่อนให้ยาเสมอ","full_counseling":"• ยาให้ทางเส้นเลือดต้องใช้ infusion pump เท่านั้น\\n• ห้ามหยุดยาทันที ต้องค่อยๆ ลดขนาด\\n• แจ้งพยาบาลถ้าบริเวณที่ให้ยาปวดหรือบวม","drug_name":"doPAMINE (HAD)","storage":"≤ 25°C · ป้องกันแสง · สีเหลืองเข้ม/น้ำตาล = ทิ้ง","icode":"1000118","counseling_th":"• ยาให้ทางเส้นเลือดต้องใช้ infusion pump เท่านั้น\\n• ห้ามหยุดยาทันที ต้องค่อยๆ ลดขนาด\\n• แจ้งพยาบาลถ้าบริเวณที่ให้ยาปวดหรือบวม","when_to_er":"• ใจสั่น แน่นหน้าอก\\n• ปลายมือปลายเท้าซีด เย็น หรือเขียว\\n• บริเวณ IV บวมแดง เย็น (extravasation → necrosis)","short_label":"Infusion pump · ตรวจสีสารละลาย · ห้ามหยุดทันที","updatedAt":"2026-06-01T15:54:37.249Z"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000139', '1000139', '{"when_to_er":"• กล้ามเนื้ออ่อนแรงมาก ตะคริวรุนแรง ใจสั่น (hypokalemia รุนแรง)\\n• หูอื้อ ได้ยินลดลง (ototoxicity — dose สูง หรือให้เร็วเกิน)\\n• ปัสสาวะน้อยมากทั้งๆ กินยา (prerenal AKI)","short_label":"กินตอนเช้า · ตรวจ K⁺ · กินกล้วยสม่ำเสมอ","counseling_th":"• กินตอนเช้าหรือช่วงกลางวัน ไม่กินเย็น (ปัสสาวะบ่อยตอนกลางคืน)\\n• ดื่มน้ำให้เพียงพอ แต่ไม่มากเกินไป\\n• กินอาหารที่มีโพแทสเซียมสูง (กล้วย ส้ม มันฝรั่ง)\\n• ตรวจเลือด K⁺ ตามนัด","icode":"1000139","drug_name":"Lasix  FUROSEMIDE(*ชา)","special_pop":"• Pregnancy Cat C\\n• แพ้ Sulfa: ระวัง cross-reactivity\\n• โรคเก๊าท์: Furosemide ↑ uric acid","full_counseling":"• กินตอนเช้าหรือช่วงกลางวัน ไม่กินเย็น (ปัสสาวะบ่อยตอนกลางคืน)\\n• ดื่มน้ำให้เพียงพอ แต่ไม่มากเกินไป\\n• กินอาหารที่มีโพแทสเซียมสูง (กล้วย ส้ม มันฝรั่ง)\\n• ตรวจเลือด K⁺ ตามนัด","storage":"≤ 25°C · ป้องกันแสง","food_interaction":"• กินอาหาร K สูงสม่ำเสมอ\\n• ห้ามซื้อ NSAIDs เอง (ลด furosemide efficacy)\\n• ลดอาหารเค็ม (เสริมฤทธิ์ยา)","updatedAt":"2026-06-01T15:54:37.249Z"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000139_25', '1000139', '{"side_effect":"• ปัสสาวะบ่อยมาก\\n• K+ ในเลือดต่ำ ตะคริว กล้ามเนื้ออ่อนแรง\\n• Na+ ต่ำ ปวดหัว คลื่นไส้\\n• เวียนหัว ความดันต่ำ","food_interaction":"• ลดอาหารเค็ม\\n• กินอาหารที่มี K+ (กล้วย ส้ม) ถ้าไม่มีข้อห้าม","warning":"• กล้ามเนื้ออ่อนแรงมาก ตะคริวรุนแรง\\n• หัวใจเต้นผิดจังหวะ ใจสั่น\\n• น้ำหนักลดเกิน 1 กก./วัน หรือขาบวมมากขึ้น\\n• ปัสสาวะน้อย ไตวาย","updatedAt":"2026-05-30T15:18:09.169Z","icode":"1000139","when_to_er":"• กล้ามเนื้ออ่อนแรงมาก ตะคริวรุนแรง\\n• หัวใจเต้นผิดจังหวะ ใจสั่น\\n• น้ำหนักลดเกิน 1 กก./วัน หรือขาบวมมากขึ้น\\n• ปัสสาวะน้อย ไตวาย","counseling_th":"• กินในตอนเช้า ไม่ควรกินเย็นเพราะปัสสาวะบ่อยกลางคืน\\n• ติดตามน้ำหนักตัวทุกวัน\\n• ดื่มน้ำสม่ำเสมอ ไม่มากเกินหรือน้อยเกิน","special_pop":"• ผู้สูงอายุ: เสี่ยงความดันต่ำและหกล้ม\\n• ผู้ป่วย DM: อาจทำให้น้ำตาลสูง","full_counseling":"• กินในตอนเช้า ไม่ควรกินเย็นเพราะปัสสาวะบ่อยกลางคืน\\n• ติดตามน้ำหนักตัวทุกวัน\\n• ดื่มน้ำสม่ำเสมอ ไม่มากเกินหรือน้อยเกิน","drug_name":"Furosemide"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000140', '1000140', '{"storage":"≤ 30°C · หลังเจือจางคงตัว 24 ชม.","drug_name":"genTAMICIN","full_counseling":"• ยาฉีด ให้ทาง IV infuse > 30 นาที ห้ามฉีดเร็ว\\n• ตรวจเลือดไตและระดับยาสม่ำเสมอ\\n• แจ้งทันทีถ้าได้ยินเสียงหึ่งในหู\\n• ดื่มน้ำให้เพียงพอ","special_pop":"• โรคไต: ปรับขนาด + monitor level\\n• Pregnancy Cat D — หลีกเลี่ยง (ototoxicity ทารก)\\n• Myasthenia gravis: ระวัง NMJ blockade","when_to_er":"• ได้ยินเสียงหึ่งในหู หรือได้ยินเสียงลดลง (ototoxicity)\\n• เวียนหัว เดินโซเซ (vestibulotoxicity)\\n• ปัสสาวะน้อยลงมาก (nephrotoxicity)","short_label":"Infuse > 30 นาที · ห้าม IV Push · ตรวจ Cr","counseling_th":"• ยาฉีด ให้ทาง IV infuse > 30 นาที ห้ามฉีดเร็ว\\n• ตรวจเลือดไตและระดับยาสม่ำเสมอ\\n• แจ้งทันทีถ้าได้ยินเสียงหึ่งในหู\\n• ดื่มน้ำให้เพียงพอ","icode":"1000140","updatedAt":"2026-06-01T15:54:37.249Z"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000145_28', '1000145', '{"food_interaction":"• แอลกอฮอล์เพิ่มฤทธิ์กดสมอง","warning":"• กล้ามเนื้อเกร็งแข็งทั่วตัว ไข้สูงมาก (NMS ฉุกเฉิน)\\n• หัวใจเต้นผิดจังหวะรุนแรง\\n• ชักหรือหมดสติ\\n• ตึงแข็งที่คอหรือลูกตากลอกขึ้น (Dystonia)","updatedAt":"2026-05-30T15:18:09.169Z","side_effect":"• ง่วงนอน ซึม\\n• กล้ามเนื้อตึง เกร็ง เดินแข็ง (EPS)\\n• ความดันต่ำ เวียนหัว\\n• ปากแห้ง ท้องผูก","drug_name":"Haloperidol","full_counseling":"• กินยาเวลาเดิม ไม่ขาดยา\\n• ลุกนั่งช้าๆ ป้องกันความดันต่ำ\\n• ระวังการขับขี่และใช้เครื่องจักร","special_pop":"• ผู้สูงอายุ: เพิ่มเสี่ยงหกล้ม สมองเสื่อม\\n• ห้ามใช้ใน Parkinson disease","when_to_er":"• กล้ามเนื้อเกร็งแข็งทั่วตัว ไข้สูงมาก (NMS ฉุกเฉิน)\\n• หัวใจเต้นผิดจังหวะรุนแรง\\n• ชักหรือหมดสติ\\n• ตึงแข็งที่คอหรือลูกตากลอกขึ้น (Dystonia)","counseling_th":"• กินยาเวลาเดิม ไม่ขาดยา\\n• ลุกนั่งช้าๆ ป้องกันความดันต่ำ\\n• ระวังการขับขี่และใช้เครื่องจักร","icode":"1000145"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000147', '1000147', '{"full_counseling":"• หลังได้รับยาอาจมีกล้ามเนื้อแข็ง คอเอียง ตาเหลือกขึ้น แจ้งพยาบาลทันที (EPS)\\n• ระวังการลุกขึ้นเร็ว (ความดันต่ำฉับพลัน)\\n• ห้ามขับรถหรือใช้เครื่องจักร","special_pop":"• สูงอายุที่มี dementia: FDA Black Box — ↑ mortality\\n• Pregnancy Cat C","drug_name":"[ ยาฉีด ] HALOPERIDOL","storage":"≤ 25°C · ป้องกันแสง · ห้ามเจือจาง NSS (เสียความคงตัว)","icode":"1000147","counseling_th":"• หลังได้รับยาอาจมีกล้ามเนื้อแข็ง คอเอียง ตาเหลือกขึ้น แจ้งพยาบาลทันที (EPS)\\n• ระวังการลุกขึ้นเร็ว (ความดันต่ำฉับพลัน)\\n• ห้ามขับรถหรือใช้เครื่องจักร","when_to_er":"• กล้ามเนื้อแข็งเกร็งทั่วตัว คอเอียง ตาเหลือก (acute dystonia → Biperiden)\\n• ไข้สูง กล้ามเนื้อแข็ง สับสน (NMS — Neuroleptic Malignant Syndrome)\\n• หัวใจเต้นผิดจังหวะ (QTc prolongation)","short_label":"Monitor EPS · ตรวจ QTc ก่อนให้","updatedAt":"2026-06-01T15:54:37.249Z","food_interaction":"• ห้ามดื่มแอลกอฮอล์ (เพิ่ม CNS depression)"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000176', '1000176', '{"updatedAt":"2026-06-01T15:54:37.249Z","special_pop":"• โรคไต (CrCl < 25): CONTRAINDICATED\\n• Pregnancy Cat B","full_counseling":"• ยานี้ป้องกันชักและปกป้องทารก (กรณีครรภ์เป็นพิษ)\\n• ต้องมี monitor ใกล้ชิด\\n• อาจรู้สึกร้อนวูบ เหงื่อออก ง่วงนอน เป็นผลปกติ\\n• ถ้าหายใจลำบากหรือกล้ามเนื้ออ่อนแรง พยาบาลจะดูแลทันที","drug_name":"magNESIUM SULFATE(HAD)","storage":"≤ 30°C · ห้ามแช่เย็น + แช่แข็ง (ตกตะกอน)","icode":"1000176","counseling_th":"• ยานี้ป้องกันชักและปกป้องทารก (กรณีครรภ์เป็นพิษ)\\n• ต้องมี monitor ใกล้ชิด\\n• อาจรู้สึกร้อนวูบ เหงื่อออก ง่วงนอน เป็นผลปกติ\\n• ถ้าหายใจลำบากหรือกล้ามเนื้ออ่อนแรง พยาบาลจะดูแลทันที","when_to_er":"• หายใจลำบาก หายใจช้า (< 12 ครั้ง/นาที)\\n• กล้ามเนื้ออ่อนแรงมาก เคลื่อนไหวไม่ได้\\n• ปัสสาวะน้อยมาก (< 25 mL/hr)","short_label":"เตรียม Ca gluconate ข้างเตียง · ตรวจ DTR + RR + UO"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000184', '1000184', '{"drug_name":"metFORMIN(*ชา)","special_pop":"• โรคไต CrCl < 30: CONTRAINDICATED (Lactic acidosis)\\n• Pregnancy Cat B — safe\\n• ผู้ใช้ Dolutegravir (HIV): เพิ่ม Metformin level 2 เท่า (ลด dose)","full_counseling":"• กินพร้อมอาหารหรือหลังอาหาร (ลด GI ADR)\\n• แจ้งก่อนตรวจ CT scan ที่ใช้ contrast dye — หยุดยา 48 ชม. ก่อน-หลัง\\n• ห้ามดื่มแอลกอฮอล์มาก (Lactic acidosis)\\n• ตรวจไตทุก 6-12 เดือน","storage":"≤ 30°C · ป้องกันความชื้น","when_to_er":"• คลื่นไส้อาเจียนรุนแรง + กล้ามเนื้อปวด + อ่อนเพลียมาก (Lactic acidosis)\\n• หายใจเร็วลึก (Kussmaul breathing)\\n• สับสน ไม่รู้สึกตัว","short_label":"กินพร้อมอาหาร · แจ้งก่อน CT scan ใช้ contrast","counseling_th":"• กินพร้อมอาหารหรือหลังอาหาร (ลด GI ADR)\\n• แจ้งก่อนตรวจ CT scan ที่ใช้ contrast dye — หยุดยา 48 ชม. ก่อน-หลัง\\n• ห้ามดื่มแอลกอฮอล์มาก (Lactic acidosis)\\n• ตรวจไตทุก 6-12 เดือน","icode":"1000184","food_interaction":"• ห้ามดื่มแอลกอฮอล์มาก\\n• กินอาหารสม่ำเสมอ ห้ามอดอาหาร","updatedAt":"2026-06-01T15:54:37.249Z"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000184_4', '1000184', '{"icode":"1000184","when_to_er":"• อาเจียนหรือท้องเสียรุนแรง\\n• อ่อนเพลียมาก หายใจหอบเร็ว","counseling_th":"• กินพร้อมอาหารหรือหลังอาหารทันที","special_pop":"• ห้ามใช้ถ้า eGFR < 30 mL/min\\n• ผู้สูงอายุ: ตรวจ eGFR ทุก 6-12 เดือน","full_counseling":"• กินพร้อมอาหารหรือหลังอาหารทันที","drug_name":"Metformin","food_interaction":"• แอลกอฮอล์เพิ่มความเสี่ยง lactic acidosis\\n• หยุดยา 48 ชั่วโมงก่อน-หลังฉีดสารทึบแสง","updatedAt":"2026-05-30T15:18:09.169Z","warning":"• อาเจียนหรือท้องเสียรุนแรง\\n• อ่อนเพลียมาก หายใจหอบเร็ว"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000188', '1000188', '{"food_interaction":"• ห้ามแอลกอฮอล์","updatedAt":"2026-06-01T15:54:37.249Z","icode":"1000188","counseling_th":"• ให้ IV infuse ช้าๆ ≥ 1 ชม. ห้าม IV push\\n• ห้ามดื่มแอลกอฮอล์และ 48 ชม. หลังหยุด","when_to_er":"• ชัก · ชาหรืออ่อนแรงมือเท้า","short_label":"ห้ามดื่มแอลกอฮอล์ · Infuse ช้า ≥ 1 ชม.","full_counseling":"• ให้ IV infuse ช้าๆ ≥ 1 ชม. ห้าม IV push\\n• ห้ามดื่มแอลกอฮอล์และ 48 ชม. หลังหยุด","special_pop":"• Pregnancy Cat B","drug_name":"metroNIdazole(*ชา)","storage":"≤ 30°C · ป้องกันแสง · เปิดใช้แล้วให้ใช้ให้หมด"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000188_41', '1000188', '{"special_pop":"• ตั้งครรภ์ไตรมาส 1: ระวัง\\n • ตับเสื่อม: ลดขนาด","full_counseling":"• กินพร้อมอาหาร\\n • ห้ามดื่มแอลกอฮอล์ระหว่างและ 48 ชม.หลังหยุดยา\\n • กินยาครบตามที่แพทย์สั่ง","drug_name":"Metronidazole","icode":"1000188","when_to_er":"• ชักหรืออาการทางประสาทผิดปกติ\\n • ผื่นแพ้รุนแรง","counseling_th":"• กินพร้อมอาหาร\\n • ห้ามดื่มแอลกอฮอล์ระหว่างและ 48 ชม.หลังหยุดยา\\n • กินยาครบตามที่แพทย์สั่ง","food_interaction":"• ห้ามดื่มแอลกอฮอล์เด็ดขาด (Disulfiram-like reaction)\\n • นมและอาหารลดการดูดซึมเล็กน้อย","warning":"• ชักหรืออาการทางประสาทผิดปกติ\\n • ผื่นแพ้รุนแรง","updatedAt":"2026-05-30T15:18:09.169Z","side_effect":"• คลื่นไส้ ปวดท้อง รสโลหะในปาก\\n • มึนงง ปวดหัว\\n • ปัสสาวะสีเข้มขึ้น"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000196', '1000196', '{"short_label":"ยาควบคุม · Monitor การหายใจ · เตรียม Naloxone","when_to_er":"• หายใจช้า < 12 ครั้ง/นาที · ริมฝีปากเขียว\\n• ไม่รู้สึกตัว · ม่านตาเล็กมาก (miosis)\\n• ปัสสาวะน้อยมาก","counseling_th":"• ยาระงับปวด อาจทำให้ง่วงซึม คลื่นไส้ ท้องผูก\\n• ห้ามขับรถหรือใช้เครื่องจักร\\n• แจ้งพยาบาลทันทีถ้าหายใจลำบาก\\n• ท้องผูก = ADR พบบ่อย ดื่มน้ำมาก + กินผักผลไม้\\n• ห้ามดื่มแอลกอฮอล์","icode":"1000196","storage":"เก็บในกล่องล็อก (Narcotic) · ≤ 25°C · ป้องกันแสง","drug_name":"morPHINE inj.","special_pop":"• Pregnancy Cat D — ทารกอาจติดยา\\n• โรคไต CrCl < 30: ลดขนาด + เพิ่ม interval (metabolite สะสม)\\n• OSA / COPD: ระวัง respiratory depression มาก\\n• สูงอายุ: เริ่มขนาดต่ำ","full_counseling":"• ยาระงับปวด อาจทำให้ง่วงซึม คลื่นไส้ ท้องผูก\\n• ห้ามขับรถหรือใช้เครื่องจักร\\n• แจ้งพยาบาลทันทีถ้าหายใจลำบาก\\n• ท้องผูก = ADR พบบ่อย ดื่มน้ำมาก + กินผักผลไม้\\n• ห้ามดื่มแอลกอฮอล์","updatedAt":"2026-06-01T15:54:37.249Z","food_interaction":"• ห้ามดื่มแอลกอฮอล์ (เพิ่ม CNS depression)\\n• ระวัง Grapefruit (CYP3A4)"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000236', '1000236', '{"food_interaction":"• ห้ามดื่มแอลกอฮอล์","updatedAt":"2026-06-01T15:54:37.249Z","storage":"เก็บในกล่องล็อก (Narcotic) · ≤ 25°C","drug_name":"peTHIDINE","special_pop":"• โรคไต (Cr > 2): CONTRAINDICATED (norpethidine seizure)\\n• ประวัติชัก: CONTRAINDICATED\\n• ผู้สูงอายุ: CONTRAINDICATED (delirium risk)\\n• Pregnancy Cat D\\n• MAOIs: ABSOLUTE CONTRAINDICATION (fatal)","full_counseling":"• ยาระงับปวด ห้ามใช้นานเกิน 48-72 ชม.\\n• แจ้งพยาบาลทันทีถ้าชัก สับสน มือสั่นมาก (norpethidine toxicity)\\n• ห้ามดื่มแอลกอฮอล์\\n• ห้ามขับรถ","when_to_er":"• ชัก (norpethidine seizure)\\n• มือสั่นรุนแรง เดินโซเซ สับสน เพ้อ\\n• หายใจช้า < 12 ครั้ง/นาที","short_label":"ยาควบคุม · ห้ามใช้ > 48 ชม. · ห้ามใน Renal failure","counseling_th":"• ยาระงับปวด ห้ามใช้นานเกิน 48-72 ชม.\\n• แจ้งพยาบาลทันทีถ้าชัก สับสน มือสั่นมาก (norpethidine toxicity)\\n• ห้ามดื่มแอลกอฮอล์\\n• ห้ามขับรถ","icode":"1000236"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000239', '1000239', '{"food_interaction":"• ห้ามแอลกอฮอล์\\n• Vit D3 supplement: ควรเสริม (Phenobarbital ลด Vit D)","updatedAt":"2026-06-01T15:54:37.249Z","icode":"1000239","counseling_th":"• กินยาเวลาเดิมทุกวัน ห้ามหยุดเองเด็ดขาด (withdrawal seizure)\\n• อาจง่วงซึมในช่วงแรก ดีขึ้นเองเมื่อร่างกายปรับตัว\\n• ห้ามขับรถหรือใช้เครื่องจักรในช่วงแรก\\n• แจ้งยาทุกชนิดที่ใช้ (DDI กับยาหลายชนิด)\\n• ห้ามดื่มแอลกอฮอล์","when_to_er":"• ชักมากขึ้นหรือชักครั้งแรก\\n• เดินโซเซ พูดไม่ชัด ตาพร่า (ระดับยาสูง)\\n• ผื่น ตุ่มพอง (SJS — หายากแต่เกิดได้)","short_label":"ห้ามหยุดยาเอง · กินเวลาเดิมทุกวัน · ห้ามขับรถ","special_pop":"• Pregnancy Cat D — neural tube defects\\n• Warfarin: ↓ INR (CYP induction)\\n• Valproate: ↑ Phenobarbital level","full_counseling":"• กินยาเวลาเดิมทุกวัน ห้ามหยุดเองเด็ดขาด (withdrawal seizure)\\n• อาจง่วงซึมในช่วงแรก ดีขึ้นเองเมื่อร่างกายปรับตัว\\n• ห้ามขับรถหรือใช้เครื่องจักรในช่วงแรก\\n• แจ้งยาทุกชนิดที่ใช้ (DDI กับยาหลายชนิด)\\n• ห้ามดื่มแอลกอฮอล์","drug_name":"phenoBARBITAL","storage":"≤ 25°C · ป้องกันแสง + ความชื้น"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000239_8', '1000239', '{"side_effect":"• ง่วงนอนมาก ซึม\\n• เดินเซ ทรงตัวไม่ดี\\n• สับสน ความจำไม่ดี\\n• ผื่นแพ้ผิวหนัง","food_interaction":"• แอลกอฮอล์เพิ่มฤทธิ์กดสมองรุนแรง\\n• หลีกเลี่ยงสมุนไพรหลายชนิด","warning":"• ชักถี่ขึ้นหรือรุนแรงขึ้นหลังหยุดยา\\n• ผื่นแดงรุนแรง ตุ่มพอง\\n• หายใจช้า หยุดหายใจ\\n• ซึมมาก หมดสติ","updatedAt":"2026-05-30T15:18:09.169Z","icode":"1000239","when_to_er":"• ชักถี่ขึ้นหรือรุนแรงขึ้นหลังหยุดยา\\n• ผื่นแดงรุนแรง ตุ่มพอง\\n• หายใจช้า หยุดหายใจ\\n• ซึมมาก หมดสติ","counseling_th":"• กินยาเวลาเดิมทุกวัน ห้ามหยุดยาเองเด็ดขาด\\n• ระวังการขับขี่และใช้เครื่องจักร\\n• ตรวจระดับยาตามนัด","special_pop":"• ตั้งครรภ์: เสี่ยงทารกพิการ ต้องให้ Folic acid เสริม\\n• เด็ก: อาจทำให้สมาธิสั้น","full_counseling":"• กินยาเวลาเดิมทุกวัน ห้ามหยุดยาเองเด็ดขาด\\n• ระวังการขับขี่และใช้เครื่องจักร\\n• ตรวจระดับยาตามนัด","drug_name":"Phenobarbital"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000242_5', '1000242', '{"drug_name":"Phenytoin","full_counseling":"• กินยาเวลาเดิมทุกวัน ห้ามหยุดยาเองเด็ดขาด\\n• ตรวจระดับยาในเลือดตามนัด\\n• แปรงฟันอย่างถูกวิธี","special_pop":"• ตั้งครรภ์: มีความเสี่ยงต่อทารก ปรึกษาแพทย์\\n• เด็ก: คำนวณขนาดตามน้ำหนัก","when_to_er":"• ชักถี่ขึ้นหรือรุนแรงขึ้นหลังหยุดยา\\n• ผื่นแดงลามทั่วตัวหรือตุ่มพอง\\n• ตาพร่า เห็นภาพซ้อน เดินไม่ได้\\n• ไข้สูงร่วมกับผื่น","counseling_th":"• กินยาเวลาเดิมทุกวัน ห้ามหยุดยาเองเด็ดขาด\\n• ตรวจระดับยาในเลือดตามนัด\\n• แปรงฟันอย่างถูกวิธี","icode":"1000242","food_interaction":"• แอลกอฮอล์เพิ่มพิษยา\\n• น้ำส้มโอ ลดการดูดซึมยา\\n• กินพร้อมอาหารถ้ามีอาการท้องไม่สบาย","warning":"• ชักถี่ขึ้นหรือรุนแรงขึ้นหลังหยุดยา\\n• ผื่นแดงลามทั่วตัวหรือตุ่มพอง\\n• ตาพร่า เห็นภาพซ้อน เดินไม่ได้\\n• ไข้สูงร่วมกับผื่น","updatedAt":"2026-05-30T15:18:09.169Z","side_effect":"• ง่วงนอน เดินเซ\\n• เหงือกบวมโต\\n• ผมร่วง\\n• ผื่นแพ้ผิวหนัง (ต้องแจ้งแพทย์ทันที)"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000245', '1000245', '{"drug_name":"KCl injection (HAD)","special_pop":"• โรคไตรุนแรง: CONTRAINDICATED\\n• Pregnancy Cat A","full_counseling":"• ยานี้ให้ทางเส้นเลือดเพื่อทดแทนโพแทสเซียมในร่างกาย\\n• อาจรู้สึกปวดหรือแสบบริเวณที่ให้ยา แจ้งพยาบาลทันที\\n• ต้องตรวจเลือดระหว่างการให้ยา","storage":"อุณหภูมิห้อง · คงตัว 24 ชม. หลังผสม","short_label":"ห้าม IV Push · ต้องเจือจางก่อน · Infusion pump","when_to_er":"• ใจสั่น หัวใจเต้นผิดปกติ\\n• กล้ามเนื้ออ่อนแรงมาก ตะคริวรุนแรง\\n• หายใจลำบาก\\n• บริเวณ IV ปวดรุนแรง บวม (extravasation)","counseling_th":"• ยานี้ให้ทางเส้นเลือดเพื่อทดแทนโพแทสเซียมในร่างกาย\\n• อาจรู้สึกปวดหรือแสบบริเวณที่ให้ยา แจ้งพยาบาลทันที\\n• ต้องตรวจเลือดระหว่างการให้ยา","icode":"1000245","updatedAt":"2026-06-01T15:54:37.249Z","food_interaction":"• หลังพักฟื้น: กินอาหารที่มีโพแทสเซียมสูง (กล้วย ส้ม มะเขือเทศ มันฝรั่ง)\\n• ห้ามซื้อ NSAIDs ร่วมโดยไม่ปรึกษาแพทย์"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000249', '1000249', '{"updatedAt":"2026-06-01T15:54:37.249Z","food_interaction":"• กินพร้อมอาหาร\\n• ลดอาหารเค็ม ของหวาน (ยาทำให้บวมน้ำ + น้ำตาลขึ้น)","short_label":"ห้ามหยุดทันที (ถ้าใช้นาน) · ตรวจ DTX · ป้องกันกระเพาะ","when_to_er":"• ปวดท้องมาก อาเจียนเลือด อุจจาระดำ (GI bleeding)\\n• ไข้สูง มีการติดเชื้อ (ยากดภูมิ)\\n• กล้ามเนื้ออ่อนแรง บวมมาก ความดันสูง (Cushing-like)","counseling_th":"• กินพร้อมหรือหลังอาหาร (ป้องกันระคายเคืองกระเพาะ)\\n• ห้ามหยุดทันทีถ้าใช้มานาน > 2 สัปดาห์ (adrenal insufficiency)\\n• น้ำตาลในเลือดอาจสูงขึ้น — ตรวจ DTX ถ้าเป็น DM\\n• ระวัง infection (ยากดภูมิคุ้มกัน)","icode":"1000249","storage":"≤ 25°C · ป้องกันความชื้น","drug_name":"predNISOLONE","full_counseling":"• กินพร้อมหรือหลังอาหาร (ป้องกันระคายเคืองกระเพาะ)\\n• ห้ามหยุดทันทีถ้าใช้มานาน > 2 สัปดาห์ (adrenal insufficiency)\\n• น้ำตาลในเลือดอาจสูงขึ้น — ตรวจ DTX ถ้าเป็น DM\\n• ระวัง infection (ยากดภูมิคุ้มกัน)","special_pop":"• Pregnancy Cat C\\n• DM: monitor DTX ถี่ขึ้น\\n• ห้ามฉีดวัคซีนมีชีวิต (BCG, MMR, Varicella) ขณะใช้ยา dose สูง"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000249_15', '1000249', '{"icode":"1000249","when_to_er":"• ไข้สูง ติดเชื้อรุนแรง ไม่ตอบสนองต่อการรักษา\\n• ปวดท้องรุนแรง ถ่ายอุจจาระดำ\\n• กล้ามเนื้ออ่อนแรงรุนแรง\\n• วิกฤตหลังหยุดยาเอง (Adrenal crisis)","counseling_th":"• กินพร้อมอาหารเพื่อลดการระคายเคืองกระเพาะ\\n• ห้ามหยุดยาเองหรือลดขนาดเองโดยไม่ปรึกษาแพทย์\\n• รายงานแพทย์ถ้ามีไข้หรือเจ็บป่วย","special_pop":"• ผู้ป่วย DM: ต้องติดตาม FBS อย่างใกล้ชิด\\n• ผู้ป่วย HT: ติดตามความดันโลหิต","full_counseling":"• กินพร้อมอาหารเพื่อลดการระคายเคืองกระเพาะ\\n• ห้ามหยุดยาเองหรือลดขนาดเองโดยไม่ปรึกษาแพทย์\\n• รายงานแพทย์ถ้ามีไข้หรือเจ็บป่วย","drug_name":"Prednisolone","side_effect":"• น้ำตาลในเลือดสูง\\n• ความดันโลหิตสูง\\n• น้ำหนักขึ้น บวม หน้ากลม\\n• กระดูกพรุนถ้าใช้นาน\\n• ภูมิคุ้มกันลดลง","food_interaction":"• หลีกเลี่ยงอาหารเค็มและหวานจัด\\n• เพิ่มอาหารที่มี Calcium และ Vitamin D","warning":"• ไข้สูง ติดเชื้อรุนแรง ไม่ตอบสนองต่อการรักษา\\n• ปวดท้องรุนแรง ถ่ายอุจจาระดำ\\n• กล้ามเนื้ออ่อนแรงรุนแรง\\n• วิกฤตหลังหยุดยาเอง (Adrenal crisis)","updatedAt":"2026-05-30T15:18:09.169Z"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000252', '1000252', '{"icode":"1000252","when_to_er":"• ปัสสาวะสีเข้มมาก/ดำ (hemolysis)\\n• ซีดมาก อ่อนเพลียมาก ใจสั่น (hemolytic anemia)\\n• ตัวเหลือง ตาเหลือง","short_label":"ตรวจ G6PD ก่อนทุกครั้ง · ปัสสาวะดำ = หยุดยาด่วน","counseling_th":"• ต้องตรวจ G6PD ก่อนให้ยาทุกครั้ง\\n• ห้ามให้ถ้า G6PD ขาด (hemolytic anemia รุนแรง)\\n• แจ้งทันทีถ้าปัสสาวะสีเข้มหรือดำ หรืออ่อนเพลียมากผิดปกติ\\n• กินพร้อมอาหาร","storage":"≤ 25°C · ป้องกันแสง","drug_name":"priMAQUINE","full_counseling":"• ต้องตรวจ G6PD ก่อนให้ยาทุกครั้ง\\n• ห้ามให้ถ้า G6PD ขาด (hemolytic anemia รุนแรง)\\n• แจ้งทันทีถ้าปัสสาวะสีเข้มหรือดำ หรืออ่อนเพลียมากผิดปกติ\\n• กินพร้อมอาหาร","special_pop":"• G6PD deficiency: CONTRAINDICATED (hemolytic anemia)\\n• Pregnancy: CONTRAINDICATED","updatedAt":"2026-06-01T15:54:37.249Z"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000257', '1000257', '{"food_interaction":"• ไม่ต้องงดอาหารไอโอดีน แต่กินสม่ำเสมอ","updatedAt":"2026-06-01T15:54:37.249Z","icode":"1000257","counseling_th":"• กินยาตรงเวลาสม่ำเสมอทุก 8 ชม.\\n• ถ้ามีไข้ เจ็บคอ อ่อนเพลียมาก — หยุดยาทันทีและตรวจเลือด CBC ด่วน (agranulocytosis)\\n• ห้ามหยุดยาเองโดยไม่ปรึกษาแพทย์ (thyroid storm)\\n• ตรวจไทรอยด์ทุก 4-6 สัปดาห์ในช่วงแรก","when_to_er":"• ไข้สูง เจ็บคอ อ่อนเพลียมาก (agranulocytosis — อันตราย)\\n• ตัวเหลือง ตาเหลือง (hepatotoxicity — PTU Black Box)\\n• ใจสั่น เหงื่อออกมาก น้ำหนักลดเร็ว (thyroid storm)","short_label":"ไข้เจ็บคอ = หยุดยา+ตรวจ CBC ด่วน","storage":"≤ 25°C · ป้องกันความชื้น","special_pop":"• Pregnancy T1: PTU preferred (Methimazole ทำให้พิการแต่กำเนิด T1)\\n• หลัง T1: เปลี่ยนเป็น Methimazole\\n• Pregnancy Cat D","full_counseling":"• กินยาตรงเวลาสม่ำเสมอทุก 8 ชม.\\n• ถ้ามีไข้ เจ็บคอ อ่อนเพลียมาก — หยุดยาทันทีและตรวจเลือด CBC ด่วน (agranulocytosis)\\n• ห้ามหยุดยาเองโดยไม่ปรึกษาแพทย์ (thyroid storm)\\n• ตรวจไทรอยด์ทุก 4-6 สัปดาห์ในช่วงแรก","drug_name":"PTU-propylTHIOURACIL"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000257_34', '1000257', '{"icode":"1000257","counseling_th":"• กินพร้อมอาหาร วันละ 3 ครั้ง\\n • ห้ามหยุดยาเองเด็ดขาด\\n • ตรวจ LFT และ CBC ตามนัด","when_to_er":"• ตัวเหลือง ตาเหลือง ปวดท้องมาก\\n • ไข้สูงกะทันหัน เจ็บคอ\\n • อ่อนเพลียมากผิดปกติ","special_pop":"• ตั้งครรภ์: PTU ปลอดภัยในไตรมาส 1\\n • Hepatotoxicity สูงกว่า Methimazole","full_counseling":"• กินพร้อมอาหาร วันละ 3 ครั้ง\\n • ห้ามหยุดยาเองเด็ดขาด\\n • ตรวจ LFT และ CBC ตามนัด","drug_name":"Propylthiouracil","side_effect":"• ผื่น คัน ลมพิษ\\n • ตับอักเสบรุนแรง (PTU > Methimazole)\\n • เม็ดเลือดขาวต่ำ","food_interaction":"• หลีกเลี่ยงอาหารที่มีไอโอดีนสูง","updatedAt":"2026-05-30T15:18:09.169Z","warning":"• ตัวเหลือง ตาเหลือง ปวดท้องมาก\\n • ไข้สูงกะทันหัน เจ็บคอ\\n • อ่อนเพลียมากผิดปกติ"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000268', '1000268', '{"storage":"≤ 30°C · ห้ามแดด","drug_name":"Ventolin MDI","full_counseling":"• ยาขยายหลอดลม ใช้เมื่อมีอาการ (Rescue inhaler)\\n• ถ้าต้องใช้ > 2 ครั้ง/สัปดาห์ = โรคควบคุมไม่ดี แจ้งแพทย์\\n• วิธีพ่นยา: หายใจออกก่อน → ใส่ไว้ที่ปาก → กดยา + หายใจเข้าพร้อมกัน → กลั้นหายใจ 10 วินาที","special_pop":"• Pregnancy Cat C\\n• ผู้ป่วยหัวใจ: ระวัง tachycardia","when_to_er":"• หายใจลำบากมากขึ้นแม้พ่นยาแล้ว (ต้องไป ER)\\n• ใจสั่นมาก มือสั่นรุนแรง (toxicity จากใช้มากเกิน)","short_label":"ใช้เมื่อมีอาการ · ถ้าใช้บ่อยมาก = ควบคุมโรคไม่ดี","counseling_th":"• ยาขยายหลอดลม ใช้เมื่อมีอาการ (Rescue inhaler)\\n• ถ้าต้องใช้ > 2 ครั้ง/สัปดาห์ = โรคควบคุมไม่ดี แจ้งแพทย์\\n• วิธีพ่นยา: หายใจออกก่อน → ใส่ไว้ที่ปาก → กดยา + หายใจเข้าพร้อมกัน → กลั้นหายใจ 10 วินาที","icode":"1000268","updatedAt":"2026-06-01T15:54:37.249Z"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1000284_21', '1000284', '{"icode":"1000284","when_to_er":"• กล้ามเนื้ออ่อนแรง ชา ใจสั่น (K+ สูงมาก)\\n• ปัสสาวะน้อยลงมาก\\n• ความดันต่ำมาก","counseling_th":"• กินพร้อมอาหาร\\n• ลดอาหารเค็มตามคำแนะนำแพทย์\\n• ติดตาม K+ ในเลือดสม่ำเสมอ","special_pop":"• ห้ามใช้ในไตวายเฉียบพลัน\\n• ผู้สูงอายุ: เสี่ยง K+ สูงมากขึ้น","full_counseling":"• กินพร้อมอาหาร\\n• ลดอาหารเค็มตามคำแนะนำแพทย์\\n• ติดตาม K+ ในเลือดสม่ำเสมอ","drug_name":"Spironolactone","side_effect":"• K+ ในเลือดสูง\\n• เต้านมโตในผู้ชาย (Gynecomastia)\\n• ประจำเดือนผิดปกติในผู้หญิง\\n• ปัสสาวะบ่อย","food_interaction":"• หลีกเลี่ยง K+ supplement และ NSAID\\n• ลดอาหารที่มี K+ สูง (กล้วย มะเขือเทศ)","warning":"• กล้ามเนื้ออ่อนแรง ชา ใจสั่น (K+ สูงมาก)\\n• ปัสสาวะน้อยลงมาก\\n• ความดันต่ำมาก","updatedAt":"2026-05-30T15:18:09.169Z"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1019001_29', '1019001', '{"special_pop":"• ผู้สูงอายุ: เสี่ยง hypoglycemia สูง เป้าหมาย FBS 100-150\\n • ไตเสื่อม eGFR<10: หลีกเลี่ยง","full_counseling":"• กินก่อนอาหาร 30 นาที\\n • ห้ามหยุดยาเองโดยไม่ปรึกษาแพทย์\\n • วัดน้ำตาลตามนัด\\n • แจ้งแพทย์ถ้ามีน้ำตาลต่ำบ่อย","drug_name":"Glipizide","icode":"1019001","counseling_th":"• กินก่อนอาหาร 30 นาที\\n • ห้ามหยุดยาเองโดยไม่ปรึกษาแพทย์\\n • วัดน้ำตาลตามนัด\\n • แจ้งแพทย์ถ้ามีน้ำตาลต่ำบ่อย","when_to_er":"• น้ำตาลต่ำมาก ชัก หมดสติ\\n • ไม่สามารถกินอาหารหรือดื่มน้ำได้","food_interaction":"• แอลกอฮอล์เพิ่มเสี่ยงน้ำตาลต่ำ\\n • กินอาหารสม่ำเสมอ ไม่ข้ามมื้อ","updatedAt":"2026-05-30T15:18:09.169Z","warning":"• น้ำตาลต่ำมาก ชัก หมดสติ\\n • ไม่สามารถกินอาหารหรือดื่มน้ำได้","side_effect":"• น้ำตาลในเลือดต่ำ (ใจสั่น เหงื่อออก มือสั่น)\\n • คลื่นไส้ ท้องอืด\\n • น้ำหนักขึ้น"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1420102', '1420102', '{"icode":"1420102","counseling_th":"• ยาหยุดการเจ็บครรภ์ชั่วคราว\\n• อาจรู้สึกใจสั่น มือสั่น วิตกกังวล เป็นผลปกติ\\n• แจ้งพยาบาลทันทีถ้าแน่นหน้าอก หายใจลำบาก (Pulmonary edema)\\n• ห้ามใช้นานเกิน 48-72 ชม. (FDA Warning)","when_to_er":"• แน่นหน้าอก หายใจลำบากมาก (Pulmonary edema)\\n• HR > 130 ครั้ง/นาที\\n• ความดันต่ำผิดปกติ","short_label":"แจ้งถ้าแน่นหน้าอกหรือใจสั่น · ห้ามใช้นาน > 48 ชม.","special_pop":"• DM: ตรวจ DTX ทุก 4-6 ชม. (Hyperglycemia)\\n• Pregnancy Cat B\\n• ห้ามใน Cardiac arrhythmia / Hypertension","full_counseling":"• ยาหยุดการเจ็บครรภ์ชั่วคราว\\n• อาจรู้สึกใจสั่น มือสั่น วิตกกังวล เป็นผลปกติ\\n• แจ้งพยาบาลทันทีถ้าแน่นหน้าอก หายใจลำบาก (Pulmonary edema)\\n• ห้ามใช้นานเกิน 48-72 ชม. (FDA Warning)","drug_name":"terBUTALINE SULFATE (HAD)","storage":"2-8°C ก่อนเปิด · หลังเปิดใช้ทันที ทิ้งส่วนที่เหลือ","updatedAt":"2026-06-01T15:54:37.249Z"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1430901', '1430901', '{"short_label":"กินเช้าท้องว่าง 30-60 นาทีก่อนอาหาร · ห้ามเปลี่ยนยี่ห้อเอง","when_to_er":"• ใจสั่น หัวใจเต้นเร็ว เจ็บหน้าอก (dose สูงเกิน)\\n• เหงื่อออกมาก น้ำหนักลด นอนไม่หลับ","counseling_th":"• กินยาเวลาเดิมทุกเช้า ท้องว่าง 30-60 นาที ก่อนอาหาร\\n• ห้ามเปลี่ยนยี่ห้อโดยไม่ปรึกษาแพทย์ (bioavailability ต่างกัน)\\n• ตรวจ TSH ทุก 6-8 สัปดาห์ช่วงแรก\\n• ห้ามหยุดยาเอง","icode":"1430901","drug_name":"ELTROXIN-THYROXIN SODIUM*","special_pop":"• โรคหัวใจ: เริ่มขนาดต่ำมาก เพิ่มช้าๆ\\n• Pregnancy Cat A — ต้องการขนาดเพิ่มขึ้น 30-50%","full_counseling":"• กินยาเวลาเดิมทุกเช้า ท้องว่าง 30-60 นาที ก่อนอาหาร\\n• ห้ามเปลี่ยนยี่ห้อโดยไม่ปรึกษาแพทย์ (bioavailability ต่างกัน)\\n• ตรวจ TSH ทุก 6-8 สัปดาห์ช่วงแรก\\n• ห้ามหยุดยาเอง","storage":"≤ 25°C · ป้องกันแสง + ความชื้น","updatedAt":"2026-06-01T15:54:37.249Z","food_interaction":"• ยาแคลเซียม / ยาธาตุเหล็ก / antacid: แยก ≥ 4 ชม.\\n• กาแฟ: ลด absorption ลดลง 25-35% — ดื่มหลังกินยา ≥ 30 นาที\\n• นม / ผลิตภัณฑ์ถั่วเหลือง: ลด absorption"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1430901_24', '1430901', '{"drug_name":"Levothyroxine","special_pop":"• ผู้สูงอายุ หัวใจ: เริ่มขนาดต่ำ ค่อยปรับขึ้น\\n• ตั้งครรภ์: ต้องการขนาดสูงขึ้น ติดตาม TSH","full_counseling":"• กินตอนเช้าท้องว่าง ก่อนอาหาร 30-60 นาที\\n• กินยาเวลาเดิมสม่ำเสมอ\\n• ตรวจ TSH ทุก 6 เดือน-1 ปี หรือตามแพทย์กำหนด","when_to_er":"• ใจสั่นรุนแรง เจ็บหน้าอก หายใจลำบาก\\n• ชักหรือหมดสติ\\n• ไข้สูง กระสับกระส่ายมาก (Thyroid storm)","counseling_th":"• กินตอนเช้าท้องว่าง ก่อนอาหาร 30-60 นาที\\n• กินยาเวลาเดิมสม่ำเสมอ\\n• ตรวจ TSH ทุก 6 เดือน-1 ปี หรือตามแพทย์กำหนด","icode":"1430901","food_interaction":"• นมและผลิตภัณฑ์นม แคลเซียม ธาตุเหล็ก กินก่อนอาหาร\\n• ซอยา (Soy products) ลดการดูดซึม","updatedAt":"2026-05-30T15:18:09.169Z","warning":"• ใจสั่นรุนแรง เจ็บหน้าอก หายใจลำบาก\\n• ชักหรือหมดสติ\\n• ไข้สูง กระสับกระส่ายมาก (Thyroid storm)","side_effect":"• ใจสั่น หัวใจเต้นเร็ว (ถ้าขนาดสูงเกิน)\\n• นอนไม่หลับ กระวนกระวาย\\n• น้ำหนักลด ท้องเสีย (ขนาดสูงเกิน)\\n• ปวดหัว เหงื่อออกมาก"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1440205', '1440205', '{"icode":"1440205","counseling_th":"• กินยาเวลาเดิม ห้ามเคี้ยวหรือบด (SR tablet)\\n• ห้ามหยุดสูบบุหรี่กะทันหัน (ระดับยาขึ้นสูง → toxicity)\\n• ลดกาแฟ/ชา\\n• ตรวจระดับยาในเลือดตามนัด","when_to_er":"• คลื่นไส้อาเจียนรุนแรง ใจสั่น หัวใจเต้นผิดจังหวะ (toxicity)\\n• ชัก (severe toxicity — level > 30 mcg/mL)","short_label":"ห้ามยาแก้ติดเชื้อบางตัวร่วม · ตรวจ level","storage":"≤ 25°C · ป้องกันความชื้น","special_pop":"• Pregnancy Cat C\\n• โรคหัวใจ: ระวัง arrhythmia\\n• ผู้สูงอายุ: ↑ toxicity risk","full_counseling":"• กินยาเวลาเดิม ห้ามเคี้ยวหรือบด (SR tablet)\\n• ห้ามหยุดสูบบุหรี่กะทันหัน (ระดับยาขึ้นสูง → toxicity)\\n• ลดกาแฟ/ชา\\n• ตรวจระดับยาในเลือดตามนัด","drug_name":"THEOPHYLLINE(*ชา)","food_interaction":"• ลดกาแฟ/ชา/น้ำอัดลม Caffeine (เพิ่ม ADR)\\n• อาหารมัน/น้ำมันสูง: ลด absorption ของบาง formulation","updatedAt":"2026-06-01T15:54:37.249Z"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1460151_18', '1460151', '{"drug_name":"Enalapril 20mg","special_pop":"• ตั้งครรภ์ไตรมาส 2-3: ห้ามใช้\\n• ไตเสื่อม: ปรับขนาดตาม eGFR","full_counseling":"หากมีอาการไอเรื้อรัง หลังกินยา โปรดแจ้งแพทย์","when_to_er":"• บวมหน้า ลิ้น หรือคอ หายใจลำบาก \\n• ปัสสาวะน้อย ปัสสาวะไม่ออก","counseling_th":"หากมีอาการไอเรื้อรัง หลังกินยา โปรดแจ้งแพทย์","icode":"1460151","food_interaction":"• หลีกเลี่ยงอาหารที่มี K+ สูงถ้าใช้ร่วม K-sparing diuretic","updatedAt":"2026-05-30T15:18:09.169Z","warning":"• บวมหน้า ลิ้น หรือคอ หายใจลำบาก \\n• ปัสสาวะน้อย ปัสสาวะไม่ออก"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1460192', '1460192', '{"short_label":"RI = ใส · NPH = ขุ่น · ตรวจ DTX ก่อนทุกครั้ง","when_to_er":"• น้ำตาลต่ำ: ใจสั่น เหงื่อออก มือสั่น วิตกกังวล ปวดหัว สับสน (กิน glucose ทันที)\\n• ไม่รู้สึกตัว ชัก (severe hypoglycemia → 50% Dextrose IV / Glucagon IM)\\n• DTX < 70 mg/dL + มีอาการ","counseling_th":"• ตรวจน้ำตาลในเลือด (DTX) ก่อนฉีดยาทุกครั้ง\\n• RI = ใส, NPH = ขุ่น — ดูสีก่อนทุกครั้ง\\n• ฉีดเข้าชั้นไขมันใต้ผิวหนัง (ท้อง ต้นขา แขน) สลับตำแหน่ง\\n• กินอาหารหลังฉีด RI ทันที (ภายใน 30 นาที)\\n• เก็บขวดที่เปิดแล้วได้ 28-30 วัน ที่อุณหภูมิห้อง\\n• ห้ามขับรถถ้า DTX < 70 mg/dL","icode":"1460192","drug_name":"HUMULIN -R   คิดราคาต่อ 1 unit","special_pop":"• Pregnancy Cat B\\n• โรคไต: ลดขนาด insulin (ไตขับ insulin ลดลง)\\n• ผู้ใช้ β-blocker: อาจ mask hypoglycemia (ยกเว้น diaphoresis)","full_counseling":"• ตรวจน้ำตาลในเลือด (DTX) ก่อนฉีดยาทุกครั้ง\\n• RI = ใส, NPH = ขุ่น — ดูสีก่อนทุกครั้ง\\n• ฉีดเข้าชั้นไขมันใต้ผิวหนัง (ท้อง ต้นขา แขน) สลับตำแหน่ง\\n• กินอาหารหลังฉีด RI ทันที (ภายใน 30 นาที)\\n• เก็บขวดที่เปิดแล้วได้ 28-30 วัน ที่อุณหภูมิห้อง\\n• ห้ามขับรถถ้า DTX < 70 mg/dL","storage":"ยังไม่เปิด: ตู้เย็น 2-8°C · เปิดแล้ว: ≤ 30°C ใช้ได้ 28-30 วัน · ห้ามแช่แข็ง","updatedAt":"2026-06-01T15:54:37.249Z","food_interaction":"• กินอาหาร 3 มื้อ/วัน ตรงเวลา\\n• ระวัง: กินน้อยกว่าปกติ + ฉีด insulin เท่าเดิม → น้ำตาลต่ำ"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1460236', '1460236', '{"updatedAt":"2026-06-01T15:54:37.249Z","storage":"≤ 25°C · ป้องกันแสง","special_pop":"• Opioid-dependent patients: ให้ช้าๆ ขนาดน้อย (ป้องกัน acute withdrawal)\\n• Pregnancy Cat B","full_counseling":"• ยานี้แก้ฤทธิ์ยาระงับปวดชั่วคราว\\n• ผู้ป่วยอาจรู้สึกปวดกลับมาหรือหงุดหงิดได้\\n• ต้องนอนพักที่โรงพยาบาล ≥ 2-4 ชม. เนื่องจากยาแก้พิษออกฤทธิ์สั้นกว่ายาระงับปวด\\n• แจ้งทันทีถ้าหายใจลำบากอีกครั้ง","drug_name":"[HAD] NALOXONE*","icode":"1460236","counseling_th":"• ยานี้แก้ฤทธิ์ยาระงับปวดชั่วคราว\\n• ผู้ป่วยอาจรู้สึกปวดกลับมาหรือหงุดหงิดได้\\n• ต้องนอนพักที่โรงพยาบาล ≥ 2-4 ชม. เนื่องจากยาแก้พิษออกฤทธิ์สั้นกว่ายาระงับปวด\\n• แจ้งทันทีถ้าหายใจลำบากอีกครั้ง","when_to_er":"• หายใจช้า < 12 ครั้ง/นาที (re-narcotization)\\n• ไม่รู้สึกตัว · ริมฝีปากเขียว\\n• ชัก (buprenorphine overdose ต้องการ naloxone dose สูงมาก)","short_label":"Monitor ≥ 2-4 ชม. · ยาออกฤทธิ์สั้นกว่ายาระงับปวด"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1460309', '1460309', '{"icode":"1460309","counseling_th":"• บ้วนปากด้วยน้ำ + บ้วนคอทุกครั้งหลังพ่นยา (ป้องกัน oral candidiasis)\\n• ใช้สม่ำเสมอทุกวัน แม้ไม่มีอาการ (ยาป้องกัน ไม่ใช่ยาแก้เฉียบพลัน)\\n• ห้ามหยุดยาเองโดยไม่ปรึกษา","when_to_er":"• หายใจลำบากหลังพ่นยา (ไม่ดีขึ้น)\\n• ปวดปากหรือมีแผลขาวในปาก (oral candidiasis)","short_label":"บ้วนปากทุกครั้งหลังพ่น","storage":"≤ 30°C · ป้องกันแสง + ความร้อน","special_pop":"• Pregnancy Cat B\\n• เด็กเล็ก: ใช้ spacer ร่วมด้วย","full_counseling":"• บ้วนปากด้วยน้ำ + บ้วนคอทุกครั้งหลังพ่นยา (ป้องกัน oral candidiasis)\\n• ใช้สม่ำเสมอทุกวัน แม้ไม่มีอาการ (ยาป้องกัน ไม่ใช่ยาแก้เฉียบพลัน)\\n• ห้ามหยุดยาเองโดยไม่ปรึกษา","drug_name":"Pulmicort-BUDESONIDE  Inhalation","updatedAt":"2026-06-01T15:54:37.249Z"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1460328', '1460328', '{"icode":"1460328","counseling_th":"• ยาแก้กรดในเลือด ให้ทางเส้นเลือด\\n• ต้องตรวจค่าเลือด (ABG) ระหว่างให้ยา\\n• ห้ามผสมกับยาอื่นในสายเดียวกัน","when_to_er":"• หายใจตื้น ช้า (overcorrection alkalosis)\\n• มือเท้าชา เป็นตะคริว (hypocalcemia จาก alkalosis)\\n• สับสน ชัก (sodium overload)","short_label":"Flush NSS ก่อน/หลัง · ห้ามผสมยาอื่น · เจือจาง 1:1 ในทารก","storage":"≤ 30°C · ห้ามแช่แข็ง","special_pop":"• ทารก: เจือจาง 1:1 ก่อนให้ (ห้ามฉีดเร็ว → IVH)\\n• Pregnancy Cat C","full_counseling":"• ยาแก้กรดในเลือด ให้ทางเส้นเลือด\\n• ต้องตรวจค่าเลือด (ABG) ระหว่างให้ยา\\n• ห้ามผสมกับยาอื่นในสายเดียวกัน","drug_name":"(HAD) sodium BICARBONATE 7.5%","food_interaction":"• ยาลดกรดกิน (antacid): แยก ≥ 2 ชม. จาก quinolone/tetracycline","updatedAt":"2026-06-01T15:54:37.249Z"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1460340_11', '1460340', '{"icode":"1460340","when_to_er":"• หูอื้อรุนแรง หรือหูหนวกกะทันหัน\\n• วิงเวียนหมุนรุนแรง\\n• ปัสสาวะน้อย หรือปัสสาวะเป็นฟอง","counseling_th":"• ฉีดโดยเจ้าหน้าที่เท่านั้น ตรวจการได้ยินก่อนและระหว่างรักษา\\n• ห้ามหยุดยาเองในการรักษา TB","special_pop":"• ห้ามใช้ในตั้งครรภ์ (หูหนวกทารก)\\n• ผู้สูงอายุและไตเสื่อม: ต้องปรับขนาด","full_counseling":"• ฉีดโดยเจ้าหน้าที่เท่านั้น ตรวจการได้ยินก่อนและระหว่างรักษา\\n• ห้ามหยุดยาเองในการรักษา TB","drug_name":"Streptomycin sulphate","side_effect":"• หูอื้อ ได้ยินลดลง (ถาวรได้)\\n• วิงเวียนทรงตัวไม่ดี\\n• ชาบริเวณปากและมือเท้า\\n• ไตเสียหาย","food_interaction":"• หลีกเลี่ยง Furosemide และ aminoglycosides อื่น","warning":"• หูอื้อรุนแรง หรือหูหนวกกะทันหัน\\n• วิงเวียนหมุนรุนแรง\\n• ปัสสาวะน้อย หรือปัสสาวะเป็นฟอง","updatedAt":"2026-05-30T15:18:09.169Z"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1460343', '1460343', '{"updatedAt":"2026-06-01T15:54:37.249Z","drug_name":"oXYTOCIN (HAD)","special_pop":"• ห้ามให้ร่วม Misoprostol ภายใน 6-8 ชม. (uterine rupture)\\n• Pregnancy Cat C/X","full_counseling":"• ยานี้กระตุ้นการเจ็บครรภ์หรือควบคุมเลือดออกหลังคลอด\\n• แจ้งพยาบาลทันทีถ้าเจ็บครรภ์รุนแรงผิดปกติ\\n• แจ้งถ้ารู้สึกว่าลูกดิ้นน้อยลง\\n• Monitor ปริมาณปัสสาวะ (ยามีผล ADH-like ทำให้น้ำเกิน)","storage":"≤ 25°C · ป้องกันแสง · ห้ามแช่แข็ง","counseling_th":"• ยานี้กระตุ้นการเจ็บครรภ์หรือควบคุมเลือดออกหลังคลอด\\n• แจ้งพยาบาลทันทีถ้าเจ็บครรภ์รุนแรงผิดปกติ\\n• แจ้งถ้ารู้สึกว่าลูกดิ้นน้อยลง\\n• Monitor ปริมาณปัสสาวะ (ยามีผล ADH-like ทำให้น้ำเกิน)","short_label":"แจ้งถ้าเจ็บมากผิดปกติหรือลูกดิ้นน้อย","when_to_er":"• เจ็บครรภ์รุนแรงต่อเนื่องไม่หาย > 5 ครั้ง/10 นาที\\n• ลูกดิ้นน้อยหรือไม่ดิ้น\\n• ปวดหัวรุนแรง มองเห็นผิดปกติ สับสน (water intoxication)\\n• ปัสสาวะน้อยมาก","icode":"1460343"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1470019_40', '1470019', '{"side_effect":"• คลื่นไส้ เบื่ออาหาร ช่วงแรก\\n • นอนไม่หลับ วิตกกังวล\\n • ความต้องการทางเพศลดลง","food_interaction":"• MAOIs: ห้ามใช้ร่วมเด็ดขาด (Serotonin syndrome)\\n • น้ำส้มโอ เพิ่มระดับยา","warning":"• มีความคิดทำร้ายตัวเอง\\n • ชัก กล้ามเนื้อเกร็ง ไข้สูง\\n • ผื่นแพ้รุนแรง","updatedAt":"2026-05-30T15:18:09.169Z","icode":"1470019","when_to_er":"• มีความคิดทำร้ายตัวเอง\\n • ชัก กล้ามเนื้อเกร็ง ไข้สูง\\n • ผื่นแพ้รุนแรง","counseling_th":"• กินตอนเช้า เพื่อลดการนอนไม่หลับ\\n • ผลรักษาอาจใช้เวลา 2-4 สัปดาห์\\n • ห้ามหยุดยาเองเด็ดขาด","special_pop":"• เด็กและวัยรุ่น: ระวังความคิดทำร้ายตัวเอง","full_counseling":"• กินตอนเช้า เพื่อลดการนอนไม่หลับ\\n • ผลรักษาอาจใช้เวลา 2-4 สัปดาห์\\n • ห้ามหยุดยาเองเด็ดขาด","drug_name":"Fluoxetine"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1470024_14', '1470024', '{"special_pop":"• ผู้สูงอายุ: เพิ่มเสี่ยงงงงวยและหกล้ม\\n• ไตเสื่อมรุนแรง: ลดขนาดและความถี่","full_counseling":"• กินพร้อมหรือหลังอาหาร\\n• ระวังการขับขี่และใช้เครื่องจักร\\n• ห้ามกินเกินขนาดที่แพทย์สั่ง","drug_name":"Tramadol HCl","icode":"1470024","counseling_th":"• กินพร้อมหรือหลังอาหาร\\n• ระวังการขับขี่และใช้เครื่องจักร\\n• ห้ามกินเกินขนาดที่แพทย์สั่ง","when_to_er":"• ชัก (โดยเฉพาะกินเกินขนาด)\\n• หายใจช้า หยุดหายใจ\\n• หมดสติ\\n• หัวใจเต้นผิดจังหวะ","food_interaction":"• แอลกอฮอล์เพิ่มฤทธิ์กดระบบหายใจ\\n• หลีกเลี่ยงยานอนหลับและยากดประสาทอื่น","updatedAt":"2026-05-30T15:18:09.169Z","warning":"• ชัก (โดยเฉพาะกินเกินขนาด)\\n• หายใจช้า หยุดหายใจ\\n• หมดสติ\\n• หัวใจเต้นผิดจังหวะ","side_effect":"• ง่วงนอน เวียนหัว\\n• คลื่นไส้ อาเจียน ท้องผูก\\n• เหงื่อออก\\n• ติดยาได้ถ้าใช้นาน"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1490006', '1490006', '{"storage":"≤ 30°C · ป้องกันความชื้น","drug_name":"Amlodipine","full_counseling":"• บวมข้อเท้า เท้า = ADR พบบ่อย ไม่อันตราย แจ้งแพทย์ถ้ารำคาญมาก\\n• เหงือกบวม (Gingival hyperplasia) — แปรงฟันสม่ำเสมอ\\n• ห้ามหยุดยาเองโดยไม่ปรึกษา","special_pop":"• Pregnancy Cat C\\n• โรคตับ: ลดขนาด","short_label":"บวมข้อเท้า=ผลข้างเคียงปกติ","when_to_er":"• เจ็บหน้าอกรุนแรง (unstable angina)\\n• บวมทั่วร่างกาย หายใจลำบาก (heart failure)\\n• ความดันต่ำมากเป็นลม","counseling_th":"• บวมข้อเท้า เท้า = ADR พบบ่อย ไม่อันตราย แจ้งแพทย์ถ้ารำคาญมาก\\n• เหงือกบวม (Gingival hyperplasia) — แปรงฟันสม่ำเสมอ\\n• ห้ามหยุดยาเองโดยไม่ปรึกษา","icode":"1490006","updatedAt":"2026-06-01T15:54:37.249Z","food_interaction":"• น้ำเกรปฟรุต: ↑ amlodipine level — หลีกเลี่ยง"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1490008_22', '1490008', '{"icode":"1490008","counseling_th":"• กินตอนท้องว่าง ก่อนอาหาร 1 ชั่วโมง หรือหลังอาหาร 2 ชั่วโมง\\n• ห้ามหยุดยาเองเด็ดขาด (ดื้อยา)\\n• กิน Vitamin B6 (Pyridoxine) ร่วมเสมอ","when_to_er":"• ตัวเหลือง ตาเหลือง ปวดท้องมาก อ่อนเพลียมาก\\n• ชาหรืออ่อนแรงรุนแรง\\n• ชักหรือเปลี่ยนแปลงพฤติกรรมกะทันหัน","special_pop":"• ตั้งครรภ์: ใช้ได้ร่วมกับ B6\\n• ผู้ป่วยตับ: ติดตาม LFT อย่างใกล้ชิด","full_counseling":"• กินตอนท้องว่าง ก่อนอาหาร 1 ชั่วโมง หรือหลังอาหาร 2 ชั่วโมง\\n• ห้ามหยุดยาเองเด็ดขาด (ดื้อยา)\\n• กิน Vitamin B6 (Pyridoxine) ร่วมเสมอ","drug_name":"Isoniazid","side_effect":"• ปลายมือปลายเท้าชา (Peripheral neuropathy)\\n• ตับอักเสบ ตัวเหลือง\\n• วิงเวียน ปวดหัว\\n• ผื่นแพ้","food_interaction":"• หลีกเลี่ยงแอลกอฮอล์ เพิ่มตับอักเสบ\\n• ปลาทูน่า ปลาหมักดอง อาจทำให้เกิด histamine reaction","updatedAt":"2026-05-30T15:18:09.169Z","warning":"• ตัวเหลือง ตาเหลือง ปวดท้องมาก อ่อนเพลียมาก\\n• ชาหรืออ่อนแรงรุนแรง\\n• ชักหรือเปลี่ยนแปลงพฤติกรรมกะทันหัน"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1500005_23', '1500005', '{"drug_name":"Rifampicin","full_counseling":"• กินตอนท้องว่าง ก่อนอาหาร 30-60 นาที\\n• ปัสสาวะ น้ำตา เหงื่อสีส้มแดง เป็นเรื่องปกติ\\n• ห้ามหยุดยาเองเด็ดขาด\\n• แจ้งทุกท่านที่จะสั่งยาเพิ่ม เพราะลดฤทธิ์ยาได้มาก","special_pop":"• ตั้งครรภ์: หลีกเลี่ยงไตรมาส 1\\n• ผู้ป่วยตับ: ติดตาม LFT ทุก 2 สัปดาห์","when_to_er":"• ตัวเหลือง ตาเหลือง ปวดท้องมาก อ่อนเพลียมาก\\n• ผื่นรุนแรงทั่วตัว\\n• ไข้สูงร่วมกับอาการแพ้","counseling_th":"• กินตอนท้องว่าง ก่อนอาหาร 30-60 นาที\\n• ปัสสาวะ น้ำตา เหงื่อสีส้มแดง เป็นเรื่องปกติ\\n• ห้ามหยุดยาเองเด็ดขาด\\n• แจ้งทุกท่านที่จะสั่งยาเพิ่ม เพราะลดฤทธิ์ยาได้มาก","icode":"1500005","food_interaction":"• กินก่อนอาหาร เพราะอาหารลดการดูดซึม\\n• ลดฤทธิ์ยาคุมกำเนิด Warfarin ยาเบาหวาน และยาอื่นอีกมาก","warning":"• ตัวเหลือง ตาเหลือง ปวดท้องมาก อ่อนเพลียมาก\\n• ผื่นรุนแรงทั่วตัว\\n• ไข้สูงร่วมกับอาการแพ้","updatedAt":"2026-05-30T15:18:09.169Z","side_effect":"• ตับอักเสบ ตัวเหลือง (สำคัญ)\\n• ผื่นแพ้ ลมพิษ\\n• คลื่นไส้ ปวดท้อง\\n• เม็ดเลือดแดงแตก ซีด"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1530002', '1530002', '{"food_interaction":"• ห้ามน้ำเกรปฟรุต\\n• ลดอาหารไขมันสัตว์","updatedAt":"2026-06-01T15:54:37.249Z","storage":"≤ 30°C · ป้องกันความชื้น","drug_name":"hydralazine","special_pop":"• Pregnancy Cat X — ห้ามใช้\\n• โรคตับ: CONTRAINDICATED","full_counseling":"• กินตอนเย็นหรือก่อนนอน (ร่างกายสังเคราะห์ cholesterol มากช่วงกลางคืน)\\n• ห้ามดื่มน้ำเกรปฟรุต (↑ level มาก)\\n• ห้ามใช้ร่วม Amiodarone เกิน 20 mg/day\\n• ตรวจ LFT + CK ตามนัด","when_to_er":"• ปวดกล้ามเนื้อรุนแรง อ่อนแรง ปัสสาวะสีน้ำตาลแดง (rhabdomyolysis)\\n• ตัวเหลือง (hepatotoxicity)","short_label":"กินตอนเย็น/กลางคืน · ห้ามน้ำเกรปฟรุต","counseling_th":"• กินตอนเย็นหรือก่อนนอน (ร่างกายสังเคราะห์ cholesterol มากช่วงกลางคืน)\\n• ห้ามดื่มน้ำเกรปฟรุต (↑ level มาก)\\n• ห้ามใช้ร่วม Amiodarone เกิน 20 mg/day\\n• ตรวจ LFT + CK ตามนัด","icode":"1530002"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1530007_32', '1530007', '{"when_to_er":"• ตะคริวรุนแรง หัวใจเต้นผิดจังหวะ\\n • ปัสสาวะน้อยมาก\\n • ความดันต่ำมาก","counseling_th":"• กินตอนเช้า ไม่ควรกินเย็น\\n • ดื่มน้ำสม่ำเสมอ\\n • ห้ามหยุดยาเอง","icode":"1530007","drug_name":"Hydrochlorothiazide","special_pop":"• เบาหวาน: อาจทำให้น้ำตาลสูง\\n • eGFR<10: ไม่แนะนำ","full_counseling":"• กินตอนเช้า ไม่ควรกินเย็น\\n • ดื่มน้ำสม่ำเสมอ\\n • ห้ามหยุดยาเอง","side_effect":"• ปัสสาวะบ่อย\\n • K+ ต่ำ ตะคริว\\n • Na+ ต่ำ ปวดหัว\\n • น้ำตาลสูง (ถ้าเป็นเบาหวาน)","food_interaction":"• กินอาหาร K+ (กล้วย ส้ม) ถ้าไม่มีข้อห้าม\\n • ลดเกลือ","updatedAt":"2026-05-30T15:18:09.169Z","warning":"• ตะคริวรุนแรง หัวใจเต้นผิดจังหวะ\\n • ปัสสาวะน้อยมาก\\n • ความดันต่ำมาก"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1530011', '1530011', '{"food_interaction":"• ลดอาหารมันสัตว์ / อาหารทอด\\n• ลดแอลกอฮอล์","updatedAt":"2026-06-01T15:54:37.249Z","icode":"1530011","counseling_th":"• กินก่อนอาหาร 30 นาที (เช้า + เย็น)\\n• ห้ามใช้ร่วมกับ Simvastatin/Atorvastatin (rhabdomyolysis)\\n• ตรวจ LFT + CK ตามนัด","when_to_er":"• ปวดกล้ามเนื้อรุนแรง กล้ามเนื้ออ่อนแรง ปัสสาวะสีน้ำตาลแดง (rhabdomyolysis)\\n• ตัวเหลือง (hepatotoxicity)","short_label":"ห้ามใช้ร่วม Statin · กินก่อนอาหาร 30 นาที","storage":"≤ 30°C","special_pop":"• Pregnancy Cat C\\n• โรคไต/ตับ: ปรับขนาด","full_counseling":"• กินก่อนอาหาร 30 นาที (เช้า + เย็น)\\n• ห้ามใช้ร่วมกับ Simvastatin/Atorvastatin (rhabdomyolysis)\\n• ตรวจ LFT + CK ตามนัด","drug_name":"Gemfibrozil"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1530012_13', '1530012', '{"icode":"1530012","counseling_th":"• กินพร้อมอาหารทุกมื้อ ไม่ขาดยา\\n• ห้ามหยุดยาเองเด็ดขาด (ดื้อยา)\\n• เก็บในตู้เย็น หรืออุณหภูมิห้องไม่เกิน 25°C","when_to_er":"• ตัวเหลือง ตาเหลือง ปวดท้องมาก\\n• หัวใจเต้นผิดจังหวะ ใจสั่น\\n• ผื่นแพ้รุนแรง\\n• ท้องเสียรุนแรงไม่หยุด","special_pop":"• เด็ก: คำนวณขนาดตามน้ำหนัก\\n• DDI สูงมาก ต้องตรวจสอบยาทุกตัวก่อนใช้ร่วม","full_counseling":"• กินพร้อมอาหารทุกมื้อ ไม่ขาดยา\\n• ห้ามหยุดยาเองเด็ดขาด (ดื้อยา)\\n• เก็บในตู้เย็น หรืออุณหภูมิห้องไม่เกิน 25°C","drug_name":"Lopinavir/Ritonavir","side_effect":"• ท้องเสีย คลื่นไส้ ปวดท้อง\\n• ตับอักเสบ ตัวเหลือง\\n• ระดับไขมันในเลือดสูง\\n• หัวใจเต้นผิดจังหวะ (QT prolongation)","food_interaction":"• น้ำส้มโอเพิ่มระดับยาในเลือดอันตราย\\n• หลีกเลี่ยง Simvastatin, Lovastatin ห้ามใช้ร่วม","updatedAt":"2026-05-30T15:18:09.169Z","warning":"• ตัวเหลือง ตาเหลือง ปวดท้องมาก\\n• หัวใจเต้นผิดจังหวะ ใจสั่น\\n• ผื่นแพ้รุนแรง\\n• ท้องเสียรุนแรงไม่หยุด"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1540001_19', '1540001', '{"food_interaction":"• ลดอาหารเค็ม\\n• หลีกเลี่ยงอาหาร K+ สูง ถ้าใช้ยาขับน้ำรักษา K+","updatedAt":"2026-05-30T15:18:09.169Z","warning":"• บวมหน้า ลิ้น หรือคอ หายใจลำบาก\\n• ความดันต่ำมาก เป็นลมหมดสติ\\n• ปัสสาวะน้อย ไตวายเฉียบพลัน","side_effect":"• ไอแห้ง (พบบ่อย)\\n• รสโลหะในปาก\\n• ความดันต่ำ เวียนหัว\\n• K+ สูง บวมหน้า","special_pop":"• ตั้งครรภ์ไตรมาส 2-3: ห้ามใช้\\n• ไตเสื่อม: ปรับขนาด","full_counseling":"• กินก่อนอาหาร 1 ชั่วโมง หรือหลังอาหาร 2 ชั่วโมง\\n• ลุกนั่งช้าๆ\\n• ห้ามหยุดยาเองโดยไม่ปรึกษาแพทย์","drug_name":"Captopril","icode":"1540001","counseling_th":"• กินก่อนอาหาร 1 ชั่วโมง หรือหลังอาหาร 2 ชั่วโมง\\n• ลุกนั่งช้าๆ\\n• ห้ามหยุดยาเองโดยไม่ปรึกษาแพทย์","when_to_er":"• บวมหน้า ลิ้น หรือคอ หายใจลำบาก\\n• ความดันต่ำมาก เป็นลมหมดสติ\\n• ปัสสาวะน้อย ไตวายเฉียบพลัน"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1550001_36', '1550001', '{"side_effect":"• น้ำหนักขึ้น บวม\\n • ความเสี่ยงกระดูกหัก (ผู้หญิง)\\n • ตับอักเสบ (หายาก)","updatedAt":"2026-05-30T15:18:09.169Z","warning":"• บวมมาก น้ำหนักขึ้นรวดเร็ว (Heart failure)\\n • ตัวเหลือง ปวดท้องมาก\\n • ปัสสาวะเป็นเลือดหรือปวดปัสสาวะ","when_to_er":"• บวมมาก น้ำหนักขึ้นรวดเร็ว (Heart failure)\\n • ตัวเหลือง ปวดท้องมาก\\n • ปัสสาวะเป็นเลือดหรือปวดปัสสาวะ","counseling_th":"• กินวันละครั้ง พร้อมหรือไม่พร้อมอาหาร\\n • น้ำหนักอาจขึ้นและบวม\\n • ห้ามหยุดยาเอง","icode":"1550001","drug_name":"Pioglitazone","special_pop":"• หัวใจล้มเหลว: ห้ามใช้\\n • มะเร็งกระเพาะปัสสาวะ: ระวัง","full_counseling":"• กินวันละครั้ง พร้อมหรือไม่พร้อมอาหาร\\n • น้ำหนักอาจขึ้นและบวม\\n • ห้ามหยุดยาเอง"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1550004_38', '1550004', '{"food_interaction":"• น้ำส้มโอ (กรณีบางยา)","warning":"• มีความคิดทำร้ายตัวเอง\\n • อาการผิดปกติ เช่น กระสับกระส่ายมาก ชัก\\n • ไข้สูง กล้ามเนื้อเกร็ง (Serotonin syndrome)","updatedAt":"2026-05-30T15:18:09.169Z","side_effect":"• คลื่นไส้ ท้องเสีย ช่วงแรก\\n • นอนไม่หลับหรือง่วงนอน\\n • ความต้องการทางเพศลดลง","drug_name":"Sertraline","full_counseling":"• กินพร้อมอาหาร\\n • ผลการรักษาอาจใช้เวลา 2-4 สัปดาห์จึงเห็นผล\\n • ห้ามหยุดยาเองเด็ดขาด","special_pop":"• ผู้สูงอายุ: เสี่ยงหกล้ม โซเดียมต่ำ\\n • ตั้งครรภ์ไตรมาส 3: ระวัง neonatal withdrawal","when_to_er":"• มีความคิดทำร้ายตัวเอง\\n • อาการผิดปกติ เช่น กระสับกระส่ายมาก ชัก\\n • ไข้สูง กล้ามเนื้อเกร็ง (Serotonin syndrome)","counseling_th":"• กินพร้อมอาหาร\\n • ผลการรักษาอาจใช้เวลา 2-4 สัปดาห์จึงเห็นผล\\n • ห้ามหยุดยาเองเด็ดขาด","icode":"1550004"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1550006', '1550006', '{"food_interaction":"• น้ำเกรปฟรุต: อาจลด clopidogrel activation\\n• ห้ามซื้อ NSAIDs/Aspirin เพิ่มเอง (↑ bleeding risk)","updatedAt":"2026-06-01T15:54:37.249Z","when_to_er":"• เลือดออกผิดปกติ: อุจจาระสีดำ · ปัสสาวะสีแดง · เลือดออกไม่หยุด\\n• เจ็บหน้าอกรุนแรงทันทีทันใด (stent thrombosis)\\n• ปวดหัวรุนแรงทันทีทันใด","short_label":"ห้ามหยุดยาเอง · แจ้งก่อนผ่าตัดหรือถอนฟัน","counseling_th":"• ห้ามหยุดยาเองโดยไม่ปรึกษาแพทย์ (stent thrombosis ใน 24-48 ชม.)\\n• แจ้งก่อนผ่าตัดหรือถอนฟัน (ต้องหยุดยา 5-7 วัน)\\n• ใช้ Pantoprazole (ไม่ใช่ Omeprazole) ถ้าต้องการยาป้องกันกระเพาะ\\n• ห้ามซื้อ NSAIDs เอง","icode":"1550006","drug_name":"Clopidogrel bisulfate","special_pop":"• Pregnancy Cat B\\n• CYP2C19 poor metabolizers: อาจไม่ตอบสนองต่อยา","full_counseling":"• ห้ามหยุดยาเองโดยไม่ปรึกษาแพทย์ (stent thrombosis ใน 24-48 ชม.)\\n• แจ้งก่อนผ่าตัดหรือถอนฟัน (ต้องหยุดยา 5-7 วัน)\\n• ใช้ Pantoprazole (ไม่ใช่ Omeprazole) ถ้าต้องการยาป้องกันกระเพาะ\\n• ห้ามซื้อ NSAIDs เอง","storage":"≤ 30°C · ป้องกันความชื้น"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1550011_3', '1550011', '{"food_interaction":"• แอลกอฮอล์ทำให้น้ำตาลต่ำรุนแรง\\n• อาหารคาร์โบไฮเดรตต้องสม่ำเสมอ","updatedAt":"2026-05-30T15:18:09.169Z","warning":"• น้ำตาลต่ำมาก หมดสติหรือชัก\\n• น้ำตาลสูงมาก (กระหายน้ำมาก ปัสสาวะบ่อย คลื่นไส้)\\n• หายใจลำบาก","side_effect":"• น้ำตาลในเลือดต่ำ (ใจสั่น เหงื่อออก มือสั่น หิวมาก)\\n• บวมบริเวณที่ฉีดช่วงแรก\\n• ผิวหนังหนาหรือแข็งถ้าฉีดซ้ำที่เดิม","special_pop":"• ผู้สูงอายุ: เสี่ยงน้ำตาลต่ำสูง เป้าหมาย FBS 100-150 mg/dL\\n• ตั้งครรภ์: ปรึกษาแพทย์เรื่องขนาดยา","full_counseling":"• ฉีดใต้ผิวหนัง เวียนตำแหน่งฉีด\\n• ฉีดก่อนอาหาร 30 นาที และกินอาหารทันทีหลังฉีด\\n• เก็บยาที่ใช้อยู่ไว้ที่อุณหภูมิห้องได้ไม่เกิน 28 วัน\\n• วัดน้ำตาลตามนัด","drug_name":"Insulin 70/30","icode":"1550011","counseling_th":"• ฉีดใต้ผิวหนัง เวียนตำแหน่งฉีด\\n• ฉีดก่อนอาหาร 30 นาที และกินอาหารทันทีหลังฉีด\\n• เก็บยาที่ใช้อยู่ไว้ที่อุณหภูมิห้องได้ไม่เกิน 28 วัน\\n• วัดน้ำตาลตามนัด","when_to_er":"• น้ำตาลต่ำมาก หมดสติหรือชัก\\n• น้ำตาลสูงมาก (กระหายน้ำมาก ปัสสาวะบ่อย คลื่นไส้)\\n• หายใจลำบาก"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1550014', '1550014', '{"updatedAt":"2026-06-01T15:54:37.249Z","drug_name":"Cytotec (Misoprostol)","special_pop":"• ห้ามใช้ใน prior C/S (uterine rupture risk)\\n• Pregnancy context เท่านั้น","full_counseling":"• ยานี้ใช้เฉพาะตามที่แพทย์สั่ง ห้ามซื้อใช้เอง\\n• ห้ามใช้ร่วม Oxytocin ภายใน 6-8 ชม. (uterine rupture)\\n• อาจมีอาการปวดท้อง ท้องเสีย หนาวสั่น เป็นปกติ","storage":"≤ 25°C · ป้องกันแสง + ความชื้น","counseling_th":"• ยานี้ใช้เฉพาะตามที่แพทย์สั่ง ห้ามซื้อใช้เอง\\n• ห้ามใช้ร่วม Oxytocin ภายใน 6-8 ชม. (uterine rupture)\\n• อาจมีอาการปวดท้อง ท้องเสีย หนาวสั่น เป็นปกติ","short_label":"ห้ามใช้เองโดยไม่ปรึกษาแพทย์","when_to_er":"• ปวดท้องรุนแรงต่อเนื่อง ไม่หาย (uterine hyperstimulation/rupture)\\n• เลือดออกมากผิดปกติ\\n• ลูกดิ้นน้อยหรือไม่ดิ้น","icode":"1550014"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1560019', '1560019', '{"food_interaction":"• กินอาหารที่มีเกลือสม่ำเสมอ — ห้ามลดเกลือกะทันหัน\\n• ห้ามซื้อ NSAIDs เอง\\n• ระวังกาเฟอีนมาก (เพิ่ม Li excretion)","updatedAt":"2026-06-01T15:54:37.249Z","special_pop":"• Pregnancy Cat D — Ebstein\'s anomaly\\n• โรคไต: ลดขนาด + monitor level บ่อยขึ้น\\n• ผู้สูงอายุ: เสี่ยง toxicity สูง","full_counseling":"• กินอาหารเค็มสม่ำเสมอ ห้ามลดเกลือกะทันหัน (เกลือลด → Li ขึ้น)\\n• ดื่มน้ำ 2-3 ลิตร/วัน ระวังท้องเสีย/อาเจียน (dehydration → Li toxicity)\\n• ห้ามซื้อยาแก้ปวด NSAIDs (ibuprofen, diclofenac) เอง (↑ Li level ฉับพลัน)\\n• ตรวจเลือดวัดระดับยาและไตทุก 3-6 เดือน\\n• เจาะเลือดตอนเช้า ก่อนกินยา (trough level)","drug_name":"Lithium carbonate","storage":"≤ 25°C · ป้องกันความชื้น","icode":"1560019","counseling_th":"• กินอาหารเค็มสม่ำเสมอ ห้ามลดเกลือกะทันหัน (เกลือลด → Li ขึ้น)\\n• ดื่มน้ำ 2-3 ลิตร/วัน ระวังท้องเสีย/อาเจียน (dehydration → Li toxicity)\\n• ห้ามซื้อยาแก้ปวด NSAIDs (ibuprofen, diclofenac) เอง (↑ Li level ฉับพลัน)\\n• ตรวจเลือดวัดระดับยาและไตทุก 3-6 เดือน\\n• เจาะเลือดตอนเช้า ก่อนกินยา (trough level)","when_to_er":"• มือสั่นรุนแรง เดินโซเซ พูดไม่ชัด สับสน (Li toxicity)\\n• คลื่นไส้อาเจียนรุนแรง ท้องเสียมาก (ขาดน้ำ → Li ขึ้น)\\n• ชัก ไม่รู้สึกตัว (severe toxicity)","short_label":"ตรวจ Li level ทุก 3-6 เดือน · ดื่มน้ำ 2-3 ลิตร/วัน · ห้ามซื้อยาแก้ปวดเอง"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1560019_6', '1560019', '{"drug_name":"Lithium carbonate","full_counseling":"• ดื่มน้ำสะอาด 2-3 ลิตร/วัน\\n• กินอาหารเค็มสม่ำเสมอ ไม่ลดเค็มกะทันหัน\\n• ตรวจระดับยาในเลือดตามนัด\\n• ห้ามหยุดยาเองเด็ดขาด","special_pop":"• ผู้สูงอายุ: เสี่ยง toxicity สูง ระวังน้ำหนักยา\\n• ตั้งครรภ์ไตรมาส 1: หลีกเลี่ยง (ผิดปกติหัวใจทารก)","when_to_er":"• สั่นรุนแรง เดินเซ พูดไม่ชัด\\n• คลื่นไส้อาเจียนรุนแรง สับสน\\n• ไข้สูง ปัสสาวะน้อยลง (ระดับยาเป็นพิษ)\\n• ชัก หมดสติ","counseling_th":"• ดื่มน้ำสะอาด 2-3 ลิตร/วัน\\n• กินอาหารเค็มสม่ำเสมอ ไม่ลดเค็มกะทันหัน\\n• ตรวจระดับยาในเลือดตามนัด\\n• ห้ามหยุดยาเองเด็ดขาด","icode":"1560019","food_interaction":"• หลีกเลี่ยงอาหารเค็มมากหรือน้อยเกินไป\\n• ชา กาแฟเพิ่มการขับ Li ออก ทำให้ระดับต่ำ","warning":"• สั่นรุนแรง เดินเซ พูดไม่ชัด\\n• คลื่นไส้อาเจียนรุนแรง สับสน\\n• ไข้สูง ปัสสาวะน้อยลง (ระดับยาเป็นพิษ)\\n• ชัก หมดสติ","updatedAt":"2026-05-30T15:18:09.169Z","side_effect":"• สั่น คลื่นไส้ ท้องเสียช่วงเริ่มต้น\\n• ปัสสาวะบ่อย กระหายน้ำ\\n• ง่วงนอน อ่อนเพลีย\\n• น้ำหนักเพิ่ม"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1560021_39', '1560021', '{"icode":"1560021","when_to_er":"• หัวใจเต้นผิดจังหวะ\\n • Priapism (ชายหน้าอก) — ต้องมา รพ. ทันที\\n • ความดันต่ำมาก","counseling_th":"• กินพร้อมอาหาร เพื่อลดอาการคลื่นไส้\\n • กินก่อนนอนถ้าใช้นอนหลับ\\n • ลุกนั่งช้าๆ","special_pop":"• ผู้สูงอายุ: เสี่ยงหกล้ม\\n • โรคหัวใจ: ระวัง QT","full_counseling":"• กินพร้อมอาหาร เพื่อลดอาการคลื่นไส้\\n • กินก่อนนอนถ้าใช้นอนหลับ\\n • ลุกนั่งช้าๆ","drug_name":"Trazodone HCl","side_effect":"• ง่วงนอน เวียนหัว\\n • ปากแห้ง\\n • ความดันต่ำเมื่อลุก","warning":"• หัวใจเต้นผิดจังหวะ\\n • Priapism (ชายหน้าอก) — ต้องมา รพ. ทันที\\n • ความดันต่ำมาก","updatedAt":"2026-05-30T15:18:09.169Z"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1560022', '1560022', '{"food_interaction":"• กินพร้อมอาหาร","updatedAt":"2026-06-01T15:54:37.249Z","storage":"≤ 25°C","drug_name":"Depakine","special_pop":"• Pregnancy Cat D — Neural tube defects สูงมาก; ห้ามใช้ถ้าเป็นไปได้\\n• Meropenem/Imipenem: ↓ level 60-100% → breakthrough seizure\\n• Phenobarbital: ↑ PB level","full_counseling":"• ห้ามหยุดยากันชักเองเด็ดขาด\\n• กินพร้อมอาหาร (ลด GI ADR) หรือ sustained-release form\\n• ตรวจ LFT + CBC + drug level ตามนัด\\n• แจ้งแพทย์ทันทีถ้าแพลนตั้งครรภ์\\n• หมอ antibiotic (Meropenem/Carbapenem) จะทำให้ level ลดลงมาก — monitor level","when_to_er":"• ชักมากขึ้นหลังได้ Antibiotic กลุ่ม Carbapenem\\n• คลื่นไส้อาเจียนรุนแรง ตัวเหลือง (hepatotoxicity)\\n• สับสน ง่วงซึมผิดปกติ (hyperammonemia)","short_label":"ห้ามหยุดยาเอง · ตรวจตับ + level · ห้ามตั้งครรภ์","counseling_th":"• ห้ามหยุดยากันชักเองเด็ดขาด\\n• กินพร้อมอาหาร (ลด GI ADR) หรือ sustained-release form\\n• ตรวจ LFT + CBC + drug level ตามนัด\\n• แจ้งแพทย์ทันทีถ้าแพลนตั้งครรภ์\\n• หมอ antibiotic (Meropenem/Carbapenem) จะทำให้ level ลดลงมาก — monitor level","icode":"1560022"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1560025', '1560025', '{"drug_name":"[ 100 mg ] Clozapine","special_pop":"• Pregnancy Cat B\\n• ห้ามร่วม Carbamazepine (agranulocytosis)\\n• Smoking cessation: ระดับยาขึ้น 50% → ระวังชัก","full_counseling":"• ต้องตรวจเลือด (WBC/ANC) ทุกสัปดาห์ × 18 สัปดาห์ ห้ามข้ามการตรวจ\\n• ถ้ามีไข้ เจ็บคอ อ่อนเพลียผิดปกติ — หยุดยาและมาพบแพทย์ด่วนทันที\\n• ห้ามหยุดบุหรี่กะทันหัน (ระดับยาขึ้นสูงทำให้ชักได้)\\n• น้ำลายมาก (Sialorrhea) = ADR พบบ่อย","storage":"≤ 25°C · ป้องกันความชื้น","short_label":"ตรวจ WBC ทุกสัปดาห์ · ไข้เจ็บคอ = หยุดยา+มาพบแพทย์ด่วน","when_to_er":"• ไข้สูง เจ็บคอ อ่อนเพลียมาก (agranulocytosis — อันตราย)\\n• เจ็บหน้าอก ใจสั่น หายใจลำบาก (myocarditis — 4 สัปดาห์แรก)\\n• ชัก","counseling_th":"• ต้องตรวจเลือด (WBC/ANC) ทุกสัปดาห์ × 18 สัปดาห์ ห้ามข้ามการตรวจ\\n• ถ้ามีไข้ เจ็บคอ อ่อนเพลียผิดปกติ — หยุดยาและมาพบแพทย์ด่วนทันที\\n• ห้ามหยุดบุหรี่กะทันหัน (ระดับยาขึ้นสูงทำให้ชักได้)\\n• น้ำลายมาก (Sialorrhea) = ADR พบบ่อย","icode":"1560025","updatedAt":"2026-06-01T15:54:37.249Z","food_interaction":"• ห้ามดื่มแอลกอฮอล์\\n• กาแฟมาก: อาจลด clozapine level เล็กน้อย"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1560025_7', '1560025', '{"icode":"1560025","when_to_er":"• ไข้สูงกะทันหัน เจ็บคอ (อาจเป็น agranulocytosis)\\n• กล้ามเนื้อเกร็งแข็งรุนแรง\\n• หัวใจเต้นผิดจังหวะ ใจสั่น\\n• ชักหรือหมดสติ","counseling_th":"• ตรวจเลือด CBC ทุกสัปดาห์ (4 สัปดาห์แรก) ห้ามขาด\\n• ห้ามหยุดยาเองเด็ดขาด\\n• ลุกนั่งช้าๆ เพราะความดันอาจต่ำเมื่อเปลี่ยนท่า","special_pop":"• ผู้สูงอายุ: เพิ่มเสี่ยงหัวใจและความดันต่ำ\\n• ห้ามใช้ร่วมกับยากดภูมิอื่น","full_counseling":"• ตรวจเลือด CBC ทุกสัปดาห์ (4 สัปดาห์แรก) ห้ามขาด\\n• ห้ามหยุดยาเองเด็ดขาด\\n• ลุกนั่งช้าๆ เพราะความดันอาจต่ำเมื่อเปลี่ยนท่า","drug_name":"Clozapine","side_effect":"• ง่วงมาก น้ำลายมาก โดยเฉพาะตอนกลางคืน\\n• น้ำหนักขึ้น ระดับน้ำตาลสูง\\n• ท้องผูก ปัสสาวะลำบาก\\n• ความดันต่ำเมื่อลุกยืน","food_interaction":"• แอลกอฮอล์เพิ่มฤทธิ์ง่วงมาก\\n• หลีกเลี่ยงเครื่องดื่มที่มีคาเฟอีนมาก","warning":"• ไข้สูงกะทันหัน เจ็บคอ (อาจเป็น agranulocytosis)\\n• กล้ามเนื้อเกร็งแข็งรุนแรง\\n• หัวใจเต้นผิดจังหวะ ใจสั่น\\n• ชักหรือหมดสติ","updatedAt":"2026-05-30T15:18:09.169Z"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1580005', '1580005', '{"drug_name":"Losartan Potassium","special_pop":"• Pregnancy Cat D — ห้ามใช้ทุก trimester\\n• ACEi + ARB = ห้ามใช้ร่วมกัน","full_counseling":"• ยาลดความดันโลหิต ไม่ค่อยมีไอ (ต่างจาก ACEi)\\n• ตรวจ K⁺ + ไต หลังเริ่มยา 1-2 สัปดาห์\\n• ห้ามใช้ขณะตั้งครรภ์ (Pregnancy Cat D)\\n• ลุกขึ้นช้าๆ (ความดันต่ำ)","storage":"≤ 30°C","when_to_er":"• บวมหน้า ลิ้น คอ (Angioedema — พบน้อยกว่า ACEi แต่เกิดได้)\\n• ความดันต่ำมาก เป็นลม","short_label":"ห้ามใช้ขณะตั้งครรภ์ · ตรวจ K⁺ + ไต","counseling_th":"• ยาลดความดันโลหิต ไม่ค่อยมีไอ (ต่างจาก ACEi)\\n• ตรวจ K⁺ + ไต หลังเริ่มยา 1-2 สัปดาห์\\n• ห้ามใช้ขณะตั้งครรภ์ (Pregnancy Cat D)\\n• ลุกขึ้นช้าๆ (ความดันต่ำ)","icode":"1580005","food_interaction":"• ห้ามซื้อ NSAIDs เอง\\n• ระวังอาหาร K สูงมาก","updatedAt":"2026-06-01T15:54:37.249Z"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1580005_20', '1580005', '{"food_interaction":"• หลีกเลี่ยงอาหาร K+ สูง ถ้าใช้ K-sparing diuretic ร่วม","warning":"• บวมหน้า ลิ้น คอ หายใจลำบาก (หายากกว่า ACEI)\\n• ความดันต่ำมาก เป็นลม\\n• ปัสสาวะน้อย ไตวาย","updatedAt":"2026-05-30T15:18:09.169Z","side_effect":"• เวียนหัว ความดันต่ำ\\n• K+ ในเลือดสูง\\n• ไตทำงานลดลงช่วงแรก","drug_name":"Losartan","full_counseling":"• กินยาเวลาเดิม ไม่ต้องสัมพันธ์กับอาหาร\\n• ลุกนั่งช้าๆ\\n• ห้ามหยุดยาเองโดยไม่ปรึกษาแพทย์","special_pop":"• ตั้งครรภ์ไตรมาส 2-3: ห้ามใช้\\n• ไตเสื่อม: ติดตาม SCr และ K+","when_to_er":"• บวมหน้า ลิ้น คอ หายใจลำบาก (หายากกว่า ACEI)\\n• ความดันต่ำมาก เป็นลม\\n• ปัสสาวะน้อย ไตวาย","counseling_th":"• กินยาเวลาเดิม ไม่ต้องสัมพันธ์กับอาหาร\\n• ลุกนั่งช้าๆ\\n• ห้ามหยุดยาเองโดยไม่ปรึกษาแพทย์","icode":"1580005"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1590006', '1590006', '{"updatedAt":"2026-06-01T15:54:37.249Z","counseling_th":"• ยานี้ละลายลิ่มเลือดในหลอดเลือด ทำให้เลือดหยุดช้ากว่าปกติ 24-48 ชม.\\n• ห้ามเจาะเลือด ทำหัตถการ หรือบาดเจ็บที่ไม่จำเป็นในช่วงนี้\\n• แจ้งทุกคนที่รักษาว่าเพิ่งได้รับยานี้","short_label":"เลือดออกง่าย 24-48 ชม. · ห้ามเจาะ/ทำหัตถการที่ไม่จำเป็น","when_to_er":"• เลือดออกผิดปกติทุกตำแหน่ง\\n• ปวดหัวรุนแรงทันทีทันใด (intracranial hemorrhage)\\n• อ่อนแรงครึ่งซีก · พูดไม่ชัด\\n• ความดันโลหิตต่ำมาก","icode":"1590006","special_pop":"• เคยได้ Streptokinase < 1 ปี: ห้ามใช้ซ้ำ\\n• Pregnancy Cat C","full_counseling":"• ยานี้ละลายลิ่มเลือดในหลอดเลือด ทำให้เลือดหยุดช้ากว่าปกติ 24-48 ชม.\\n• ห้ามเจาะเลือด ทำหัตถการ หรือบาดเจ็บที่ไม่จำเป็นในช่วงนี้\\n• แจ้งทุกคนที่รักษาว่าเพิ่งได้รับยานี้","drug_name":"streptokinase (HAD)","storage":"2-8°C ก่อนเปิด · หลังละลาย 24 ชม. ที่ 2-8°C"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1590024_9', '1590024', '{"special_pop":"• ตั้งครรภ์: ห้ามใช้ (ทารกพิการ Neural tube defect)\\n• เด็กอายุ < 2 ปี: เสี่ยง hepatotoxicity สูง","full_counseling":"• กินยาตามขนาดและเวลาที่กำหนด ห้ามหยุดเอง\\n• กินพร้อมอาหารถ้ามีอาการคลื่นไส้\\n• ตรวจระดับยาและตับตามนัด","drug_name":"Sodium valproate","icode":"1590024","when_to_er":"• ชักถี่ขึ้นหรือรุนแรงขึ้น\\n• ตัวเหลือง ตาเหลือง ปวดท้องมาก (ตับอักเสบ)\\n• ฟกช้ำง่าย เลือดออกผิดปกติ\\n• ไข้สูงร่วมกับผื่น","counseling_th":"• กินยาตามขนาดและเวลาที่กำหนด ห้ามหยุดเอง\\n• กินพร้อมอาหารถ้ามีอาการคลื่นไส้\\n• ตรวจระดับยาและตับตามนัด","food_interaction":"• แอลกอฮอล์เพิ่มฤทธิ์กดสมอง\\n• หลีกเลี่ยงอาหารที่มีผลต่อตับ","warning":"• ชักถี่ขึ้นหรือรุนแรงขึ้น\\n• ตัวเหลือง ตาเหลือง ปวดท้องมาก (ตับอักเสบ)\\n• ฟกช้ำง่าย เลือดออกผิดปกติ\\n• ไข้สูงร่วมกับผื่น","updatedAt":"2026-05-30T15:18:09.169Z","side_effect":"• คลื่นไส้ เบื่ออาหาร ช่วงแรก\\n• ง่วงนอน ผมร่วง\\n• น้ำหนักขึ้น\\n• มือสั่น"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1590032_31', '1590032', '{"food_interaction":"• แอลกอฮอล์เพิ่มฤทธิ์กดสมอง","updatedAt":"2026-05-30T15:18:09.169Z","warning":"• ชักถี่ขึ้นหรือรุนแรงขึ้น\\n • สับสนมาก หรือหมดสติ\\n • หายใจลำบาก","side_effect":"• ง่วงนอนมาก เวียนหัว\\n • เดินเซ ทรงตัวไม่ดี\\n • บวม มือเท้า\\n • ความจำไม่ดี","special_pop":"• ผู้สูงอายุ: ลดขนาด เสี่ยงหกล้ม\\n • ไตเสื่อม: ต้องลดขนาดตาม CrCl","full_counseling":"• กินพร้อมอาหารหรือไม่ก็ได้\\n • ห้ามหยุดยาเองเด็ดขาด (ชักได้)\\n • ระวังการขับขี่ในช่วงแรก","drug_name":"Gabapentin","icode":"1590032","counseling_th":"• กินพร้อมอาหารหรือไม่ก็ได้\\n • ห้ามหยุดยาเองเด็ดขาด (ชักได้)\\n • ระวังการขับขี่ในช่วงแรก","when_to_er":"• ชักถี่ขึ้นหรือรุนแรงขึ้น\\n • สับสนมาก หรือหมดสติ\\n • หายใจลำบาก"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1600001', '1600001', '{"storage":"≤ 30°C · ห้ามแช่เย็น (ตกตะกอน)","special_pop":"• ห้ามใน Asthma / COPD (bronchospasm)\\n• ห้ามใน 2nd/3rd degree AV block","full_counseling":"• ยานี้จะทำให้รู้สึกวูบ ใจสั่น หายใจลำบาก แน่นหน้าอกสักครู่ — เป็นผลปกติ หายเองใน 30 วินาที\\n• ถ้าอาการไม่ดีขึ้นหลัง 1 นาที บอกพยาบาลทันที","drug_name":"Adenosine (HAD)","icode":"1600001","counseling_th":"• ยานี้จะทำให้รู้สึกวูบ ใจสั่น หายใจลำบาก แน่นหน้าอกสักครู่ — เป็นผลปกติ หายเองใน 30 วินาที\\n• ถ้าอาการไม่ดีขึ้นหลัง 1 นาที บอกพยาบาลทันที","when_to_er":"• หัวใจหยุดเต้น · ชีพจรหาย · ไม่รู้สึกตัว","short_label":"ฉีดเร็ว + Flush NSS ทันที · Monitor EKG","updatedAt":"2026-06-01T15:54:37.249Z","food_interaction":"• งด Caffeine (กาแฟ/ชา) ≥ 12-24 ชม. ก่อนใช้ยา (ลดฤทธิ์)"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1600002', '1600002', '{"updatedAt":"2026-06-01T15:54:37.249Z","food_interaction":"• น้ำเกรปฟรุตอาจเพิ่ม level ยา — หลีกเลี่ยง","drug_name":"Amiodarone (HAD) 150mg/3mL","full_counseling":"• ผิวหนังไวต่อแสงแดด — ทาครีมกันแดด SPF ≥ 30 + สวมเสื้อแขนยาวทุกวัน\\n• ตรวจไทรอยด์และตับทุก 3-6 เดือน\\n• ห้ามหยุดยาเองเด็ดขาด (arrhythmia กลับมาได้)\\n• อาจมีผื่นสีเทาน้ำเงินที่ผิวหนังในระยะยาว","special_pop":"• Pregnancy Cat D — ห้ามใช้ขณะตั้งครรภ์ / ให้นมบุตร\\n• โรคตับ: ลดขนาดยา\\n• ผู้ป่วย DM: monitor thyroid (amiodarone ทำให้ไทรอยด์ผิดปกติ)","storage":"≤ 25°C · ป้องกันแสง (เก็บในกล่อง)","short_label":"ห้ามหยุดยาเอง · ตรวจเลือด + ตรวจตับ + ไทรอยด์สม่ำเสมอ","when_to_er":"• ไอ หายใจลำบาก (pulmonary toxicity)\\n• ตัวเหลือง ตาเหลือง ปวดท้องรุนแรง (hepatotoxicity)\\n• ใจสั่นผิดปกติ · เป็นลม","counseling_th":"• ผิวหนังไวต่อแสงแดด — ทาครีมกันแดด SPF ≥ 30 + สวมเสื้อแขนยาวทุกวัน\\n• ตรวจไทรอยด์และตับทุก 3-6 เดือน\\n• ห้ามหยุดยาเองเด็ดขาด (arrhythmia กลับมาได้)\\n• อาจมีผื่นสีเทาน้ำเงินที่ผิวหนังในระยะยาว","icode":"1600002"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1600003', '1600003', '{"icode":"1600003","counseling_th":"• ห้ามหยุดยากันชักเองเด็ดขาด (อาจชักรุนแรง)\\n• กินยาเวลาเดิมสม่ำเสมอ\\n• แจ้งยาทุกชนิดที่ใช้ก่อนรับยาเพิ่ม (DDI มาก)\\n• ดูแลช่องปากสม่ำเสมอ (เหงือกบวม = ADR)\\n• ห้ามดื่มแอลกอฮอล์","when_to_er":"• เดินโซเซ พูดไม่ชัด เห็นภาพซ้อน (ระดับยาสูง)\\n• ชักมากขึ้นหรือชักครั้งแรก\\n• ผื่นแดง ตุ่มพอง (SJS/TEN)\\n• บริเวณ IV ปวดรุนแรง มือบวมม่วง (Purple Glove)","short_label":"ห้ามหยุดยาเอง · แจ้งยาทุกชนิดที่ใช้","storage":"≤ 25°C · หลังเจือจาง NSS ใช้ภายใน 4 ชม. เท่านั้น","special_pop":"• Albumin < 3 g/dL: ต้องตรวจ free phenytoin level\\n• Pregnancy Cat D — ทำให้พิการแต่กำเนิด\\n• โรคไต: เพิ่ม free phenytoin (ปรับขนาด)","full_counseling":"• ห้ามหยุดยากันชักเองเด็ดขาด (อาจชักรุนแรง)\\n• กินยาเวลาเดิมสม่ำเสมอ\\n• แจ้งยาทุกชนิดที่ใช้ก่อนรับยาเพิ่ม (DDI มาก)\\n• ดูแลช่องปากสม่ำเสมอ (เหงือกบวม = ADR)\\n• ห้ามดื่มแอลกอฮอล์","drug_name":"Phenytoin (HAD)","updatedAt":"2026-06-01T15:54:37.249Z","food_interaction":"• ห้ามกินพร้อม Enteral feeding — หยุด feed 1-2 ชม. ก่อน-หลัง (ลด absorption 70%)\\n• ห้ามกินพร้อม antacid — แยก ≥ 2 ชม."}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1600019_1', '1600019', '{"food_interaction":"• ผักใบเขียว (ผักบุ้ง คะน้า บร็อคโคลี่) กินสม่ำเสมอปริมาณเท่าเดิม\\n• น้ำส้มโอ มะม่วงสุก หลีกเลี่ยง\\n• แอลกอฮอล์ หลีกเลี่ยง","updatedAt":"2026-05-30T15:18:09.169Z","warning":"• เลือดออกหยุดไม่ได้, จ้ำเลือดตามตัว\\n• ปวดหัวรุนแรง ,แขนขาอ่อนแรงเฉียบพลัน","drug_name":"Warfarin 5mg","special_pop":"• ผู้สูงอายุ ≥75 ปี: เริ่มขนาดต่ำ เสี่ยงเลือดออกสูง\\n• ตั้งครรภ์: ห้ามใช้ในไตรมาส 1 และ 3","full_counseling":"• หากมีรับยาสถานพยาบาลอื่น โปรดแจ้งทุกครั้ง","when_to_er":"• เลือดออกหยุดไม่ได้, จ้ำเลือดตามตัว\\n• ปวดหัวรุนแรง ,แขนขาอ่อนแรงเฉียบพลัน","counseling_th":"• หากมีรับยาสถานพยาบาลอื่น โปรดแจ้งทุกครั้ง","icode":"1600019"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1600020', '1600020', '{"updatedAt":"2026-06-01T15:54:37.249Z","food_interaction":"• ผักใบเขียว (คะน้า บรอกโคลี ผักโขม): กินสม่ำเสมอ ไม่ต้องงด แต่ห้ามเพิ่มกะทันหัน\\n• ห้ามซื้อ NSAIDs (ibuprofen, diclofenac) เอง\\n• ห้ามดื่มแอลกอฮอล์มาก\\n• น้ำเกรปฟรุต: อาจเพิ่ม level — หลีกเลี่ยง","storage":"≤ 25°C · ป้องกันแสง · แยก 3 mg (ฟ้า) กับ 5 mg (ชมพู) อย่างชัดเจน","drug_name":"(HAD) ฟ้า Warfarin","special_pop":"• Pregnancy Cat X — ห้ามใช้ขณะตั้งครรภ์ (teratogen)\\n• ผู้สูงอายุ: เสี่ยง bleeding สูง ใช้ dose ต่ำ\\n• โรคตับ: เพิ่ม INR มาก","full_counseling":"• กินยาเวลาเดิมทุกวัน ห้ามหยุดเอง (ลิ่มเลือดอุดตันได้)\\n• กินผักใบเขียวได้ตามปกติ แต่ต้องสม่ำเสมอ ห้ามเพิ่ม-ลดกะทันหัน\\n• ตรวจเลือด (INR) ตามนัดทุกครั้ง\\n• แจ้งทุกคนที่รักษา รวมทันตแพทย์และเภสัชกร ว่าใช้ยานี้\\n• ถ้าลืมกิน: กินทันทีที่นึกขึ้นได้ในวันเดิม ถ้าจำได้วันถัดไปแล้ว = ข้ามมื้อนั้น ห้ามกินสองเท่า","short_label":"3 mg ฟ้า / 5 mg ชมพู · ตรวจ INR ก่อนให้ · แจ้งยาทุกชนิด","when_to_er":"• เลือดออกผิดปกติ: ปัสสาวะสีชมพู/แดง · อุจจาระสีดำ · ช้ำง่ายผิดปกติ\\n• เลือดหยุดยากหลังบาดเจ็บ\\n• ปวดหัวรุนแรงทันที (intracranial hemorrhage)\\n• อ่อนแรงครึ่งซีก พูดไม่ชัด (stroke)","counseling_th":"• กินยาเวลาเดิมทุกวัน ห้ามหยุดเอง (ลิ่มเลือดอุดตันได้)\\n• กินผักใบเขียวได้ตามปกติ แต่ต้องสม่ำเสมอ ห้ามเพิ่ม-ลดกะทันหัน\\n• ตรวจเลือด (INR) ตามนัดทุกครั้ง\\n• แจ้งทุกคนที่รักษา รวมทันตแพทย์และเภสัชกร ว่าใช้ยานี้\\n• ถ้าลืมกิน: กินทันทีที่นึกขึ้นได้ในวันเดิม ถ้าจำได้วันถัดไปแล้ว = ข้ามมื้อนั้น ห้ามกินสองเท่า","icode":"1600020"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1600020_0', '1600020', '{"food_interaction":"• ผักใบเขียว (ผักบุ้ง คะน้า บร็อคโคลี่) กินสม่ำเสมอปริมาณเท่าเดิม\\n• น้ำส้มโอ มะม่วงสุก หลีกเลี่ยง\\n• แอลกอฮอล์ หลีกเลี่ยง","updatedAt":"2026-05-30T15:18:09.169Z","warning":"• เลือดออกหยุดไม่ได้, จ้ำเลือดตามตัว\\n• ปวดหัวรุนแรง ,แขนขาอ่อนแรงเฉียบพลัน","special_pop":"• ผู้สูงอายุ ≥75 ปี: เริ่มขนาดต่ำ เสี่ยงเลือดออกสูง\\n• ตั้งครรภ์: ห้ามใช้ในไตรมาส 1 และ 3","full_counseling":"• หากมีรับยาสถานพยาบาลอื่น โปรดแจ้งทุกครั้ง","drug_name":"Warfarin 3mg","icode":"1600020","when_to_er":"• เลือดออกหยุดไม่ได้, จ้ำเลือดตามตัว\\n• ปวดหัวรุนแรง ,แขนขาอ่อนแรงเฉียบพลัน","counseling_th":"• หากมีรับยาสถานพยาบาลอื่น โปรดแจ้งทุกครั้ง"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1600022', '1600022', '{"storage":"≤ 25°C · ป้องกันแสง · D5W เท่านั้น","drug_name":"Norepinephrine (HAD)","special_pop":"• Pregnancy Cat C\\n• ผู้ป่วย hypovolemia: แก้ไขก่อนให้ยาเสมอ\\n• ผู้ป่วย TCA: ระวัง HTN รุนแรง","full_counseling":"• ยาให้ผ่านเส้นเลือดโดยใช้ infusion pump\\n• ต้องมีการตรวจวัดความดันโลหิตอย่างต่อเนื่อง\\n• แจ้งพยาบาลทันทีถ้าบริเวณที่ให้ยามีอาการผิดปกติ","counseling_th":"• ยาให้ผ่านเส้นเลือดโดยใช้ infusion pump\\n• ต้องมีการตรวจวัดความดันโลหิตอย่างต่อเนื่อง\\n• แจ้งพยาบาลทันทีถ้าบริเวณที่ให้ยามีอาการผิดปกติ","short_label":"Infusion pump + Central line · ตรวจ IV site บ่อยๆ","when_to_er":"• ความดันโลหิตสูงผิดปกติมาก\\n• บริเวณ IV ซีดขาว เย็น (extravasation → necrosis)\\n• ปลายมือปลายเท้าเขียว ขาดเลือด","icode":"1600022","updatedAt":"2026-06-01T15:54:37.249Z"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1600026', '1600026', '{"icode":"1600026","counseling_th":"• ฉีดเข้าชั้นไขมันใต้ผิวหนังท้องส่วนล่าง ห่างสะดือ > 5 ซม.\\n• สลับตำแหน่งฉีดทุกครั้ง ซ้าย-ขวาสลับกัน\\n• ห้ามนวดบริเวณที่ฉีด (เพิ่มรอยช้ำ + ลด bioavailability)\\n• ห้ามดูดฟองอากาศออกก่อนฉีด (สูญเสียยา)\\n• แจ้งทุกคนที่รักษาว่าใช้ยานี้อยู่ (รวมทันตแพทย์)","when_to_er":"• เลือดออกผิดปกติ ช้ำง่าย มาก\\n• ปัสสาวะสีชมพู/แดง · อุจจาระสีดำ\\n• ปวดหลังรุนแรง + ชาขา (spinal hematoma)\\n• เกล็ดเลือดต่ำ — ไข้ เจ็บคอ (HIT)","short_label":"ฉีด SC ท้อง · ห้ามนวด · แจ้งทุกคนที่รักษา","storage":"≤ 25°C · ห้ามแช่แข็ง","special_pop":"• โรคไต (CrCl < 30): ปรับขนาดยา\\n• Pregnancy Cat C\\n• น้ำหนักน้อยมาก (< 45 kg หญิง): ↑ bleeding risk","full_counseling":"• ฉีดเข้าชั้นไขมันใต้ผิวหนังท้องส่วนล่าง ห่างสะดือ > 5 ซม.\\n• สลับตำแหน่งฉีดทุกครั้ง ซ้าย-ขวาสลับกัน\\n• ห้ามนวดบริเวณที่ฉีด (เพิ่มรอยช้ำ + ลด bioavailability)\\n• ห้ามดูดฟองอากาศออกก่อนฉีด (สูญเสียยา)\\n• แจ้งทุกคนที่รักษาว่าใช้ยานี้อยู่ (รวมทันตแพทย์)","drug_name":"Enoxaparin (HAD)","updatedAt":"2026-06-01T15:54:37.249Z","food_interaction":"• ห้ามซื้อ NSAIDs (ibuprofen, diclofenac) ร่วมกับยานี้เอง"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1600026_12', '1600026', '{"food_interaction":"• หลีกเลี่ยง NSAID และ Aspirin ถ้าไม่จำเป็น","updatedAt":"2026-05-30T15:18:09.169Z","warning":"• เลือดออกรุนแรงหยุดไม่ได้\\n• อาเจียนหรือถ่ายอุจจาระเป็นเลือด\\n• ปวดหัวรุนแรง แขนขาอ่อนแรง","side_effect":"• เลือดออกง่าย ฟกช้ำบริเวณฉีด\\n• เกล็ดเลือดต่ำ (HIT)\\n• ผื่นบริเวณฉีด","drug_name":"Enoxaparin sodium","special_pop":"• ไตเสื่อม eGFR<30: ต้องปรับขนาด\\n• ตั้งครรภ์: ใช้ได้ถ้าจำเป็น ปรึกษาแพทย์","full_counseling":"• ฉีดใต้ผิวหนังพุงบริเวณเอว เวียนตำแหน่งฉีด\\n• ห้ามถูหรือนวดบริเวณที่ฉีด\\n• แจ้งแพทย์ก่อนทำหัตถการหรือผ่าตัด","when_to_er":"• เลือดออกรุนแรงหยุดไม่ได้\\n• อาเจียนหรือถ่ายอุจจาระเป็นเลือด\\n• ปวดหัวรุนแรง แขนขาอ่อนแรง","counseling_th":"• ฉีดใต้ผิวหนังพุงบริเวณเอว เวียนตำแหน่งฉีด\\n• ห้ามถูหรือนวดบริเวณที่ฉีด\\n• แจ้งแพทย์ก่อนทำหัตถการหรือผ่าตัด","icode":"1600026"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1610009', '1610009', '{"updatedAt":"2026-06-01T15:54:37.249Z","icode":"1610009","counseling_th":"• กินยาวันละ 1 ครั้ง (ง่ายกว่า PTU)\\n• ถ้ามีไข้ เจ็บคอ — หยุดยา + ตรวจ CBC ด่วน\\n• ห้ามใช้ไตรมาส 1 ของการตั้งครรภ์ (aplasia cutis)\\n• ตรวจไทรอยด์สม่ำเสมอ","when_to_er":"• ไข้ เจ็บคอ (agranulocytosis)\\n• ผื่น ตุ่มพอง (SJS)\\n• ตัวเหลือง (hepatotoxicity)","short_label":"ไข้เจ็บคอ = หยุดยา+ตรวจ CBC ด่วน","special_pop":"• Pregnancy Cat D — ห้ามใน T1 (ใช้ PTU แทน)\\n• ห้ามให้นม","full_counseling":"• กินยาวันละ 1 ครั้ง (ง่ายกว่า PTU)\\n• ถ้ามีไข้ เจ็บคอ — หยุดยา + ตรวจ CBC ด่วน\\n• ห้ามใช้ไตรมาส 1 ของการตั้งครรภ์ (aplasia cutis)\\n• ตรวจไทรอยด์สม่ำเสมอ","drug_name":"meThimazole(*ชา)","storage":"≤ 25°C"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1610009_33', '1610009', '{"food_interaction":"• ยาอาจผ่านนมแม่ได้","updatedAt":"2026-05-30T15:18:09.169Z","warning":"• ไข้สูงกะทันหัน เจ็บคอ (agranulocytosis)\\n • ตัวเหลือง ตาเหลือง\\n • ผื่นรุนแรง","side_effect":"• ผื่น คัน\\n • เม็ดเลือดขาวต่ำ (ไข้ เจ็บคอ)\\n • ตับอักเสบ","drug_name":"Methimazole","special_pop":"• ตั้งครรภ์ไตรมาส 1: PTU ดีกว่า Methimazole\\n • ให้นมบุตร: ใช้ขนาดต่ำสุด","full_counseling":"• กินยาเวลาเดิมทุกวัน\\n • ห้ามหยุดยาเองเด็ดขาด\\n • ตรวจเลือด CBC ตามนัด","when_to_er":"• ไข้สูงกะทันหัน เจ็บคอ (agranulocytosis)\\n • ตัวเหลือง ตาเหลือง\\n • ผื่นรุนแรง","counseling_th":"• กินยาเวลาเดิมทุกวัน\\n • ห้ามหยุดยาเองเด็ดขาด\\n • ตรวจเลือด CBC ตามนัด","icode":"1610009"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1610011', '1610011', '{"food_interaction":"• ห้ามน้ำเกรปฟรุต\\n• ลดอาหารไขมันสัตว์","updatedAt":"2026-06-01T15:54:37.249Z","icode":"1610011","counseling_th":"• กินได้ทุกเวลา (Atorvastatin กินเวลาไหนก็ได้)\\n• ห้ามดื่มน้ำเกรปฟรุต\\n• ตรวจ LFT ตามนัด\\n• แจ้งทันทีถ้าปวดกล้ามเนื้อรุนแรง","when_to_er":"• ปวดกล้ามเนื้อรุนแรง กล้ามเนื้ออ่อนแรง ปัสสาวะสีน้ำตาลแดง (rhabdomyolysis)\\n• ตัวเหลือง","short_label":"ห้ามน้ำเกรปฟรุต · แจ้งถ้าปวดกล้ามเนื้อมาก","special_pop":"• Pregnancy Cat X — ห้ามใช้\\n• โรคตับ: ปรับขนาด","full_counseling":"• กินได้ทุกเวลา (Atorvastatin กินเวลาไหนก็ได้)\\n• ห้ามดื่มน้ำเกรปฟรุต\\n• ตรวจ LFT ตามนัด\\n• แจ้งทันทีถ้าปวดกล้ามเนื้อรุนแรง","drug_name":"Atorvastatin","storage":"≤ 30°C"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1610011_26', '1610011', '{"when_to_er":"• ปวดกล้ามเนื้อรุนแรง กล้ามเนื้อสลาย (ปัสสาวะสีน้ำตาล)\\n• ตัวเหลือง ตาเหลือง ปวดท้องมาก\\n• กล้ามเนื้ออ่อนแรงมาก","counseling_th":"• กินเวลาใดก็ได้ ไม่ต้องสัมพันธ์กับอาหาร\\n• กินยาสม่ำเสมอ แม้รู้สึกดีแล้ว\\n• ตรวจตับและ CK ตามนัด","icode":"1610011","drug_name":"Atorvastatin","full_counseling":"• กินเวลาใดก็ได้ ไม่ต้องสัมพันธ์กับอาหาร\\n• กินยาสม่ำเสมอ แม้รู้สึกดีแล้ว\\n• ตรวจตับและ CK ตามนัด","special_pop":"• ตั้งครรภ์: ห้ามใช้\\n• ตับเสื่อม: ห้ามใช้ หรือใช้ด้วยความระมัดระวัง","side_effect":"• ปวดกล้ามเนื้อ กล้ามเนื้ออ่อนแรง\\n• ตับอักเสบ\\n• ท้องอืด ปวดท้อง คลื่นไส้\\n• ปวดศีรษะ","food_interaction":"• น้ำส้มโอเพิ่มระดับยา ห้ามกิน\\n• แอลกอฮอล์เพิ่มความเสี่ยงตับ","warning":"• ปวดกล้ามเนื้อรุนแรง กล้ามเนื้อสลาย (ปัสสาวะสีน้ำตาล)\\n• ตัวเหลือง ตาเหลือง ปวดท้องมาก\\n• กล้ามเนื้ออ่อนแรงมาก","updatedAt":"2026-05-30T15:18:09.169Z"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1610023', '1610023', '{"updatedAt":"2026-06-01T15:54:37.249Z","storage":"หลังผสม: ≤ 4-8 ชม. ที่อุณหภูมิห้อง / 24 ชม. ตู้เย็น","drug_name":"MeROpenem","special_pop":"• Pregnancy Cat B\\n• โรคไต: ปรับขนาดตาม CrCl","full_counseling":"• ยาปฏิชีวนะชนิดแรง ให้ IV infuse 20-30 นาที\\n• ถ้าใช้ร่วมกับยากันชัก Valproate (Depakine) ต้องตรวจเลือดวัด level ยา\\n• Meropenem ลด Valproate level ได้ 60-100% → อาจชักได้","counseling_th":"• ยาปฏิชีวนะชนิดแรง ให้ IV infuse 20-30 นาที\\n• ถ้าใช้ร่วมกับยากันชัก Valproate (Depakine) ต้องตรวจเลือดวัด level ยา\\n• Meropenem ลด Valproate level ได้ 60-100% → อาจชักได้","short_label":"ใช้ภายใน 4-8 ชม. · ระวัง Valproate ↓ level","when_to_er":"• ชัก (ถ้าใช้ร่วม Valproate)\\n• ผื่นแพ้ยา\\n• ถ่ายเหลวรุนแรง (C. diff)","icode":"1610023"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1610027', '1610027', '{"icode":"1610027","counseling_th":"• ยาให้ทางเส้นเลือดเท่านั้น ต้องใช้ infusion pump\\n• ห้ามหยุดยาทันที ต้องค่อยๆ ลดขนาดลง\\n• แจ้งพยาบาลทันทีถ้าใจสั่น เจ็บหน้าอก หายใจลำบาก","when_to_er":"• ใจสั่นรุนแรง หัวใจเต้นผิดจังหวะ\\n• เจ็บแน่นหน้าอกนาน > 15 นาที\\n• หายใจลำบากมาก\\n• บริเวณ IV บวมแดง (extravasation)","short_label":"Infusion pump เท่านั้น · ห้ามหยุดทันที","special_pop":"• AF + RVR: ต้อง Digoxin ก่อน\\n• Pregnancy Cat B","full_counseling":"• ยาให้ทางเส้นเลือดเท่านั้น ต้องใช้ infusion pump\\n• ห้ามหยุดยาทันที ต้องค่อยๆ ลดขนาดลง\\n• แจ้งพยาบาลทันทีถ้าใจสั่น เจ็บหน้าอก หายใจลำบาก","drug_name":"Dobutamine HCL (HAD)","storage":"≤ 25°C · หลังผสมคงตัว 24 ชม. · สีชมพู = oxidation ปกติ","updatedAt":"2026-06-01T15:54:37.249Z"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1640026_37', '1640026', '{"updatedAt":"2026-05-30T15:18:09.169Z","warning":"• บวมหน้า ลิ้น คอ\\n • เจ็บหน้าอกอย่างรุนแรง\\n • ปัสสาวะยาก อาการแย่ลง","side_effect":"• สมรรถภาพทางเพศลดลง\\n • ปริมาณน้ำอสุจิลดลง\\n • หน้าอกโต (หายาก)","special_pop":"• สตรีตั้งครรภ์: ห้ามสัมผัสยาเด็ดขาด (ทำให้ทารกเพศชายพิการ)","full_counseling":"• กินยาวันละ 1 ครั้ง ไม่ต้องสัมพันธ์กับอาหาร\\n • กินยาสม่ำเสมอ อาจต้องกิน 6-12 เดือนกว่าจะเห็นผล\\n • ห้ามให้สตรีตั้งครรภ์สัมผัสยา","drug_name":"Finasteride","icode":"1640026","when_to_er":"• บวมหน้า ลิ้น คอ\\n • เจ็บหน้าอกอย่างรุนแรง\\n • ปัสสาวะยาก อาการแย่ลง","counseling_th":"• กินยาวันละ 1 ครั้ง ไม่ต้องสัมพันธ์กับอาหาร\\n • กินยาสม่ำเสมอ อาจต้องกิน 6-12 เดือนกว่าจะเห็นผล\\n • ห้ามให้สตรีตั้งครรภ์สัมผัสยา"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1640028_30', '1640028', '{"drug_name":"Carvedilol","full_counseling":"• กินพร้อมอาหาร\\n • ลุกนั่งช้าๆ ป้องกันความดันต่ำ\\n • ห้ามหยุดยาเองเด็ดขาด ต้องค่อยๆ ลด","special_pop":"• หอบหืด COPD: ระวังมาก อาจทำให้หลอดลมหดเกร็ง\\n • เบาหวาน: บัง hypoglycemia symptoms","when_to_er":"• HR น้อยกว่า 50 ครั้ง/นาที\\n • หายใจลำบากรุนแรง บวม\\n • ความดันต่ำมาก เป็นลม","counseling_th":"• กินพร้อมอาหาร\\n • ลุกนั่งช้าๆ ป้องกันความดันต่ำ\\n • ห้ามหยุดยาเองเด็ดขาด ต้องค่อยๆ ลด","icode":"1640028","food_interaction":"• แอลกอฮอล์เพิ่มฤทธิ์ลดความดัน","warning":"• HR น้อยกว่า 50 ครั้ง/นาที\\n • หายใจลำบากรุนแรง บวม\\n • ความดันต่ำมาก เป็นลม","updatedAt":"2026-05-30T15:18:09.169Z","side_effect":"• ความดันต่ำ เวียนหัว\\n • HR ช้า\\n • อ่อนเพลีย\\n • มือเท้าเย็น"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1640039', '1640039', '{"storage":"≤ 25°C · ป้องกันแสง · หลังผสมคงตัว 24 ชม.","drug_name":"NIcardipine HCL (HAD)","full_counseling":"• ยาลดความดันโลหิตสูง ต้องวัด BP ต่อเนื่อง\\n• ห้ามลุกขึ้นเร็ว (เวียนหัวได้)\\n• แจ้งพยาบาลถ้าปวดหัวมาก มองเห็นผิดปกติ อ่อนแรง","special_pop":"• Pregnancy Cat C\\n• โรคตับ: ลดขนาดยา\\n• Cyclosporine / Tacrolimus: monitor level (NiCard ↑ level 2-3x)","when_to_er":"• ความดันต่ำเกิน BP < 90/60 mmHg\\n• HR > 120 ครั้ง/นาที\\n• ชา อ่อนแรงครึ่งซีก (ระวังลด BP เร็วเกินใน stroke)","short_label":"Monitor BP ทุก 5-15 นาที · เปลี่ยน IV site ทุก 12 ชม.","counseling_th":"• ยาลดความดันโลหิตสูง ต้องวัด BP ต่อเนื่อง\\n• ห้ามลุกขึ้นเร็ว (เวียนหัวได้)\\n• แจ้งพยาบาลถ้าปวดหัวมาก มองเห็นผิดปกติ อ่อนแรง","icode":"1640039","updatedAt":"2026-06-01T15:54:37.249Z"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1640057_10', '1640057', '{"when_to_er":"• ปัสสาวะน้อยลงมาก หรือไม่มีปัสสาวะ\\n• หูอื้อรุนแรง หรือหูหนวกกะทันหัน\\n• วิงเวียนหมุนเวียน\\n• กล้ามเนื้ออ่อนแรง หายใจลำบาก","counseling_th":"• ฉีดโดยเจ้าหน้าที่เท่านั้น\\n• แจ้งแพทย์/เภสัชกรทันทีถ้ามีอาการผิดปกติ\\n• ตรวจไตและการได้ยินตามนัด","icode":"1640057","drug_name":"Amikacin sulfate","full_counseling":"• ฉีดโดยเจ้าหน้าที่เท่านั้น\\n• แจ้งแพทย์/เภสัชกรทันทีถ้ามีอาการผิดปกติ\\n• ตรวจไตและการได้ยินตามนัด","special_pop":"• ผู้ป่วยไตเสื่อม: ต้องปรับขนาด ติดตาม SCr\\n• ผู้สูงอายุ: เสี่ยงหูหนวกถาวร","side_effect":"• ไตเสียหาย (ปัสสาวะน้อย บวม)\\n• หูอื้อ ได้ยินลดลง\\n• วิงเวียน ทรงตัวไม่ดี\\n• คลื่นไส้ อาเจียน","food_interaction":"• หลีกเลี่ยง loop diuretic (Furosemide) ใช้ร่วมจะเพิ่มพิษ","warning":"• ปัสสาวะน้อยลงมาก หรือไม่มีปัสสาวะ\\n• หูอื้อรุนแรง หรือหูหนวกกะทันหัน\\n• วิงเวียนหมุนเวียน\\n• กล้ามเนื้ออ่อนแรง หายใจลำบาก","updatedAt":"2026-05-30T15:18:09.169Z"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1650037', '1650037', '{"updatedAt":"2026-06-01T15:54:37.249Z","food_interaction":"• ห้ามดื่มแอลกอฮอล์ (เพิ่ม hypotension)","icode":"1650037","counseling_th":"• ห้ามใช้ยาสมรรถภาพทางเพศ (Sildenafil/Viagra, Tadalafil/Cialis) ระหว่างใช้ยานี้ อันตรายถึงชีวิต\\n• อาจปวดหัวในช่วงแรก เป็นผลปกติ มักดีขึ้นเอง\\n• ถ้ารู้สึกหน้ามืดวิงเวียน นอนราบทันที\\n• ห้ามหยุดยาทันทีถ้าใช้มาสักระยะ (rebound angina)","when_to_er":"• ความดันต่ำมาก หน้ามืด เป็นลม\\n• เจ็บหน้าอกไม่ดีขึ้นหลังให้ยา\\n• ริมฝีปาก/เล็บเขียว (methemoglobinemia)","short_label":"ห้ามร่วม ไวอากร้า/ซิอาลิส · ปวดหัว=ปกติ","full_counseling":"• ห้ามใช้ยาสมรรถภาพทางเพศ (Sildenafil/Viagra, Tadalafil/Cialis) ระหว่างใช้ยานี้ อันตรายถึงชีวิต\\n• อาจปวดหัวในช่วงแรก เป็นผลปกติ มักดีขึ้นเอง\\n• ถ้ารู้สึกหน้ามืดวิงเวียน นอนราบทันที\\n• ห้ามหยุดยาทันทีถ้าใช้มาสักระยะ (rebound angina)","special_pop":"• Pregnancy Cat C\\n• Hypertrophic obstructive cardiomyopathy: CONTRAINDICATED","drug_name":"NITROGLYCERIN (HAD)","storage":"≤ 25°C · ป้องกันแสง · ห้าม PVC container"}');
INSERT INTO rxrule_drug_counseling (doc_id, icode, data) VALUES ('1680044', '1680044', '{"drug_name":"Vancomycin","special_pop":"• โรคไต: ปรับขนาดตาม CrCl + ตรวจ trough level\\n• ร่วม Aminoglycosides: ↑ nephrotoxicity + ototoxicity","full_counseling":"• ยาปฏิชีวนะสำหรับเชื้อดื้อยา ต้องให้ช้าๆ ≥ 60 นาที/500 mg\\n• ตรวจเลือดระหว่างรักษาสม่ำเสมอ\\n• แจ้งทันทีถ้าหน้าแดง ผื่นขึ้น (Red Man Syndrome — ลด rate)","storage":"≤ 25°C · หลังละลาย NSS/D5W เก็บได้ 14 วัน ตู้เย็น","counseling_th":"• ยาปฏิชีวนะสำหรับเชื้อดื้อยา ต้องให้ช้าๆ ≥ 60 นาที/500 mg\\n• ตรวจเลือดระหว่างรักษาสม่ำเสมอ\\n• แจ้งทันทีถ้าหน้าแดง ผื่นขึ้น (Red Man Syndrome — ลด rate)","short_label":"Infuse ≥ 60 นาที/500 mg · ตรวจ Cr + Trough level","when_to_er":"• ได้ยินเสียงหึ่งในหู ได้ยินเสียงลดลง (ototoxicity)\\n• ปัสสาวะน้อยลงมาก (nephrotoxicity)\\n• หน้าแดงผื่นขึ้นลามทั่วตัว คอ หน้าอก (Red Man Syndrome → ลด rate)","icode":"1680044","updatedAt":"2026-06-01T15:54:37.249Z"}');
INSERT INTO rxrule_warfarin_inr (doc_id, icode, data) VALUES ('inr_0', NULL, '{"note":"INR < 1.5 — เพิ่มขนาด 10–20%","vit_k":"","inr_max":1.49,"adjust_pct":15,"action":"increase","inr_min":0}');
INSERT INTO rxrule_warfarin_inr (doc_id, icode, data) VALUES ('inr_1', NULL, '{"note":"INR 1.5–1.9 — เพิ่มขนาด 5–10%","vit_k":"","inr_max":1.99,"adjust_pct":7.5,"action":"increase","inr_min":1.5}');
INSERT INTO rxrule_warfarin_inr (doc_id, icode, data) VALUES ('inr_2', NULL, '{"inr_min":2,"action":"maintain","adjust_pct":0,"inr_max":3,"note":"INR 2.0–3.0 — ในเป้าหมาย คงขนาดเดิม","vit_k":""}');
INSERT INTO rxrule_warfarin_inr (doc_id, icode, data) VALUES ('inr_3', NULL, '{"inr_max":3.9,"note":"INR 3.1–3.9 — ลดขนาด 5–10%","vit_k":"","action":"decrease","inr_min":3.1,"adjust_pct":7.5}');
INSERT INTO rxrule_warfarin_inr (doc_id, icode, data) VALUES ('inr_4', NULL, '{"inr_min":4,"action":"hold_1d","adjust_pct":10,"inr_max":4.9,"note":"INR 4.0–4.9 — หยุด 1 วัน แล้วลด 10%","vit_k":""}');
INSERT INTO rxrule_warfarin_inr (doc_id, icode, data) VALUES ('inr_5', NULL, '{"adjust_pct":0,"action":"omit_vitk","inr_min":5,"note":"INR 5.0–8.9 ไม่มีเลือดออก — งด 1–2 มื้อ","vit_k":"Vitamin K1 1 mg oral","inr_max":8.9}');
INSERT INTO rxrule_warfarin_inr (doc_id, icode, data) VALUES ('inr_6', NULL, '{"inr_min":9,"action":"omit_vitk","adjust_pct":0,"inr_max":99,"note":"INR ≥ 9.0 ไม่มีเลือดออก — งดยา","vit_k":"Vitamin K1 5–10 mg oral"}');
INSERT INTO rxrule_warfarin_twd (doc_id, icode, data) VALUES ('twd_3_12', NULL, '{"schedule_code":"0.5 จ-ส + 1 อา","twd_mg":12,"strength_mg":3,"description":"4 เม็ด"}');
