INSERT INTO rxrule_warfarin_twd (doc_id, icode, data) VALUES ('twd_3_19_5', NULL, '{"twd_mg":19.5,"schedule_code":"1 จ-ส + 0.5 อา","description":"6.5 เม็ด","strength_mg":3}');
