INSERT INTO rxrule_warfarin_twd (doc_id, icode, data) VALUES ('twd_3_22_5', NULL, '{"schedule_code":"1 จ-ส + 1.5 อา","twd_mg":22.5,"strength_mg":3,"description":"7.5 เม็ด"}');
INSERT INTO rxrule_warfarin_twd (doc_id, icode, data) VALUES ('twd_3_24', NULL, '{"schedule_code":"1 จ-ศ + 1.5 ส-อา","twd_mg":24,"strength_mg":3,"description":"8 เม็ด"}');
