INSERT INTO rxrule_ddi_override (doc_id, icode, data) VALUES ('1600020__1690111', NULL, '{"updatedAt":"2026-06-01T14:53:55.153Z","drug_a":"1600020","documentation":"1","severity":"major","onset":"D","mechanism":"Complex: displacement แล้วตาม CYP induction","local_note":"INR เปลี่ยนแปลงซับซ้อน (↑ แล้ว ↓)","drug_b":"1690111","recommendation":"Monitor INR สัปดาห์ละ 2 ครั้งช่วงแรก"}');
INSERT INTO rxrule_ddi_override (doc_id, icode, data) VALUES ('1600024__1680044', NULL, '{"drug_b":"1680044","local_note":"Hearing loss","onset":"D","mechanism":"Additive ototoxicity","recommendation":"Monitor audiometry ถ้าใช้ร่วมนาน","severity":"moderate","documentation":"2","updatedAt":"2026-06-01T14:53:55.153Z","drug_a":"1600024"}');
INSERT INTO rxrule_ddi_override (doc_id, icode, data) VALUES ('1610023__1680036', NULL, '{"drug_b":"1680036","local_note":"Valproate level ↓ 60-100% → breakthrough seizure — Clinically critical — common scenario in ICU/ward","onset":"D","mechanism":"Meropenem ลด valproate absorption + ↑ metabolism","recommendation":"Monitor valproate level ทุก 24-48 ชม.; พิจารณา alternative antibiotic","severity":"major","documentation":"1","updatedAt":"2026-06-01T14:53:55.153Z","drug_a":"1610023"}');
INSERT INTO rxrule_ddi_override (doc_id, icode, data) VALUES ('1680036__1690111', NULL, '{"recommendation":"ตรวจ FREE phenytoin level; ระวัง ataxia","local_note":"Free phenytoin ↑ → toxicity (total level ดูเหมือนปกติ)","drug_b":"1690111","onset":"D","mechanism":"Protein displacement + CYP2C9 inhibition","severity":"major","documentation":"1","drug_a":"1680036","updatedAt":"2026-06-01T14:53:55.153Z"}');
INSERT INTO rxrule_ddi_override (doc_id, icode, data) VALUES ('Warfarin__rifampicin', NULL, '{"updatedAt":"2026-05-30T15:22:29.397Z","severity":"moderate","drug_a":"Warfarin","drug_b":"rifampicin","local_note":"-กรณี มีการเริ่มยา Rifampicin อาจต้อง ปรับเพิ่มขนาดยา warfarin 100-200% ในช่วง 1-2 สัปดาห์แรก โดยพิจารณา เพิ่มขนาดยาครั้งละ 2.5 mg/วัน จนกว่า ค่า INR เข้าเป้าหมาย  -กรณีหยุดยา Rifampicin พิจารณา ปรับ ลดขนาดยา warfarin ลง 50% ของขนาด ยาสุดท้าย ในช่วง 1-2 สัปดาห์แรก และมี การติดตาม INR อย่างใกล้ชิด ","mechanism":"ลดผล anticoagulant ของ warfarin ","recommendation":""}');
INSERT INTO rxrule_ddi_override (doc_id, icode, data) VALUES ('acetaminophen__warfarin', NULL, '{"drug_b":"Warfarin","local_note":"Paracetamol >1.3-2g/day ติดต่อกันหลายวัน เพิ่มฤทธิ์ anticoagulant Warfarin — ติดตาม INR โดยเฉพาะเมื่อใช้ต่อเนื่อง","drug_a":"Acetaminophen","updatedAt":"2026-05-30T15:18:10.349Z","severity":"moderate"}');
INSERT INTO rxrule_ddi_override (doc_id, icode, data) VALUES ('amitriptyline__haloperidol', NULL, '{"drug_b":"Haloperidol","local_note":"ใช้ร่วมกันเพิ่มความเสี่ยง QT prolongation และหัวใจเต้นผิดจังหวะ","drug_a":"Amitriptyline","updatedAt":"2026-05-30T15:18:10.349Z","severity":"moderate"}');
INSERT INTO rxrule_ddi_override (doc_id, icode, data) VALUES ('amlodipine__simvastatin', NULL, '{"drug_b":"Simvastatin","local_note":"หากใช้ร่วมกัน ให้ใช้ max dose simvastatin 20 mg กับ Amlodipine 10 mg","drug_a":"Amlodipine","updatedAt":"2026-05-30T15:18:10.349Z","severity":"major"}');
INSERT INTO rxrule_ddi_override (doc_id, icode, data) VALUES ('amoxicillin_clavulanate__warfarin', NULL, '{"updatedAt":"2026-05-30T15:18:10.349Z","severity":"moderate","drug_a":"Amoxicillin+Clavulanate","drug_b":"Warfarin","local_note":"Penicillin อาจเพิ่มฤทธิ์ anticoagulant Warfarin — ติดตาม INR เมื่อเริ่มหรือหยุดยา"}');
