INSERT INTO rxrule_ddi_override (doc_id, icode, data) VALUES ('azithromycin__warfarin', NULL, '{"drug_b":"Warfarin","local_note":"Azithromycin (Macrolide) เพิ่มฤทธิ์ anticoagulant Warfarin — ติดตาม INR เมื่อเริ่มหรือหยุดยา","drug_a":"Azithromycin","updatedAt":"2026-05-30T15:18:10.349Z","severity":"moderate"}');
INSERT INTO rxrule_ddi_override (doc_id, icode, data) VALUES ('chlorpromazine__propranolol', NULL, '{"updatedAt":"2026-05-30T18:03:48.687Z","drug_a":"Chlorpromazine","documentation":"2","severity":"major","onset":"D","mechanism":"Mutual metabolism inhibition (first-pass) → ระดับยาทั้งคู่สูงขึ้น","local_note":"เพิ่มเสี่ยงพิษ — หัวใจเต้นผิดจังหวะ/หยุดเต้น","drug_b":"Propranolol","recommendation":"ลดขนาดยา · ติดตาม pulse rate (60-100) · EKG ถ้าผิดปกติ"}');
