INSERT INTO rxrule_ddi_override (doc_id, icode, data) VALUES ('digoxin__amiodarone', NULL, '{"drug_b":"Amiodarone","local_note":"เพิ่มระดับ Digoxin 50-100% เสี่ยง Digoxin toxicity ลด dose Digoxin ลงครึ่งหนึ่ง","updatedAt":"2026-05-30T15:18:10.349Z","severity":"major","drug_a":"Digoxin"}');
