INSERT INTO rxrule_ddi_override (doc_id, icode, data) VALUES ('digoxin__furosemide', NULL, '{"drug_b":"Furosemide","local_note":"Furosemide ทำให้ K+ ต่ำ เพิ่มพิษ Digoxin ต้องติดตาม K+ และ Digoxin level","updatedAt":"2026-05-30T15:18:10.349Z","severity":"major","drug_a":"Digoxin"}');
INSERT INTO rxrule_ddi_override (doc_id, icode, data) VALUES ('efavirenz__warfarin', NULL, '{"drug_b":"Warfarin","local_note":"Efavirenz อาจลดหรือเพิ่มระดับ Warfarin (ผลทั้งสองทิศ) — ติดตาม INR อย่างใกล้ชิดเมื่อเริ่มหรือหยุด EFV","drug_a":"Efavirenz","updatedAt":"2026-05-30T15:18:10.349Z","severity":"moderate"}');
INSERT INTO rxrule_ddi_override (doc_id, icode, data) VALUES ('ergotamine__azithromycin', NULL, '{"severity":"contraindicated","recommendation":"ห้ามใช้ร่วมกัน — Roxithromycin แม้ weak ยังต้องเลี่ยง","onset":"R","mechanism":"Macrolide = Strong/Moderate CYP3A4 inhibitor (Roxithromycin = weak)","drug_b":"Azithromycin","local_note":"🚨 Fatal — ergotism, peripheral vasoconstriction → gangrene","drug_a":"Ergotamine","updatedAt":"2026-05-30T18:03:48.687Z","documentation":"2"}');
INSERT INTO rxrule_ddi_override (doc_id, icode, data) VALUES ('ergotamine__clarithromycin', NULL, '{"drug_a":"Ergotamine","updatedAt":"2026-05-30T18:03:48.687Z","documentation":"2","severity":"contraindicated","recommendation":"ห้ามใช้ร่วมกัน — Roxithromycin แม้ weak ยังต้องเลี่ยง","drug_b":"Clarithromycin","local_note":"🚨 Fatal — ergotism, peripheral vasoconstriction → gangrene","onset":"R","mechanism":"Macrolide = Strong/Moderate CYP3A4 inhibitor (Roxithromycin = weak)"}');
INSERT INTO rxrule_ddi_override (doc_id, icode, data) VALUES ('ergotamine__efavirenz', NULL, '{"severity":"contraindicated","onset":"D","mechanism":"Moderate CYP3A4 inhibition → ergot toxicity","drug_b":"Efavirenz","local_note":"🚨 Fatal drug interaction","recommendation":"ห้ามใช้ร่วมกัน — consult แพทย์","updatedAt":"2026-05-30T18:03:48.687Z","drug_a":"Ergotamine","documentation":"3"}');
INSERT INTO rxrule_ddi_override (doc_id, icode, data) VALUES ('ergotamine__erythromycin', NULL, '{"updatedAt":"2026-05-30T18:03:48.687Z","drug_a":"Ergotamine","documentation":"2","severity":"contraindicated","drug_b":"Erythromycin","local_note":"🚨 Fatal — ergotism, peripheral vasoconstriction → gangrene","onset":"R","mechanism":"Macrolide = Strong/Moderate CYP3A4 inhibitor (Roxithromycin = weak)","recommendation":"ห้ามใช้ร่วมกัน — Roxithromycin แม้ weak ยังต้องเลี่ยง"}');
INSERT INTO rxrule_ddi_override (doc_id, icode, data) VALUES ('ergotamine__indinavir', NULL, '{"severity":"contraindicated","recommendation":"ห้ามใช้ร่วมกัน — consult แพทย์เปลี่ยนเป็นยาตัวอื่น","mechanism":"PI = Strong CYP3A4 inhibitor → รบกวน hepatic metabolism ของ Ergot → ergotism","onset":"D","local_note":"🚨 Fatal drug interaction — vasoconstriction → peripheral gangrene","drug_b":"Indinavir","drug_a":"Ergotamine","updatedAt":"2026-05-30T18:03:48.687Z","documentation":"2"}');
