INSERT INTO rxrule_ddi_override (doc_id, icode, data) VALUES ('ergotamine__ritonavir', NULL, '{"severity":"contraindicated","recommendation":"ห้ามใช้ร่วมกัน — consult แพทย์เปลี่ยนเป็นยาตัวอื่น","onset":"D","mechanism":"PI = Strong CYP3A4 inhibitor → รบกวน hepatic metabolism ของ Ergot → ergotism","local_note":"🚨 Fatal drug interaction — vasoconstriction → peripheral gangrene","drug_b":"Ritonavir","drug_a":"Ergotamine","updatedAt":"2026-05-30T18:03:48.687Z","documentation":"2"}');
