INSERT INTO rxrule_ddi_override (doc_id, icode, data) VALUES ('methylergonovine__azithromycin', NULL, '{"documentation":"2","drug_a":"Methylergonovine","updatedAt":"2026-05-30T18:03:48.687Z","recommendation":"ห้ามใช้ร่วมกัน — Roxithromycin แม้ weak ยังต้องเลี่ยง","drug_b":"Azithromycin","local_note":"🚨 Fatal — ergotism, peripheral vasoconstriction → gangrene","onset":"R","mechanism":"Macrolide = Strong/Moderate CYP3A4 inhibitor (Roxithromycin = weak)","severity":"contraindicated"}');
