INSERT INTO rxrule_ddi_override (doc_id, icode, data) VALUES ('methylergonovine__indinavir', NULL, '{"drug_b":"Indinavir","local_note":"🚨 Fatal drug interaction — vasoconstriction → peripheral gangrene","onset":"D","mechanism":"PI = Strong CYP3A4 inhibitor → รบกวน hepatic metabolism ของ Ergot → ergotism","recommendation":"ห้ามใช้ร่วมกัน — consult แพทย์เปลี่ยนเป็นยาตัวอื่น","severity":"contraindicated","documentation":"2","updatedAt":"2026-05-30T18:03:48.687Z","drug_a":"Methylergonovine"}');
