INSERT INTO rxrule_ddi_override (doc_id, icode, data) VALUES ('warfarin__rifampicin', NULL, '{"drug_a":"Warfarin","updatedAt":"2026-05-30T18:03:48.687Z","documentation":"3","severity":"major","recommendation":"เริ่ม Rifampicin → เพิ่ม warfarin 100-200% ครั้งละ 2.5 mg/วัน ใน 1-2 สัปดาห์แรก · หยุด Rifampicin → ลด warfarin 50% · ติดตาม INR ใกล้ชิด","onset":"D","mechanism":"CYP induction → ลดผล anticoagulant","local_note":"ลดผล warfarin","drug_b":"Rifampicin"}');
